INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('96-zenkoku-koukou-soccer-senshuken-japan', 'SNES', '96 Zenkoku Koukou Soccer Senshuken (Japan)', '1996', 'Sports', 'Konami', '2', 'Soccer simulation', '2D soccer simulation with realistic high school tournament rules.', 'Win the All Japan High School Soccer Tournament.', 'Relive the 1996 Japanese high school soccer season on SNES.', '96 Zenkoku Koukou Soccer Senshuken brings authentic high school football to the SNES with deep tournament modes and team management features for sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the', 'SNES', 'the', '0', 'Platformer', 'ROM Hack', '1', 'Fan-made platformer', 'unknown', 'unknown', 'unknown', 'unknown');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('100-rooms-of-enemies-by-daizo-dee-von', 'SNES', '100 Rooms of Enemies by Daizo Dee Von', '1993', 'Action', 'Homebrew', '1', 'Arcade action', 'Hardcore combat-focused platforming in a series of closed arenas.', 'Defeat every single enemy in 100 increasingly difficult rooms.', 'Master intense combat in 100 Rooms of Enemies, a challenging SNES hack.', 'A grueling test of skill, 100 Rooms of Enemies requires players to clear 100 unique stages filled with enemies using precise platforming and combat mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2020-super-baseball-japan', 'SNES', '2020 Super Baseball (Japan)', '1991', 'Sports', 'Palsoft', '2', 'Baseball simulation', 'Futuristic arcade baseball with power-ups and robotic players.', 'Outscore the opposing team in a high-tech baseball league.', 'Play futuristic 16-bit baseball in 2020 Super Baseball for SNES.', 'Step into the future of sports with 2020 Super Baseball. Featuring cybernetic upgrades and unique stadium rules, it''s a high-octane take on America''s favorite pastime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2020-super-baseball-usa', 'SNES', '2020 Super Baseball (USA)', '1991', 'Sports', 'Palsoft', '2', 'Baseball simulation', 'Futuristic arcade baseball with power-ups and robotic players.', 'Outscore the opposing team in a high-tech baseball league.', 'Play futuristic 16-bit baseball in 2020 Super Baseball for SNES.', 'Step into the future of sports with 2020 Super Baseball. Featuring cybernetic upgrades and unique stadium rules, it''s a high-octane take on America''s favorite pastime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3-jigen-kakutou-ballz-japan', 'SNES', '3 Jigen Kakutou Ballz (Japan)', '1995', 'Fighting', 'Banpresto', '2', 'Anime fighting', '1-on-1 fighting game using characters made of individual spheres.', 'Defeat all opponents in martial arts combat to prove supremacy.', 'Experience the unique sphere-based combat of Ballz on the SNES.', '3 Jigen Kakutou Ballz features a distinct visual style with fighters composed of balls. Master its physics-based combat system in this eccentric 16-bit fighting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3-ninjas-kick-back-usa', 'SNES', '3 Ninjas Kick Back (USA)', '1994', 'Action Platformer', 'Culture Brain', '2', 'Side-scrolling action', 'Side-scrolling action platformer based on the martial arts film.', 'Rescue your grandfather by fighting through ninja-infested levels.', 'Join the three brothers in 3 Ninjas Kick Back for SNES action.', 'Based on the hit movie, 3 Ninjas Kick Back lets you play as Rocky, Colt, or Tum-Tum. Use ninja skills and weapons to defeat the ancient Koga and save your mentor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3000-leagues-in-search-of-bowser---mario-edition-final', 'SNES', '3000 Leagues in Search of Bowser - Mario Edition (Final)', '2023', 'Adventure', 'ROM Hack', '1', 'Narrative adventure', 'Complex side-scrolling platforming with custom level mechanics.', 'Navigate a massive world to find and defeat Bowser.', 'Embark on an epic quest in 3000 Leagues in Search of Bowser for SNES.', 'This Mario Edition overhaul offers an expansive new world to explore. Navigate through challenging custom levels and hidden paths to stop Bowser''s latest scheme.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3000-leagues-in-search-of-bowser---touhou-edition-english-v254', 'SNES', '3000 Leagues in Search of Bowser - Touhou Edition (English) (V2.54)', '2023', 'Adventure', 'ROM Hack', '1', 'Narrative adventure', 'Platforming with Touhou-inspired characters and bullet-hell elements.', 'Complete the journey across the world to stop Bowser''s plot.', 'Play a unique Touhou crossover in 3000 Leagues in Search of Bowser.', 'This Touhou Edition hack merges anime-style characters with classic Mario platforming. Experience custom music, graphics, and high-difficulty gameplay on your SNES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3x3-eyes---juuma-houkan-japan', 'SNES', '3x3 Eyes - Juuma Houkan (Japan)', '1992', 'RPG', 'Novia', '1', 'Turn-based RPG', 'Turn-based RPG and adventure with supernatural horror themes.', 'Stop a demon invasion and protect the Sanjiyan''s immortality.', 'Explore a dark anime world in 3x3 Eyes - Juuma Houkan for SNES.', 'Based on the 3x3 Eyes manga, this title combines RPG exploration with an atmospheric story. Fight demons and solve puzzles to protect the secret of eternal life.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3x3-eyes---seima-kourinden-japan', 'SNES', '3x3 Eyes - Seima Kourinden (Japan)', '1995', 'RPG', 'Novia', '1', 'Turn-based RPG', 'Traditional turn-based JRPG with cinematic narrative sequences.', 'Travel across Asia to recover lost artifacts and protect Pai.', 'Follow the epic story of Yakumo and Pai in 3x3 Eyes for SNES.', 'A faithful RPG adaptation of the 3x3 Eyes series. Manage your party, master spells, and experience a deep storyline filled with ancient mysticism and demon battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('4-nin-shougi-japan', 'SNES', '4 Nin Shougi (Japan)', '1995', 'Board Game', 'SETA', '2', 'Traditional board game', 'Strategic board game simulation of traditional Japanese chess.', 'Outmaneuver the opponent to capture their King.', 'Master the strategy of 4 Nin Shougi on the SNES.', 'Enjoy the classic game of Shogi with up to four players. 4 Nin Shougi provides a challenging AI and various modes for fans of Japanese strategic board games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('46-okunen-monogatari---harukanaru-eden-e-japan', 'SNES', '46 Okunen Monogatari - Harukanaru Eden e (Japan)', '1992', 'RPG', 'Almanic', '1', 'Evolution RPG', 'Evolutionary action-RPG where the player evolves through eras.', 'Evolve from a fish to a human to reach the Garden of Eden.', 'Shape your own evolution in 46 Okunen Monogatari for SNES.', 'Known as E.V.O.: Search for Eden, this unique RPG lets you customize your creature''s body as you struggle for survival across millions of years of history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('7th-saga-the-usa', 'SNES', '7th Saga, The (USA)', '1993', 'RPG', 'Produce!', '1', 'Turn-based RPG', 'Turn-based RPG with a unique radar system and high difficulty.', 'Collect the seven mystical runes to inherit the power of a god.', 'Experience the punishing challenge of The 7th Saga on SNES.', 'Select one of seven heroes and compete against the others in a race for the runes. The 7th Saga is famous for its steep difficulty and innovative combat radar.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('7th-saga-the-usa-hack-by-james-skarzinskas-v10-elnards-balance-restauration', 'SNES', '7th Saga, The (USA) [Hack by James Skarzinskas v1.0] (Elnard''s Balance Restauration)', '1993', 'RPG', 'ROM Hack', '1', 'Rebalanced RPG', 'Rebalanced turn-based RPG with restored Japanese difficulty stats.', 'Complete the quest for the runes with more fair gameplay.', 'Play the balanced version of The 7th Saga with this SNES hack.', 'This restoration hack adjusts the difficulty curve of The 7th Saga to match the original Japanese version, providing a more balanced and enjoyable RPG experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('7th-saga-the-usa-hack-by-nati-v10-~7th-saga-redux', 'SNES', '7th Saga, The (USA) [Hack by Nati v1.0] (~7th Saga Redux)', '1993', 'RPG', 'ROM Hack', '1', 'Rebalanced RPG', 'Overhauled turn-based RPG with new mechanics and character tweaks.', 'Secure the seven runes in this refined version of the classic game.', 'Experience a fresh take on a classic with 7th Saga Redux for SNES.', '7th Saga Redux improves character viability and balance. Enjoy the same epic story with polished gameplay mechanics and updated difficulty scaling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('90-minutes---european-prime-goal-europe', 'SNES', '90 Minutes - European Prime Goal (Europe)', '1992', 'Sports', 'Taito', '2', 'Soccer simulation', 'Fast-paced European soccer simulation with arcade physics.', 'Lead your team to victory in the European Prime Goal tournament.', 'Get on the pitch with 90 Minutes - European Prime Goal for SNES.', 'Experience the speed of European football. 90 Minutes features intuitive controls, multiple team selections, and intense 16-bit soccer action for sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('90-minutes---european-prime-goal-europe-beta', 'SNES', '90 Minutes - European Prime Goal (Europe) (Beta)', '1992', 'Sports', 'Taito', '2', 'Soccer simulation', 'Early prototype of the soccer simulation with experimental features.', 'Test the soccer mechanics and win the experimental cup.', 'Explore a piece of gaming history with the 90 Minutes Beta.', 'This beta version of 90 Minutes - European Prime Goal offers a look at the game''s development, featuring early builds of the mechanics and team rosters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('a-journey-to-save-the-yoshis-by-yoshivert99', 'SNES', 'A Journey To Save The Yoshis by Yoshivert99', '2022', 'Platformer', 'Homebrew', '1', 'Fan-made platformer', 'Creative platformer featuring custom mechanics for Yoshi.', 'Navigate through custom worlds to rescue the Yoshi clan.', 'Explore a new Yoshi adventure in A Journey To Save The Yoshis.', 'A vibrant and creative hack of Super Mario World starring Yoshi. Use unique power-ups and clever level design to save your friends in this community favorite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('a-link-to-the-past:-kaizo-edition', 'SNES', 'A Link to the Past: Kaizo Edition', '2021', 'Action Platformer', 'ROM Hack', '1', 'Kaizo-style platformer', 'Extremely difficult puzzle-platformer built on the Zelda engine.', 'Complete the lethal dungeons and rescue Princess Zelda.', 'Test your limits in A Link to the Past: Kaizo Edition.', 'This is not the Hyrule you remember. Kaizo Edition turns Zelda into a brutal gauntlet of traps and precision puzzles that will challenge the most veteran players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aaahh!!!-real-monsters-europe', 'SNES', 'AAAHH!!! Real Monsters (Europe)', '1995', 'Platformer', 'Realtime Associates', '2', 'Cartoon platformer', 'Platformer where players switch between three monsters with unique abilities.', 'Complete the monster scare assignments to pass the Academy exams.', 'Scare humans and solve puzzles in AAAHH!!! Real Monsters for SNES.', 'Based on the Nickelodeon hit, control Ickis, Krumm, and Oblina. Use their combined teamwork and gross-out scares to navigate through trash heaps and human cities in this 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aaahh!!!-real-monsters-usa', 'SNES', 'AAAHH!!! Real Monsters (USA)', '1995', 'Platformer', 'Realtime Associates', '2', 'Cartoon platformer', 'Platformer where players switch between three monsters with unique abilities.', 'Complete the monster scare assignments to pass the Academy exams.', 'Scare humans and solve puzzles in AAAHH!!! Real Monsters for SNES.', 'Based on the Nickelodeon hit, control Ickis, Krumm, and Oblina. Use their combined teamwork and gross-out scares to navigate through trash heaps and human cities in this 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('abc-monday-night-football-japan', 'SNES', 'ABC Monday Night Football (Japan)', '1993', 'Sports', 'Data East', '2', 'American football', 'Arcade-style American football simulation with high-energy presentation.', 'Win the Super Bowl by leading your team through the Monday Night season.', 'Experience 16-bit gridiron action in ABC Monday Night Football for SNES.', 'Featuring the official ABC license, this football title offers fast-paced gameplay, multiple formations, and the excitement of prime-time sports broadcasting on your Super Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('abc-monday-night-football-usa', 'SNES', 'ABC Monday Night Football (USA)', '1993', 'Sports', 'Data East', '2', 'American football', 'Arcade-style American football simulation with high-energy presentation.', 'Win the Super Bowl by leading your team through the Monday Night season.', 'Experience 16-bit gridiron action in ABC Monday Night Football for SNES.', 'Featuring the official ABC license, this football title offers fast-paced gameplay, multiple formations, and the excitement of prime-time sports broadcasting on your Super Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('accele-brid-japan', 'SNES', 'Accele Brid (Japan)', '1992', 'Shoot ''em up', 'Naxat Soft', '1', 'Vertical shooter', 'A futuristic behind-the-back racing game combined with robot combat.', 'Defeat opponents in high-speed races and combat to win the championship.', 'Battle and race in the futuristic world of Accele Brid on SNES.', 'A unique hybrid of racing and shooter. Control a giant mecha through 3D tunnels, upgrading your weapons and speed to overcome rivals in this Japanese cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('accele-brid-japan-en-by-aeon-genesis-v10', 'SNES', 'Accele Brid (Japan) [En by Aeon Genesis v1.0]', '1992', 'Shoot ''em up', 'Naxat Soft', '1', 'Vertical shooter', 'A futuristic behind-the-back racing game combined with robot combat.', 'Defeat opponents in high-speed races and combat to win the championship.', 'Play the English translated version of Accele Brid, a SNES racing-combat gem.', 'Now fully playable in English, this translation allows you to follow the story and upgrade system as you race your mecha through intense, futuristic corridors and boss battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ace-o-nerae!-japan', 'SNES', 'Ace o Nerae! (Japan)', '1993', 'Sports', 'Taito', '2', 'Anime tennis', 'Anime-style tennis simulation with story elements and special moves.', 'Rise through the ranks to become a world-class tennis champion.', 'Experience anime-style sports in Ace o Nerae! for the Super Famicom.', 'Based on the famous "Aim for the Ace!" manga. This tennis game features cinematic shots, dramatic story beats, and deep tennis mechanics that capture the spirit of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ace-o-nerae!-japan-en-by-rpgone-v12-~aim-for-the-ace!---ace-tennis', 'SNES', 'Ace o Nerae! (Japan) [En by RPGOne v1.2] (~Aim for the Ace! - Ace Tennis)', '1993', 'Sports', 'Taito', '2', 'Anime tennis', 'Anime-style tennis simulation with story elements and special moves.', 'Rise through the ranks to become a world-class tennis champion.', 'Play the English translation of Aim for the Ace! Tennis on SNES.', 'Experience the dramatic story of Hiromi Oka in English. This RPG-sports hybrid combines competitive tennis gameplay with the emotional narrative of the classic anime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('acme-animation-factory-europe', 'SNES', 'ACME Animation Factory (Europe)', '1994', 'Creation Software', 'Probe Entertainment', '1', 'Animation tool', 'A creative suite featuring animation tools, music composition, and mini-games.', 'Create your own Looney Tunes cartoons and play themed activities.', 'Get creative with the Looney Tunes in ACME Animation Factory for SNES.', 'A digital playground for kids. Use Looney Tunes characters to animate scenes, compose MIDI-style music, and play various puzzles in this creative ACME toolkit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('acme-animation-factory-usa', 'SNES', 'ACME Animation Factory (USA)', '1994', 'Creation Software', 'Probe Entertainment', '1', 'Animation tool', 'A creative suite featuring animation tools, music composition, and mini-games.', 'Create your own Looney Tunes cartoons and play themed activities.', 'Get creative with the Looney Tunes in ACME Animation Factory for SNES.', 'A digital playground for kids. Use Looney Tunes characters to animate scenes, compose MIDI-style music, and play various puzzles in this creative ACME toolkit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('acrobat-mission-japan', 'SNES', 'Acrobat Mission (Japan)', '1992', 'Shoot ''em up', 'Ukiyotei', '1', 'Vertical shooter', 'Vertical-scrolling shoot ''em up with a unique weapon-stealing mechanic.', 'Fly through enemy lines and destroy the bio-mechanical invaders.', 'Battle through space in the intense shooter Acrobat Mission on SNES.', 'A classic arcade port featuring a risk-reward system where your ship can cause massive damage when destroyed. Navigate through challenging levels and epic boss fights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('action-pachio-japan', 'SNES', 'Action Pachio (Japan)', '1994', 'Arcade', 'Namco', '1', 'Pachinko simulation', 'Side-scrolling platformer starring a mascot character with high agility.', 'Navigate through colorful levels to stop the corporate villain.', 'Enjoy fast-paced 16-bit platforming with Action Pachio on SNES.', 'A hidden gem from the creators of Umihara Kawase. Play as a small mechanical hero with unique physics, exploring vibrant worlds filled with secrets and tight controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('actraiser-europe', 'SNES', 'ActRaiser (Europe)', '1993', 'Action / Simulation', 'Quintet', '1', 'Action god game', 'A unique blend of city-building simulation and side-scrolling action.', 'Rebuild civilization as a god and defeat the evil Tanzra.', 'Play the legendary god-sim and action hybrid ActRaiser on SNES.', 'Assume the role of The Master. Alternate between overhead city management to help your followers and intense platforming combat to purge the land of demons.');
