INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('actraiser-japan-en-by-aeon-genesis-v10', 'SNES', 'ActRaiser (Japan) [En by Aeon Genesis v1.0]', '1993', 'Action / Simulation', 'Quintet', '1', 'Action god game', 'A unique blend of city-building simulation and side-scrolling action.', 'Rebuild civilization as a god and defeat the evil Tanzra.', 'Play ActRaiser in English with the Japanese difficulty and balance.', 'This fan translation restores the original Japanese experience, featuring the higher difficulty and mechanical nuances that were altered in the Western releases.');
