INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('actraiser-2---chinmoku-e-no-seisen-japan', 'SNES', 'ActRaiser 2 - Chinmoku e no Seisen (Japan)', '1993', 'Action Platformer', 'Quintet', '1', 'Dark fantasy platformer', 'Hardcore side-scrolling action platformer with an emphasis on wings and magic.', 'Defeat the seven deadly sins to save humanity from darkness.', 'Experience the challenging action of ActRaiser 2 on the SNES.', 'Moving away from the city-building of the first game, the sequel focuses on pure, high-difficulty action. Use your wings to glide and strike down monsters in beautiful, gothic environments.');
