INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('actraiser-2-usa', 'SNES', 'ActRaiser 2 (USA)', '1993', 'Action Platformer', 'Quintet', '1', 'Dark fantasy platformer', 'Hardcore side-scrolling action platformer with an emphasis on wings and magic.', 'Defeat the seven deadly sins to save humanity from darkness.', 'Experience the challenging action of ActRaiser 2 on the SNES.', 'Moving away from the city-building of the first game, the sequel focuses on pure, high-difficulty action. Use your wings to glide and strike down monsters in beautiful, gothic environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('addams-family-values-europe-enfrde', 'SNES', 'Addams Family Values (Europe) (En,Fr,De)', '1995', 'Action Platformer', 'Ocean Software', '1', 'Cinematic platformer', 'Action-adventure game with an overhead perspective and puzzle elements.', 'Explore the world to find and rescue the kidnapped baby Pubert.', 'Join the spooky family in Addams Family Values for the SNES.', 'Based on the sequel film, play as Uncle Fester in a vast, interconnected world. Use different weapons and items to solve puzzles, talk to family members, and defeat bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('addams-family-values-usa-enfrde', 'SNES', 'Addams Family Values (USA) (En,Fr,De)', '1995', 'Action Platformer', 'Ocean Software', '1', 'Cinematic platformer', 'Action-adventure game with an overhead perspective and puzzle elements.', 'Explore the world to find and rescue the kidnapped baby Pubert.', 'Join the spooky family in Addams Family Values for the SNES.', 'Based on the sequel film, play as Uncle Fester in a vast, interconnected world. Use different weapons and items to solve puzzles, talk to family members, and defeat bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('addams-family-the---pugsleys-scavenger-hunt-europe', 'SNES', 'Addams Family, The - Pugsley''s Scavenger Hunt (Europe)', '1993', 'Platformer', 'Ocean Software', '1', 'Cartoon platformer', 'Side-scrolling platformer featuring non-linear level exploration.', 'Find all the hidden items in the mansion to complete the scavenger hunt.', 'Help Pugsley in Addams Family: Pugsley''s Scavenger Hunt for SNES.', 'Control Pugsley Addams in this challenging platformer. Navigate through the bizarre Addams mansion, battling strange creatures and solving environmental puzzles to find your family''s lost treasures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('addams-family-the---pugsleys-scavenger-hunt-usa', 'SNES', 'Addams Family, The - Pugsley''s Scavenger Hunt (USA)', '1993', 'Platformer', 'Ocean Software', '1', 'Cartoon platformer', 'Side-scrolling platformer featuring non-linear level exploration.', 'Find all the hidden items in the mansion to complete the scavenger hunt.', 'Help Pugsley in Addams Family: Pugsley''s Scavenger Hunt for SNES.', 'Control Pugsley Addams in this challenging platformer. Navigate through the bizarre Addams mansion, battling strange creatures and solving environmental puzzles to find your family''s lost treasures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('addams-family-the---pugsleys-scavenger-hunt-usa-beta', 'SNES', 'Addams Family, The - Pugsley''s Scavenger Hunt (USA) (Beta)', '1993', 'Platformer', 'Ocean Software', '1', 'Cartoon platformer', 'Side-scrolling platformer featuring non-linear level exploration.', 'Find all the hidden items in the mansion to complete the scavenger hunt.', 'Explore the Pugsley''s Scavenger Hunt Beta version for SNES.', 'A pre-release version of the classic platformer. This beta offers a look at early level designs and mechanics for Pugsley''s quest through the haunted Addams estate.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('addams-family-the-europe-enfrde', 'SNES', 'Addams Family, The (Europe) (En,Fr,De)', '1992', 'Action Platformer', 'Ocean Software', '1', 'Cinematic platformer', 'Action platformer with open exploration of the Addams estate.', 'Rescue the kidnapped members of the Addams family from the mansion''s depths.', 'Save the family in The Addams Family, a classic SNES adventure.', 'Play as Gomez Addams in this vast platforming quest. Explore different wings of the mansion, collect coins, and use power-ups to defeat enemies and free Morticia and the rest of the clan.');
