INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-batman-&-robin-the-europe', 'SNES', 'Adventures of Batman & Robin, The (Europe)', '1995', 'Action', 'Clockwork Tortoise', '1', 'Comic-style action', 'Cinematic action-platformer with high-quality 16-bit graphics and gadgets.', 'Defeat the iconic villains of Gotham City and stop the Joker''s latest plot.', 'Experience the best Batman action in The Adventures of Batman & Robin for SNES.', 'Widely considered one of the best licensed games on the system, this title features incredible visuals and varied levels based on the animated series. Use Batarangs and gadgets to take down Gotham''s worst.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-batman-&-robin-the-usa', 'SNES', 'Adventures of Batman & Robin, The (USA)', '1995', 'Action', 'Clockwork Tortoise', '1', 'Comic-style action', 'Cinematic action-platformer with high-quality 16-bit graphics and gadgets.', 'Defeat the iconic villains of Gotham City and stop the Joker''s latest plot.', 'Experience the best Batman action in The Adventures of Batman & Robin for SNES.', 'Widely considered one of the best licensed games on the system, this title features incredible visuals and varied levels based on the animated series. Use Batarangs and gadgets to take down Gotham''s worst.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-dr-franken-the-europe-enfrdeesitnlsv', 'SNES', 'Adventures of Dr. Franken, The (Europe) (En,Fr,De,Es,It,Nl,Sv)', '1993', 'Platformer', 'MotiveTime', '1', 'Horror platformer', 'Side-scrolling platformer with puzzle elements and limb-collection mechanics.', 'Explore the world to find the missing body parts of Franken''s girlfriend.', 'Join Franky in The Adventures of Dr. Franken, a unique SNES platformer.', 'Play as a monster on a mission. Navigate through global locations, from London to Egypt, solving puzzles and jumping through obstacles to bring your monster bride back to life.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-dr-franken-the-usa', 'SNES', 'Adventures of Dr. Franken, The (USA)', '1993', 'Platformer', 'MotiveTime', '1', 'Horror platformer', 'Side-scrolling platformer with puzzle elements and limb-collection mechanics.', 'Explore the world to find the missing body parts of Franken''s girlfriend.', 'Join Franky in The Adventures of Dr. Franken, a unique SNES platformer.', 'Play as a monster on a mission. Navigate through global locations, from London to Egypt, solving puzzles and jumping through obstacles to bring your monster bride back to life.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-kid-kleets-the-usa-enfres', 'SNES', 'Adventures of Kid Kleets, The (USA) (En,Fr,Es)', '1994', 'Platformer', 'Radical Entertainment', '1', 'Cartoon platformer', 'Soccer-themed action platformer where the player uses a ball to attack.', 'Defeat enemies and navigate obstacles to win the world soccer trophy.', 'Kick off an adventure in Adventures of Kid Kleets for the SNES.', 'Known in Europe as Soccer Kid, this creative platformer tasks you with using a soccer ball as your primary weapon and tool for movement across various international stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-rocky-and-bullwinkle-and-friends-the-usa', 'SNES', 'Adventures of Rocky and Bullwinkle and Friends, The (USA)', '1993', 'Action Platformer', 'Radical Entertainment', '1', 'Cartoon action', 'Multi-style action game featuring platforming, flying, and mini-games.', 'Stop Boris and Natasha from stealing the world''s artifacts.', 'Enjoy classic cartoon fun in The Adventures of Rocky and Bullwinkle on SNES.', 'Play as the famous moose and squirrel duo. Tackle various levels inspired by the cartoon show, featuring unique gameplay segments for both Rocky and Bullwinkle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-tintin-the---prisoners-of-the-sun-europe-enfrdees', 'SNES', 'Adventures of Tintin, The - Prisoners of the Sun (Europe) (En,Fr,De,Es)', '1996', 'Adventure', 'Infogrames', '1', 'Graphic adventure', 'Side-scrolling action adventure based on the famous Hergé comic series.', 'Rescue Professor Calculus and uncover the secrets of the Sun Temple.', 'Experience the mystery of Tintin: Prisoners of the Sun on SNES.', 'A faithful recreation of the Tintin universe. Help Tintin and Captain Haddock navigate dangerous environments in Peru, solving puzzles and avoiding traps in this atmospheric adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-yogi-bear-usa', 'SNES', 'Adventures of Yogi Bear (USA)', '1994', 'Platformer', 'Radical Entertainment', '1', 'Cartoon platformer', 'Side-scrolling platformer set in Jellystone Park with food-collecting goals.', 'Navigate levels and collect enough picnic baskets to progress.', 'Go on a picnic with Adventures of Yogi Bear for the SNES.', 'Play as Yogi Bear in this colorful, family-friendly platformer. Avoid park rangers and obstacles while hunting for baskets across forests and mountains in Jellystone Park.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aero-fighters-usa', 'SNES', 'Aero Fighters (USA)', '1992', 'Shoot ''em up', 'Video System', '2', 'Arcade vertical shooter', 'Vertical-scrolling shoot ''em up with multiple selectable pilots and planes.', 'Defeat the alien invasion across various global territories.', 'Take to the skies in Aero Fighters, an intense SNES arcade shooter.', 'Choose from four different nations and pilots, each with unique weapon systems. Engage in fast-paced aerial combat and massive boss battles in this acclaimed SHMUP.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aero-the-acro-bat-europe', 'SNES', 'Aero the Acro-Bat (Europe)', '1993', 'Platformer', 'Iguana Entertainment', '1', 'Acrobatic platformer', 'Fast-paced acrobatic platformer featuring a circus bat protagonist.', 'Stop the evil industrialist Edgar Ektor from destroying the circus.', 'Experience circus-themed action in Aero the Acro-Bat for SNES.', 'Play as Aero, using his signature drill attack and gliding abilities. Navigate through circus-inspired levels filled with spikes, cannons, and dangerous stunts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aero-the-acro-bat-usa', 'SNES', 'Aero the Acro-Bat (USA)', '1993', 'Platformer', 'Iguana Entertainment', '1', 'Acrobatic platformer', 'Fast-paced acrobatic platformer featuring a circus bat protagonist.', 'Stop the evil industrialist Edgar Ektor from destroying the circus.', 'Experience circus-themed action in Aero the Acro-Bat for SNES.', 'Play as Aero, using his signature drill attack and gliding abilities. Navigate through circus-inspired levels filled with spikes, cannons, and dangerous stunts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aero-the-acro-bat-2-europe', 'SNES', 'Aero the Acro-Bat 2 (Europe)', '1994', 'Platformer', 'Iguana Entertainment', '1', 'Acrobatic platformer', 'Polished action platformer with improved controls and darker themes.', 'Chase Edgar Ektor to his secret base and stop his evil plans once and for all.', 'Soar higher in Aero the Acro-Bat 2, the refined SNES sequel.', 'The sequel improves on every aspect of the original. Aero returns with new moves and longer levels, featuring some of the most fluid platforming mechanics on the Super Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aero-the-acro-bat-2-usa', 'SNES', 'Aero the Acro-Bat 2 (USA)', '1994', 'Platformer', 'Iguana Entertainment', '1', 'Acrobatic platformer', 'Polished action platformer with improved controls and darker themes.', 'Chase Edgar Ektor to his secret base and stop his evil plans once and for all.', 'Soar higher in Aero the Acro-Bat 2, the refined SNES sequel.', 'The sequel improves on every aspect of the original. Aero returns with new moves and longer levels, featuring some of the most fluid platforming mechanics on the Super Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aerobiz-usa', 'SNES', 'Aerobiz (USA)', '1992', 'Simulation', 'HAL Laboratory', '1', 'Business simulation', 'Deep business simulation focused on managing a global airline.', 'Expand your airline''s reach and become the top carrier in the world.', 'Master the airline business in Aerobiz for the SNES.', 'A sophisticated strategy game where you manage routes, buy planes, and handle negotiations. Compete against rival airlines to dominate the skies over several decades.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aerobiz-supersonic-usa', 'SNES', 'Aerobiz Supersonic (USA)', '1993', 'Simulation', 'HAL Laboratory', '1', 'Business simulation', 'Advanced airline management simulator with more time periods and options.', 'Achieve global aviation dominance through strategic planning and expansion.', 'Take command of the skies in Aerobiz Supersonic for the SNES.', 'The expanded sequel to Aerobiz, featuring more planes, cities, and historical scenarios. Navigate economic shifts and technological advancements to build a lasting airline empire.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aging-cassette-japan', 'SNES', 'Aging Cassette (Japan)', '1992', 'Educational', 'Nintendo', '1', 'Data management tool', 'Unknown', 'Unknown', 'Explore the mysterious Aging Cassette on the Super Famicom.', 'Information regarding this specific title is limited; it remains a rare or obscure entry in the Japanese Super Famicom library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aguri-suzuki-f-1-super-driving-europe', 'SNES', 'Aguri Suzuki F-1 Super Driving (Europe)', '1993', 'Racing', 'Genki', '1', 'Formula One racing', 'F1 racing simulation featuring the real driver and realistic tracks.', 'Compete in the Formula One world championship and finish in first place.', 'Race for glory in Aguri Suzuki F-1 Super Driving for SNES.', 'Experience 16-bit F1 racing with a focus on realism. Tune your car and master various world-famous tracks in this challenging racing sim endorsed by the Japanese legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aiii-sv---a-ressha-de-ikou-3-super-version-japan', 'SNES', 'AIII S.V. - A Ressha de Ikou 3 Super Version (Japan)', '1992', 'Simulation', 'Artdink', '1', 'Train management simulation', 'Complex city-building and train network simulation.', 'Build a successful metropolis by managing transit, zoning, and finances.', 'Master urban planning in AIII S.V. - A Ressha de Ikou 3 for SNES.', 'A deep simulation game where your primary tool for city growth is the railway system. Manage resources, stocks, and urban development in this classic Super Version of the "A-Train" series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-cavalry-europe', 'SNES', 'Air Cavalry (Europe)', '1995', 'Shoot ''em up', 'Sculptured Software', '1', 'Helicopter combat', 'First-person helicopter flight simulator with tactical combat elements.', 'Complete various military missions including search and destroy and escort.', 'Fly intense missions in Air Cavalry, the SNES helicopter combat sim.', 'Take control of an advanced attack helicopter. Navigate through multiple theaters of war, manage your fuel and ammunition, and engage enemy forces in this detailed 16-bit flight simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-cavalry-usa', 'SNES', 'Air Cavalry (USA)', '1995', 'Shoot ''em up', 'Sculptured Software', '1', 'Helicopter combat', 'First-person helicopter flight simulator with tactical combat elements.', 'Complete various military missions including search and destroy and escort.', 'Fly intense missions in Air Cavalry, the SNES helicopter combat sim.', 'Take control of an advanced attack helicopter. Navigate through multiple theaters of war, manage your fuel and ammunition, and engage enemy forces in this detailed 16-bit flight simulation.');
