INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-management---oozora-ni-kakeru-japan-rev-a', 'SNES', 'Air Management - Oozora ni Kakeru (Japan) (Rev A)', '1993', 'Simulation', 'Koei', '1', 'Aviation management simulation', 'Deep business simulation focused on managing a global airline.', 'Expand your airline''s reach and become the top carrier in the world.', 'Master the airline business in Air Management for the SNES.', 'Japanese version of Aerobiz. Manage routes, fleet acquisitions, and international negotiations to build a profitable aviation empire in this sophisticated strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-management-ii---koukuu-ou-o-mezase-japan', 'SNES', 'Air Management II - Koukuu Ou o Mezase (Japan)', '1995', 'Simulation', 'Koei', '1', 'Aviation management simulation', 'Advanced airline management simulator with more time periods and options.', 'Achieve global aviation dominance through strategic planning and expansion.', 'Take command of the skies in Air Management II for the SNES.', 'Japanese version of Aerobiz Supersonic. Navigate decades of aviation history, manage economic crises, and outcompete rivals to dominate the global travel market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-strike-patrol-usa', 'SNES', 'Air Strike Patrol (USA)', '1994', 'Action Strategy', 'SETA', '1', 'Tactical air combat', 'Isometric tactical jet fighter game with focus on ground support and dogfights.', 'Complete specific mission objectives like destroying targets and protecting allies.', 'Engage in tactical aerial combat in Air Strike Patrol for SNES.', 'Known as A.S.P., this game features an isometric view that adds a unique layer of strategy to the shoot ''em up genre. Master precision bombing and aerial maneuvers to succeed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akazukin-chacha-japan', 'SNES', 'Akazukin Chacha (Japan)', '1994', 'Action Platformer', 'Now Production', '1', 'Anime action', 'Turn-based RPG with magical girl themes and puzzle-solving.', 'Follow Chacha and her friends to defeat the Demon King.', 'Experience the magical world of Akazukin Chacha on SNES.', 'Based on the popular anime, this RPG features a unique battle system and charming story beats. Help Chacha, Riiya, and Shiine use their magical powers to save their world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akumajou-dracula-japan', 'SNES', 'Akumajou Dracula (Japan)', '1991', 'Action Platformer', 'Konami', '1', 'Gothic action platformer', 'Side-scrolling action platformer with gothic horror atmosphere and whip combat.', 'Navigate Dracula''s castle to defeat the Prince of Darkness.', 'Play the legendary Akumajou Dracula (Super Castlevania IV) on SNES.', 'Wield the legendary whip as Simon Belmont. This title features 8-way whipping mechanics, incredible Mode 7 effects, and one of the best soundtracks in the 16-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akumajou-dracula-xx-japan', 'SNES', 'Akumajou Dracula XX (Japan)', '1995', 'Action Platformer', 'Konami', '1', 'Gothic action platformer', 'Hardcore side-scrolling action platformer with branching paths and hidden secrets.', 'Rescue Maria and Annette and defeat Dracula in his castle.', 'Challenge yourself in Akumajou Dracula XX, a classic SNES horror quest.', 'Known in the West as Castlevania: Dracula X, this title offers intense difficulty, stunning sprite work, and multiple endings based on who you rescue during your journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('al-unser-jrs-road-to-the-top-europe', 'SNES', 'Al Unser Jr.''s Road to the Top (Europe)', '1994', 'Racing', 'Leland Interactive Media', '1', 'Indy-style racing', 'Racing game featuring go-karts, snowmobiles, IROC cars, and Indy cars.', 'Master four different vehicle types to become the ultimate racing champion.', 'Race to victory in Al Unser Jr.''s Road to the Top for SNES.', 'Progress through different racing disciplines. Start with go-karts and work your way up to professional Indy cars in this varied and challenging racing simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('al-unser-jrs-road-to-the-top-usa', 'SNES', 'Al Unser Jr.''s Road to the Top (USA)', '1994', 'Racing', 'Leland Interactive Media', '1', 'Indy-style racing', 'Racing game featuring go-karts, snowmobiles, IROC cars, and Indy cars.', 'Master four different vehicle types to become the ultimate racing champion.', 'Race to victory in Al Unser Jr.''s Road to the Top for SNES.', 'Progress through different racing disciplines. Start with go-karts and work your way up to professional Indy cars in this varied and challenging racing simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aladdin-europe', 'SNES', 'Aladdin (Europe)', '1993', 'Platformer', 'Capcom', '1', 'Disney platformer', 'Fast-paced action platformer with fluid animation and sword/apple combat.', 'Navigate Agrabah to win the heart of Jasmine and defeat Jafar.', 'Experience the magic of Disney''s Aladdin, a masterpiece for SNES.', 'Widely praised for its smooth controls and vibrant graphics, help Aladdin navigate the Cave of Wonders and the streets of Agrabah in this definitive 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aladdin-france', 'SNES', 'Aladdin (France)', '1993', 'Platformer', 'Capcom', '1', 'Disney platformer', 'Fast-paced action platformer with fluid animation and sword/apple combat.', 'Navigate Agrabah to win the heart of Jasmine and defeat Jafar.', 'Experience the magic of Disney''s Aladdin, a masterpiece for SNES.', 'Widely praised for its smooth controls and vibrant graphics, help Aladdin navigate the Cave of Wonders and the streets of Agrabah in this definitive 16-bit platformer.');
