INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aladdin-usa-beta', 'SNES', 'Aladdin (USA) (Beta)', '1993', 'Platformer', 'Capcom', '1', 'Disney platformer', 'Fast-paced action platformer with fluid animation and sword/apple combat.', 'Navigate Agrabah to win the heart of Jasmine and defeat Jafar.', 'Explore the Aladdin Beta and see the game''s development on SNES.', 'This pre-release version offers a fascinating look at early level designs and mechanics of the classic Disney title, perfect for fans and historians.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aladdin-2000', 'SNES', 'Aladdin 2000', '2000', 'Platformer', 'Unlicensed', '1', 'Fan-made platformer', 'Unknown', 'Unknown', 'Explore the mysterious Aladdin 2000 title for SNES.', 'Likely an unlicensed or pirate port, this title attempts to bring a different version of the Aladdin story to the 16-bit hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('albert-odyssey-japan', 'SNES', 'Albert Odyssey (Japan)', '1993', 'RPG', 'Sunsoft', '1', 'Turn-based RPG', 'Traditional turn-based RPG with a tactical battle system.', 'Embark on a quest to save the world from an emerging evil force.', 'Dive into the classic JRPG adventure of Albert Odyssey on SNES.', 'Featuring beautiful sprite work and a strategic grid-based combat system, Albert Odyssey is a hidden gem for fans of 16-bit role-playing games and epic stories.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('albert-odyssey-2---jashin-no-taidou-japan', 'SNES', 'Albert Odyssey 2 - Jashin no Taidou (Japan)', '1994', 'RPG', 'Sunsoft', '1', 'Turn-based RPG', 'Traditional turn-based RPG with a tactical battle system and deeper story.', 'Stop the resurrection of an evil god and restore peace to the land.', 'Continue the epic journey in Albert Odyssey 2 for the SNES.', 'The sequel expands on the tactical combat and narrative of the first game, offering more complex battles and a rich world to explore for JRPG enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alcahest-japan', 'SNES', 'Alcahest (Japan)', '1993', 'Action RPG', 'HAL Laboratory', '1', 'Isometric action RPG', 'Top-down action-adventure game with fast-paced real-time combat.', 'Journey across the land to collect the four elemental swords and defeat the demon.', 'Experience the intense action of Alcahest, a HAL Laboratory classic for SNES.', 'Produced by Satoru Iwata, this game plays like a faster-paced Zelda with more emphasis on combat. Navigate challenging dungeons and defeat massive bosses in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alcahest-japan-en-by-fh-v10beta', 'SNES', 'Alcahest (Japan) [En by FH v1.0Beta]', '1993', 'Action RPG', 'HAL Laboratory', '1', 'Isometric action RPG', 'Top-down action-adventure game with fast-paced real-time combat.', 'Journey across the land to collect the four elemental swords and defeat the demon.', 'Play the English translation of Alcahest, the SNES action gem.', 'Now fully playable in English, follow the story of Alen as he battles through a high-fantasy world in this incredible real-time action-adventure game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alfred-chicken-europe', 'SNES', 'Alfred Chicken (Europe)', '1994', 'Platformer', 'Twilight Games', '1', 'Cartoon platformer', 'Side-scrolling platformer starring a quirky chicken with various abilities.', 'Rescue your fellow chickens and defeat the robotic invaders.', 'Join the wacky adventure in Alfred Chicken for the SNES.', 'Play as a brave chicken who can peck, bounce, and find hidden areas. This colorful platformer is filled with puzzles and secret items across multiple themed worlds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alice-no-paint-adventure-japan', 'SNES', 'Alice no Paint Adventure (Japan)', '1992', 'Educational', 'HAL Laboratory', '1', 'Painting creativity tool', 'Educational digital painting and adventure game based on the classic story.', 'Complete various mini-games and coloring activities in Wonderland.', 'Get creative with Alice no Paint Adventure for the SNES.', 'This unique title combines the "Alice in Wonderland" story with creative tools, allowing players to paint scenes and interact with characters in an educational setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-3-europe', 'SNES', 'Alien 3 (Europe)', '1992', 'Action Platformer', 'Probe Entertainment', '1', 'Cinematic action', 'Side-scrolling action platformer with exploration and mission-based objectives.', 'Complete tasks like rescuing prisoners and clearing nests on Fiorina 161.', 'Survive the horror of Alien 3, the intense action game for SNES.', 'Unlike other versions, the SNES game features a non-linear mission structure. Use flamethrowers and pulse rifles to navigate the prison planet and survive the Xenomorph threat.');
