INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-vs-predator-europe', 'SNES', 'Alien vs. Predator (Europe)', '1993', 'Beat ''em up', 'Jorudan', '2', 'Sci-fi brawler', 'Belt-scrolling beat ''em up featuring the iconic movie monsters.', 'Fight through waves of enemies to survive the ultimate intergalactic conflict.', 'Battle for supremacy in Alien vs. Predator for the SNES.', 'Choose your side and engage in brutal hand-to-hand combat. Navigate through various environments and defeat powerful bosses in this 16-bit arcade-style brawler.');
