INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-american-championship-football-europe', 'SNES', 'All-American Championship Football (Europe)', '1993', 'Sports', 'SEGA', '2', 'American football', 'American football simulation with league and tournament modes.', 'Win the championship by leading your football team to the top of the league.', 'Experience 16-bit gridiron action in All-American Championship Football.', 'A solid American football title for the SNES featuring various formations, team management, and competitive gameplay for sports enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-stars-smb2-in-smb1-&-smb1-in-smb3', 'SNES', 'All-Stars SMB2 in SMB1 & SMB1 in SMB3', '2021', 'Platformer', 'ROM Hack', '1', 'Mario remix platformer', 'Platformer compilation or engine swap featuring classic Mario levels.', 'Navigate through various Mario worlds and defeat Bowser in different styles.', 'Play the unique Mario engine swap All-Stars SMB2 in SMB1.', 'This interesting ROM hack or compilation swaps engines between classic Super Mario games, offering a fresh way to play iconic 8-bit levels with 16-bit graphics and physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('amazing-spider-man-the---lethal-foes-japan', 'SNES', 'Amazing Spider-Man, The - Lethal Foes (Japan)', '1995', 'Action', 'Sega', '1', 'Comic-style action', 'Side-scrolling action platformer featuring Spider-Man''s powers and gadgets.', 'Defeat the Lethal Foes and stop their criminal organization in New York.', 'Swing into action with Spider-Man: Lethal Foes on the SNES.', 'A Japan-exclusive Marvel title featuring high-quality sprite work and cameos from various Marvel heroes and villains. Use web-swinging and wall-crawling to stop the city''s greatest threats.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('america-oudan-ultra-quiz-japan', 'SNES', 'America Oudan Ultra Quiz (Japan)', '1991', 'Trivia', 'Game Studio', '1', 'TV quiz game', 'Trivia-based quiz game based on the popular Japanese TV show.', 'Answer questions correctly to travel across America and win the grand prize.', 'Test your knowledge in America Oudan Ultra Quiz for SNES.', 'Experience the high-stakes world of Japanese TV trivia. Compete in various rounds across different US locations in this unique 16-bit quiz simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('american-battle-dome-japan', 'SNES', 'American Battle Dome (Japan)', '1992', 'Action', 'Takara', '2', 'Tabletop action', 'Futuristic 4-player pinball battle game with competitive elements.', 'Score the most points and outlast opponents in a high-speed pinball arena.', 'Experience chaotic pinball action in American Battle Dome for SNES.', 'A unique take on pinball where players compete simultaneously on the same board. Fast-paced, colorful, and highly competitive, it''s a great multiplayer gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('american-gladiators-usa', 'SNES', 'American Gladiators (USA)', '1993', 'Action', 'Sales Curve Interactive', '2', 'TV show action', 'Action-sports simulation based on the hit physical competition TV show.', 'Complete various athletic challenges and defeat the Gladiators in the Eliminator.', 'Become a contender in American Gladiators for the SNES.', 'Featuring classic events like Joust, Assault, and the Wall. Test your timing and reflexes against the show''s iconic athletes in this 16-bit recreation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('american-tail-an---fievel-goes-west-europe', 'SNES', 'American Tail, An - Fievel Goes West (Europe)', '1994', 'Platformer', 'MotiveTime', '1', 'Animated film platformer', 'Side-scrolling platformer with cowboy themes and exploration.', 'Navigate the Wild West and find Fievel''s family while avoiding Cat R. Waul.', 'Join Fievel''s Western adventure in An American Tail for SNES.', 'Based on the animated film, help Fievel jump, climb, and shoot bubble pop guns through various levels inspired by the movie''s desert and town settings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('american-tail-an---fievel-goes-west-usa', 'SNES', 'American Tail, An - Fievel Goes West (USA)', '1994', 'Platformer', 'MotiveTime', '1', 'Animated film platformer', 'Side-scrolling platformer with cowboy themes and exploration.', 'Navigate the Wild West and find Fievel''s family while avoiding Cat R. Waul.', 'Join Fievel''s Western adventure in An American Tail for SNES.', 'Based on the animated film, help Fievel jump, climb, and shoot bubble pop guns through various levels inspired by the movie''s desert and town settings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('andre-agassi-tennis-japan', 'SNES', 'Andre Agassi Tennis (Japan)', '1992', 'Sports', 'Taito', '2', 'Tennis simulation', 'Tennis simulation with multiple court surfaces and tournament modes.', 'Win the Grand Slam tournaments and become the world''s top-ranked player.', 'Play professional 16-bit tennis in Andre Agassi Tennis for SNES.', 'Featuring the legendary player, this game offers realistic tennis physics, various stroke types, and a deep career mode for fans of the sport.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('andre-agassi-tennis-usa', 'SNES', 'Andre Agassi Tennis (USA)', '1992', 'Sports', 'Taito', '2', 'Tennis simulation', 'Tennis simulation with multiple court surfaces and tournament modes.', 'Win the Grand Slam tournaments and become the world''s top-ranked player.', 'Play professional 16-bit tennis in Andre Agassi Tennis for SNES.', 'Featuring the legendary player, this game offers realistic tennis physics, various stroke types, and a deep career mode for fans of the sport.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('angelique---premium-box-japan', 'SNES', 'Angelique - Premium Box (Japan)', '1994', 'Simulation', 'Koei', '1', 'Otome dating simulation', 'Otomé dating simulation and strategy with fantasy elements.', 'Balance your duties as a candidate for Queen while building relationships.', 'Experience the first Otomé game in Angelique - Premium Box for SNES.', 'A luxury edition of the classic romance sim. Interact with various guardians and manage your planetary development in this pioneering title of the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('angelique---voice-fantasy-japan', 'SNES', 'Angelique - Voice Fantasy (Japan)', '1995', 'Simulation', 'Koei', '1', 'Voice-enhanced dating sim', 'Otomé dating simulation enhanced with voice-acting features.', 'Win the favor of the Guardians and become the next Queen of the universe.', 'Enjoy the expanded Angelique - Voice Fantasy experience on SNES.', 'This version utilizes special hardware or techniques to provide voice acting, enhancing the narrative and romance elements of the original Angelique story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('angelique-japan', 'SNES', 'Angelique (Japan)', '1994', 'Simulation', 'Koei', '1', 'Otome dating simulation', 'The original Otomé dating simulation and planetary management game.', 'Grow your assigned continent and build bonds with the elemental Guardians.', 'Play the original Angelique, the pioneer of Otomé games on SNES.', 'A blend of social simulation and light strategy. Choose your path, interact with characters, and manage resources to prove your worthiness for the throne.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('angelique-english', 'SNES', 'Angelique English', '1994', 'Simulation', 'Koei', '1', 'Otome dating simulation', 'Otomé dating simulation and strategy, translated for English speakers.', 'Compete to become the Queen while developing romances in English.', 'Play the English translation of Angelique on the SNES.', 'The classic romance and strategy hybrid is now accessible to a wider audience. Manage your world and your heart in this landmark Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-buranden---brutal-japan', 'SNES', 'Animal Buranden - Brutal (Japan)', '1992', 'Fighting', 'Jaleco', '2', 'Brutal fighting game', 'Fighting game with anthropomorphic animal characters and brutal moves.', 'Defeat all animal rivals in a tournament of ultimate biological strength.', 'Unleash your wild side in Animal Buranden - Brutal for SNES.', 'A colorful 16-bit fighter featuring diverse animal warriors. Master unique combos and special moves in this high-energy martial arts contest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animaniacs-europe', 'SNES', 'Animaniacs (Europe)', '1994', 'Platformer', 'Konami', '2', 'Cartoon platformer', 'Multi-style action game with platforming, puzzles, and mini-games.', 'Complete various tasks on the movie studio lot to stop Thaddeus Plotz.', 'Join the Warner brothers (and sister) in Animaniacs for SNES.', 'Control Yakko, Wakko, and Dot as they switch between unique abilities to solve puzzles and navigate the Warner Bros. studio in this vibrant licensed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animaniacs-japan', 'SNES', 'Animaniacs (Japan)', '1994', 'Platformer', 'Konami', '2', 'Cartoon platformer', 'Multi-style action game with platforming, puzzles, and mini-games.', 'Complete various tasks on the movie studio lot to stop Thaddeus Plotz.', 'Join the Warner brothers (and sister) in Animaniacs for SNES.', 'Control Yakko, Wakko, and Dot as they switch between unique abilities to solve puzzles and navigate the Warner Bros. studio in this vibrant licensed title.');
