INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('another-world-europe', 'SNES', 'Another World (Europe)', '1992', 'Adventure', 'Delphine Software', '1', 'Cinematic adventure', 'Cinematic action-adventure with rotoscoped animation and logic puzzles.', 'Survive a dangerous alien world and find a way back home.', 'Experience the cinematic masterpiece Another World on SNES.', 'Also known as Out of This World, this game features minimalist storytelling and intense trial-and-error gameplay in a beautifully realized alien landscape.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aoki-densetsu-shoot!-japan', 'SNES', 'Aoki Densetsu Shoot! (Japan)', '1994', 'Sports', 'KCE Tokyo', '2', 'Anime soccer', 'Soccer simulation based on the popular manga and anime series.', 'Lead your team to victory in the national championships using special moves.', 'Play anime-style soccer in Aoki Densetsu Shoot! for SNES.', 'Experience the drama of the "Shoot!" series. Execute powerful signature shots and follow the narrative of Toshi and his teammates in this 16-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('apocalypse-ii-europe-proto', 'SNES', 'Apocalypse II (Europe) (Proto)', '1994', 'Shoot ''em up', 'Unknown', '1', 'Prototype shooter', 'Side-scrolling shooter with high-tech weaponry and vehicle segments.', 'Stop a global terrorist threat and prevent a nuclear apocalypse.', 'Play the unreleased prototype Apocalypse II on the SNES.', 'A fast-paced action game that never saw a final release. Features intense shooting mechanics and large-scale explosions in a futuristic setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('appleseed---prometheus-no-shintaku-japan', 'SNES', 'Appleseed - Prometheus no Shintaku (Japan)', '1994', 'Action RPG', 'SEGA', '1', 'Cyberpunk action RPG', 'Side-scrolling action-adventure based on the cyberpunk manga.', 'Navigate through high-tech environments to stop a terrorist conspiracy.', 'Enter the world of Appleseed - Prometheus no Shintaku on SNES.', 'Control Deunan Knute in this atmospheric cyberpunk title. Featuring platforming, combat, and mecha segments based on Masamune Shirow''s iconic series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aqutallion-japan', 'SNES', 'Aqutallion (Japan)', '1995', 'RPG', 'Technosoft', '1', 'Top-down sci-fi RPG', 'Traditional turn-based JRPG with a focus on elemental magic and adventure.', 'Travel the world to stop an ancient evil from awakening.', 'Explore the magical world of Aqutallion (Tecmo Secret of the Stars) on SNES.', 'Features two separate parties of heroes whose stories eventually intertwine. A classic JRPG experience with unique magic systems and a vast world to explore.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arabian-nights---sabaku-no-seirei-ou-english-v10', 'SNES', 'Arabian Nights - Sabaku no Seirei Ou (English v1.0)', '1993', 'Action RPG', 'Culture Brain', '1', 'Fantasy narrative RPG', 'Turn-based RPG with an Arabian Nights setting and card-based mechanics.', 'Navigate a world of genies and desert mystery to defeat the Spirit King.', 'Play the English translation of Arabian Nights for SNES.', 'A beautifully crafted JRPG featuring a unique day/night system and card combat. Follow the story of a girl and her genie protector in this desert epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arabian-nights---sabaku-no-seirei-ou-japan', 'SNES', 'Arabian Nights - Sabaku no Seirei Ou (Japan)', '1993', 'Action RPG', 'Culture Brain', '1', 'Fantasy narrative RPG', 'Turn-based RPG with an Arabian Nights setting and card-based mechanics.', 'Navigate a world of genies and desert mystery to defeat the Spirit King.', 'Experience the desert mystery of Arabian Nights on SNES.', 'A beautifully crafted JRPG featuring a unique day/night system and card combat. Follow the story of a girl and her genie protector in this desert epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('araiguma-rascal-japan', 'SNES', 'Araiguma Rascal (Japan)', '1994', 'Platformer', 'Nippon Animation', '1', 'Anime platformer', 'Action platformer and puzzle game featuring the famous raccoon character.', 'Navigate through beautiful hand-drawn levels to collect items and reach home.', 'Join the cute adventures of Araiguma Rascal on the SNES.', 'Based on the popular anime, this title features charming graphics and relaxing gameplay, perfect for younger players and fans of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arcades-greatest-hits---the-atari-collection-1-europe', 'SNES', 'Arcade''s Greatest Hits - The Atari Collection 1 (Europe)', '1995', 'Compilation', 'Digital Eclipse', '2', 'Classic arcade compilation', 'Compilation of classic arcade games from the Atari era.', 'Achieve high scores in legendary titles like Asteroids, Centipede, and Missile Command.', 'Play the classics with Arcade''s Greatest Hits: Atari Collection 1 on SNES.', 'A perfect preservation of arcade history. Includes pixel-perfect ports of iconic games that defined the early era of video gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arcades-greatest-hits---the-atari-collection-1-usa', 'SNES', 'Arcade''s Greatest Hits - The Atari Collection 1 (USA)', '1995', 'Compilation', 'Digital Eclipse', '2', 'Classic arcade compilation', 'Compilation of classic arcade games from the Atari era.', 'Achieve high scores in legendary titles like Asteroids, Centipede, and Missile Command.', 'Play the classics with Arcade''s Greatest Hits: Atari Collection 1 on SNES.', 'A perfect preservation of arcade history. Includes pixel-perfect ports of iconic games that defined the early era of video gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arcana-usa', 'SNES', 'Arcana (USA)', '1992', 'RPG', 'HAL Laboratory', '1', 'Tactical card-based RPG', 'First-person dungeon crawler with turn-based card-themed combat.', 'Explore the tower of Galia to defeat the evil empress and restore peace.', 'Master card-based combat in Arcana, a unique SNES RPG.', 'A distinct JRPG that uses cards for its visuals and combat system. Navigate large 3D-style dungeons and manage your party of elemental spirits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arcus-odyssey-usa-proto', 'SNES', 'Arcus Odyssey (USA) (Proto)', '1992', 'Action RPG', 'Wolf Team', '1', 'Top-down action RPG', 'Top-down action RPG with multiple playable characters and cooperative play.', 'Defeat the dark wizards and protect the sacred land of Arcus.', 'Experience the action-packed Arcus Odyssey prototype on SNES.', 'Known for its fast-paced combat and diverse character choices. Each hero offers a different gameplay style in this intense fantasy adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arcus-spirits-japan', 'SNES', 'Arcus Spirits (Japan)', '1991', 'Action RPG', 'Wolf Team', '1', 'Top-down action RPG', 'Isometric action-adventure with tactical combat and exploration.', 'Navigate dangerous dungeons and defeat mythological creatures to save the land.', 'Master isometric action in Arcus Spirits for the SNES.', 'A refined version of the Arcus formula, featuring challenging enemies, intricate level designs, and beautiful 16-bit fantasy aesthetics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ardy-lightfoot-europe', 'SNES', 'Ardy Lightfoot (Europe)', '1993', 'Platformer', 'Irem', '1', 'Action platformer', 'Side-scrolling action platformer with a unique companion mechanic.', 'Find the seven rainbow colored stones to save the world from an evil king.', 'Join the epic adventure of Ardy Lightfoot on the SNES.', 'Ardy is joined by his pal Pec, who can be used as a weapon or a tool. This game features incredibly detailed animation and a charming, story-rich world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ardy-lightfoot-japan', 'SNES', 'Ardy Lightfoot (Japan)', '1993', 'Platformer', 'Irem', '1', 'Action platformer', 'Side-scrolling platformer with a unique companion-based combat system.', 'Collect the shattered pieces of a rainbow crystal to defeat the evil King Visconti.', 'Join Ardy and his pal Pec in the charming SNES platformer Ardy Lightfoot.', 'Control Ardy and use your creature companion, Pec, as a multi-purpose tool and weapon. Explore a beautifully animated world filled with creative boss fights and diverse environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ardy-lightfoot-japan-beta', 'SNES', 'Ardy Lightfoot (Japan) (Beta)', '1993', 'Platformer', 'Irem', '1', 'Action platformer', 'Side-scrolling platformer with a unique companion-based combat system.', 'Collect the shattered pieces of a rainbow crystal to defeat the evil King Visconti.', 'Explore the early development of Ardy Lightfoot in this SNES Beta.', 'A pre-release version of Ardy Lightfoot featuring minor differences in level layout and mechanics. Experience the core platforming action as it was during the development phase.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ardy-lightfoot-usa', 'SNES', 'Ardy Lightfoot (USA)', '1993', 'Platformer', 'Irem', '1', 'Action platformer', 'Side-scrolling platformer with a unique companion-based combat system.', 'Collect the shattered pieces of a rainbow crystal to defeat the evil King Visconti.', 'Join Ardy and his pal Pec in the charming SNES platformer Ardy Lightfoot.', 'Control Ardy and use your creature companion, Pec, as a multi-purpose tool and weapon. Explore a beautifully animated world filled with creative boss fights and diverse environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('area-88-japan', 'SNES', 'Area 88 (Japan)', '1991', 'Shoot ''em up', 'Capcom', '1', 'Arcade jet shooter', 'Side-scrolling shoot ''em up with a mercenary pilot theme and upgradeable jets.', 'Complete aerial missions and destroy the enemy base to end the war.', 'Fly intense mercenary missions in Area 88 (UN Squadron) for the SNES.', 'Choose your pilot and customize your jet with various weapons. Navigate through challenging aerial stages and engage in massive boss battles in this acclaimed Capcom shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aretha-japan', 'SNES', 'Aretha (Japan)', '1993', 'RPG', 'Japan Art Media', '1', 'Fantasy RPG', 'Traditional turn-based RPG with a focus on exploration and magic.', 'Embark on a journey to find the lost treasures of Aretha and save the kingdom.', 'Experience the classic JRPG adventure of Aretha on the SNES.', 'Guide Ariel through a vast fantasy world. Manage your party, master powerful spells, and engage in classic 16-bit turn-based combat to uncover the secrets of the Aretha lineage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aretha-ii---ariel-no-fushigi-na-tabi-japan', 'SNES', 'Aretha II - Ariel no Fushigi na Tabi (Japan)', '1994', 'RPG', 'Japan Art Media', '1', 'Story-driven RPG', 'Traditional turn-based RPG featuring a female protagonist and deeper narrative.', 'Travel across the land to stop an ancient evil from threatening the world of Aretha.', 'Continue the epic RPG journey in Aretha II for the SNES.', 'The sequel expands on the original''s mechanics with improved graphics and a more complex story. Follow Ariel and her companions as they face new challenges in this expansive JRPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aretha-ii---ariel-no-fushigi-na-tabi-japan-beta1', 'SNES', 'Aretha II - Ariel no Fushigi na Tabi (Japan) (Beta1)', '1994', 'RPG', 'Japan Art Media', '1', 'Story-driven RPG', 'Traditional turn-based RPG featuring a female protagonist and deeper narrative.', 'Travel across the land to stop an ancient evil from threatening the world of Aretha.', 'Explore the development of Aretha II with this SNES Beta version.', 'An early look at the second entry in the Aretha series. Test the combat systems and explore early builds of the game''s fantasy environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aretha-ii---ariel-no-fushigi-na-tabi-japan-beta2', 'SNES', 'Aretha II - Ariel no Fushigi na Tabi (Japan) (Beta2)', '1994', 'RPG', 'Japan Art Media', '1', 'Story-driven RPG', 'Traditional turn-based RPG featuring a female protagonist and deeper narrative.', 'Travel across the land to stop an ancient evil from threatening the world of Aretha.', 'Explore the development of Aretha II with this SNES Beta version.', 'A secondary pre-release build of Aretha II, offering further insights into the game''s development and refined RPG mechanics before the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arkanoid---doh-it-again-europe', 'SNES', 'Arkanoid - Doh It Again (Europe)', '1997', 'Arcade', 'Taito', '2', 'Brick breaker', 'Classic brick-breaking arcade action with power-ups and boss battles.', 'Clear all blocks on each level using a paddle and ball to defeat Doh.', 'Relive the classic arcade fun of Arkanoid - Doh It Again on SNES.', 'An updated take on the arcade classic. Use various power-ups like lasers and multi-ball to clear stages, while facing off against the recurring antagonist, Doh.');
