INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('art-of-fighting-europe', 'SNES', 'Art of Fighting (Europe)', '1993', 'Fighting', 'SNK', '2', 'Traditional fighting', 'One-on-one fighting game featuring large sprites and a spirit gauge mechanic.', 'Defeat Mr. Big and save Yuri Sakazaki from the criminal underworld.', 'Experience the high-impact combat of Art of Fighting on SNES.', 'A faithful port of the Neo Geo classic. Use the spirit gauge to unleash powerful special moves and watch as characters take visible damage during the fight.');
