INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('axelay-usa-sample', 'SNES', 'Axelay (USA) (Sample)', '1992', 'Shoot ''em up', 'Konami', '2', 'Vertical sci-fi shooter', 'Dual-perspective shoot ''em up with both vertical and side-scrolling stages.', 'Protect the solar system from the alien armada of the Illis Empire.', 'Play the Axelay Sample version to see the game''s SNES development.', 'A pre-release sample of the iconic shooter Axelay. This version offers a glimpse into the development process, featuring early stage builds and weapon mechanics for testing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ayrton-senna-racing-nigel-mansells-racing-hack', 'SNES', 'Ayrton Senna Racing (Nigel Mansell''s Racing Hack)', '1994', 'Racing', 'ROM Hack', '1', 'Formula racing', 'Formula One racing simulation with realistic physics and track designs.', 'Win the World Championship by mastering high-speed F1 circuits.', 'Race as a legend in the Ayrton Senna Racing hack for SNES.', 'A fan-made modification of Nigel Mansell''s World Championship Racing that pays tribute to Ayrton Senna. Experience refined F1 racing with updated graphics and performance to honor the Brazilian champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bob-europe', 'SNES', 'B.O.B. (Europe)', '1995', 'Action Platformer', 'Gray Matter', '1', 'Sci-fi action platformer', 'Side-scrolling action platformer with an emphasis on various projectile weapons.', 'Navigate through dangerous alien planets to reach your date on time.', 'Blast through enemies in the sci-fi adventure B.O.B. for SNES.', 'Play as a teenage robot stranded on an asteroid. Use a wide array of specialized guns and gadgets to solve environmental puzzles and defeat waves of hostile aliens in this quirky platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bob-usa', 'SNES', 'B.O.B. (USA)', '1995', 'Action Platformer', 'Gray Matter', '1', 'Sci-fi action platformer', 'Side-scrolling action platformer with an emphasis on various projectile weapons.', 'Navigate through dangerous alien planets to reach your date on time.', 'Blast through enemies in the sci-fi adventure B.O.B. for SNES.', 'Play as a teenage robot stranded on an asteroid. Use a wide array of specialized guns and gadgets to solve environmental puzzles and defeat waves of hostile aliens in this quirky platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bahamut-lagoon-japan', 'SNES', 'Bahamut Lagoon (Japan)', '1996', 'Tactical RPG', 'Square', '1', 'Strategy RPG', 'Tactical turn-based RPG featuring dragon breeding and squad-based combat.', 'Lead the resistance to free the kingdom of Orelus from the Granbelos Empire.', 'Master dragon tactics in the epic Bahamut Lagoon for SNES.', 'A Squaresoft masterpiece that combines grid-based strategy with RPG elements. Feed and evolve your dragons to change their abilities and support your human squads in massive, beautiful 16-bit battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bahamut-lagoon-japan-en-by-dejap+neill-corlett+tomato-v13-emulator-edition', 'SNES', 'Bahamut Lagoon (Japan) [En by DeJap+Neill Corlett+Tomato v1.3] (Emulator Edition)', '1996', 'Tactical RPG', 'Square', '1', 'Strategy RPG', 'Tactical turn-based RPG featuring dragon breeding and squad-based combat.', 'Lead the resistance to free the kingdom of Orelus from the Granbelos Empire.', 'Play the English translation of Bahamut Lagoon on your SNES emulator.', 'Experience the full story of Bahamut Lagoon in English. This version is optimized for emulators, ensuring the complex script and tactical menus are perfectly readable for Western players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bahamut-lagoon-japan-en-by-dejap+neill-corlett+tomato-v13-real-hardware-edition', 'SNES', 'Bahamut Lagoon (Japan) [En by DeJap+Neill Corlett+Tomato v1.3] (Real Hardware Edition)', '1996', 'Tactical RPG', 'Square', '1', 'Strategy RPG', 'Tactical turn-based RPG featuring dragon breeding and squad-based combat.', 'Lead the resistance to free the kingdom of Orelus from the Granbelos Empire.', 'Bahamut Lagoon English translation optimized for real SNES hardware.', 'A specialized version of the fan translation designed to run flawlessly on original consoles and flash carts. Enjoy this deep tactical RPG with its full narrative restored in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baken-renkinjutsu-japan', 'SNES', 'Baken Renkinjutsu (Japan)', '1993', 'RPG', 'NCS', '1', 'Turn-based fantasy RPG', 'Horse racing simulation and management game.', 'Bet on winning horses and manage your gambling funds to become wealthy.', 'Test your luck in the Japanese horse racing sim Baken Renkinjutsu for SNES.', 'Focusing on the statistical side of horse racing, this title allows players to analyze data, place bets, and experience the tension of the racetrack through a 16-bit interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bakukyuu-renpatsu!!-super-b-daman-japan', 'SNES', 'Bakukyuu Renpatsu!! Super B-Daman (Japan)', '1995', 'Action', 'Takara', '2', 'Marble shooting action', 'Top-down action game based on the popular marble-shooting toy line.', 'Defeat opponents in various B-Daman arenas to win the championship.', 'Battle with marbles in Bakukyuu Renpatsu!! Super B-Daman for SNES.', 'Based on the classic hobby, this game features fast-paced arcade action. Master your aim and firing speed to clear obstacles and knock out rivals in competitive marble-blasting tournaments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bakumatsu-kourinden-oni-japan', 'SNES', 'Bakumatsu Kourinden Oni (Japan)', '1994', 'Action RPG', 'Atelier Double', '1', 'Dark fantasy action RPG', 'Traditional turn-based RPG set in historical Japan with supernatural elements.', 'Explore a mythological version of the Bakumatsu era to defeat ancient demons.', 'Dive into the supernatural RPG Bakumatsu Kourinden Oni for SNES.', 'Part of the "Oni" series, this JRPG blends Japanese history with folklore. Manage a party of heroes with unique spiritual abilities to combat monsters in a beautifully rendered 16-bit Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bakutou-dochers---bumps-jima-wa-oosawagi-japan', 'SNES', 'Bakutou Dochers - Bumps-jima wa Oosawagi (Japan)', '1993', 'Action Platformer', 'Compile', '2', 'Arcade-style action', 'Isometric action game with puzzle elements and competitive combat.', 'Navigate island stages and knock opponents off the platform to win.', 'Enjoy chaotic isometric action in Bakutou Dochers for the SNES.', 'A quirky Japanese title where players control round, bouncy characters. Use environmental hazards and character abilities to dominate the arena in this colorful and fast-paced multiplayer-focused game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ball-bullet-gun-japan', 'SNES', 'Ball Bullet Gun (Japan)', '1992', 'Shoot ''em up', 'Namco', '1', 'Arcade shooter', 'Isometric tactical strategy game focused on airsoft-style military combat.', 'Lead your squad to victory in various tactical skirmish scenarios.', 'Master tactical airsoft combat in Ball Bullet Gun for the SNES.', 'A unique strategy game that simulates airsoft battles. Manage squad positioning, cover, and line-of-sight in detailed isometric environments to outmaneuver the opposing team.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ball-bullet-gun-japan-en-by-aeon-genesis-v10', 'SNES', 'Ball Bullet Gun (Japan) [En by Aeon Genesis v1.0]', '1992', 'Shoot ''em up', 'Namco', '1', 'Arcade shooter', 'Isometric tactical strategy game focused on airsoft-style military combat.', 'Lead your squad to victory in various tactical skirmish scenarios.', 'Play Ball Bullet Gun in English with this SNES fan translation.', 'Now fully playable for English speakers, this translation opens up the deep tactical mechanics and mission briefings of this unique Japanese military strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ballz-3d-usa', 'SNES', 'Ballz 3D (USA)', '1994', 'Fighting', 'PF Magic', '2', '3D fighting', '3D perspective-based fighting game with unique ball-shaped characters.', 'Defeat all eccentric opponents to become the 3D fighting champion.', 'Experience the bizarre 3D fighter Ballz 3D on the Super Nintendo.', 'Ballz 3D uses a unique visual style where fighters are made of individual spheres. Utilize the pseudo-3D movement to pull off complex combos and outplay a cast of very strange characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbarossa-japan', 'SNES', 'Barbarossa (Japan)', '1993', 'Strategy', 'Koei', '1', 'Historical war simulation', 'Historical grand strategy simulation set during World War II.', 'Lead German forces through the Eastern Front to achieve military dominance.', 'Command armies in the WWII strategy game Barbarossa for SNES.', 'A deep, menu-driven tactical simulation. Manage unit placement, supply lines, and historical maneuvers in this complex recreation of the 1941 invasion of the Soviet Union.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-super-model-usa', 'SNES', 'Barbie Super Model (USA)', '1993', 'Platformer', 'Imagineering', '1', 'Fashion-themed platformer', 'Fashion-focused simulation with mini-games involving modeling and photography.', 'Complete various fashion assignments to become a successful supermodel.', 'Live the fashion life in Barbie Super Model for the Super Nintendo.', 'Navigate Barbie through various locations, practicing walking patterns, choosing outfits, and completing mini-games to prepare for the big runway shows and magazine shoots.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-vacation-adventure-usa-proto', 'SNES', 'Barbie Vacation Adventure (USA) (Proto)', '1994', 'Platformer', 'Imagineering', '1', 'Cartoon platformer', 'Adventure game with multiple vacation-themed mini-games and activities.', 'Explore different vacation spots and participate in local activities with Barbie.', 'Join the unreleased Barbie Vacation Adventure on the SNES.', 'A prototype of a family-friendly title featuring various holiday destinations. Participate in beach activities, camping, and more in this rare look at a cancelled Barbie project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barkley-no-power-dunk-japan', 'SNES', 'Barkley no Power Dunk (Japan)', '1994', 'Sports', 'Toei Animation', '2', 'Arcade basketball', 'Arcade-style basketball game featuring the NBA star Charles Barkley.', 'Outscore the opposing team in fast-paced 2-on-2 basketball matches.', 'Hit the court in Barkley no Power Dunk (Shut Up and Jam!) for SNES.', 'The Japanese version of the street basketball hit. Features high-flying dunks, aggressive defense, and the legendary Charles Barkley in an arcade-style hoop experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barkley-shut-up-and-jam!-europe', 'SNES', 'Barkley Shut Up and Jam! (Europe)', '1994', 'Sports', 'Accolade', '2', 'Street basketball', 'Arcade-style basketball game featuring the NBA star Charles Barkley.', 'Outscore the opposing team in fast-paced 2-on-2 basketball matches.', 'Experience street hoops in Barkley Shut Up and Jam! for the SNES.', 'Forget the rules of professional basketball. This title focuses on the intensity of streetball, featuring big dunks, trash talking, and competitive 2-on-2 action across various urban courts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barkley-shut-up-and-jam!-usa', 'SNES', 'Barkley Shut Up and Jam! (USA)', '1994', 'Sports', 'Accolade', '2', 'Street basketball', 'Arcade-style basketball game featuring the NBA star Charles Barkley.', 'Outscore the opposing team in fast-paced 2-on-2 basketball matches.', 'Experience street hoops in Barkley Shut Up and Jam! for the SNES.', 'Forget the rules of professional basketball. This title focuses on the intensity of streetball, featuring big dunks, trash talking, and competitive 2-on-2 action across various urban courts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bass-masters-classic---pro-edition-europe', 'SNES', 'BASS Masters Classic - Pro Edition (Europe)', '1996', 'Sports', 'Black Pearl Software', '1', 'Fishing simulation', 'Fishing simulation with professional tournament rules and licensed gear.', 'Win the BASS Masters Classic by catching the heaviest bass in each tournament.', 'Experience professional competitive fishing in BASS Masters Classic Pro Edition.', 'The definitive 16-bit fishing experience. Select your equipment, choose your boat, and use professional techniques to find the best spots and catch record-breaking bass in various lake environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bass-masters-classic---pro-edition-usa', 'SNES', 'BASS Masters Classic - Pro Edition (USA)', '1996', 'Sports', 'Black Pearl Software', '1', 'Fishing simulation', 'Fishing simulation with professional tournament rules and licensed gear.', 'Win the BASS Masters Classic by catching the heaviest bass in each tournament.', 'Experience professional competitive fishing in BASS Masters Classic Pro Edition.', 'The definitive 16-bit fishing experience. Select your equipment, choose your boat, and use professional techniques to find the best spots and catch record-breaking bass in various lake environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bass-masters-classic-japan', 'SNES', 'BASS Masters Classic (Japan)', '1995', 'Sports', 'Black Pearl Software', '1', 'Fishing simulation', 'Fishing simulation with professional tournament rules and licensed gear.', 'Win the BASS Masters Classic by catching the heaviest bass in each tournament.', 'Master the art of bass fishing in the Japanese version of BASS Masters Classic.', 'A detailed sports simulation where you compete in high-stakes fishing tournaments. Features realistic fish behavior and a wide variety of lures and rods to master on the water.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bass-masters-classic-usa', 'SNES', 'BASS Masters Classic (USA)', '1995', 'Sports', 'Black Pearl Software', '1', 'Fishing simulation', 'Fishing simulation with professional tournament rules and licensed gear.', 'Win the BASS Masters Classic by catching the heaviest bass in each tournament.', 'Experience professional competitive fishing in BASS Masters Classic for SNES.', 'Navigate your boat across legendary American lakes. Monitor weather conditions and lake depth to track down the biggest fish and climb the professional rankings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bassins-black-bass-usa', 'SNES', 'Bassin''s Black Bass (USA)', '1994', 'Sports', 'Hot-B', '1', 'Fishing simulation', 'Detailed fishing game with a focus on realism and seasonal changes.', 'Progress through local tournaments to become the ultimate bass fishing champion.', 'Dive into authentic lake fishing with Bassin''s Black Bass for the SNES.', 'Featuring a top-down view for navigation and a cinematic view for reeling in, this title offers a deep simulation of freshwater fishing, including lure movement and tension management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bastard!!---ankoku-no-hakaishin-japan', 'SNES', 'Bastard!! - Ankoku no Hakaishin (Japan)', '1994', 'RPG', 'Cobra Team', '1', 'Anime dark fantasy RPG', '3D perspective fighting game with magical combat and anime-style graphics.', 'Defeat the dark wizards and protect the world from the Dark God of Destruction.', 'Experience magical 16-bit combat in Bastard!! - Ankoku no Hakaishin.', 'Based on the hit manga and anime, this game features a unique over-the-shoulder perspective. Unleash massive spells and engage in high-speed aerial battles against iconic dark fantasy villains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bastard!!---ankoku-no-hakaishin-japan-en-by-dejap-v10-~bastard!!---dark-god-of-destruction', 'SNES', 'Bastard!! - Ankoku no Hakaishin (Japan) [En by DeJap v1.0] (~Bastard!! - Dark God of Destruction)', '1994', 'RPG', 'Cobra Team', '1', 'Anime dark fantasy RPG', '3D perspective fighting game with magical combat and anime-style graphics.', 'Defeat the dark wizards and protect the world from the Dark God of Destruction.', 'Play the English translation of Bastard!! Dark God of Destruction on SNES.', 'Now fully playable in English, follow Dark Schneider''s quest to reclaim his power. This fan translation makes the deep magic system and story accessible to Western fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman---revenge-of-the-joker-usa-proto', 'SNES', 'Batman - Revenge of the Joker (USA) (Proto)', '1995', 'Action Platformer', 'Sunsoft', '1', 'Comic-style action', 'Side-scrolling action platformer based on the comic book style.', 'Navigate through Gotham City to find and defeat the Joker.', 'Explore the rare prototype of Batman: Revenge of the Joker on SNES.', 'A 16-bit upgrade of the NES classic. Use various Batarang types and combat moves to fight through industrial levels and face off against Batman''s greatest rival in this unreleased build.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-usa-proto', 'SNES', 'Batman (USA) (Proto)', '1995', 'Action Platformer', 'Sunsoft', '1', 'Comic-style action', 'Side-scrolling action platformer featuring Batman''s gadgets.', 'Defeat thugs and iconic villains to clean up the streets of Gotham.', 'Check out this early Batman Prototype for the Super Nintendo.', 'An early development build showing the core mechanics of what would become a Batman action title. Features early level designs and character movement for testing purposes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-forever-europe', 'SNES', 'Batman Forever (Europe)', '1995', 'Action Platformer', 'Probe Entertainment', '1', 'Cinematic beat ''em up', 'Beat ''em up and platformer hybrid with digitized character sprites.', 'Infiltrate the Arkham Asylum and stop Two-Face and the Riddler''s scheme.', 'Enter the shadows in the Batman Forever video game for SNES.', 'Based on the 1995 film, control Batman or Robin. Use a variety of gadgets and Mortal Kombat-style combat moves to navigate through Gotham''s dark secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-forever-japan', 'SNES', 'Batman Forever (Japan)', '1995', 'Action Platformer', 'Probe Entertainment', '1', 'Cinematic beat ''em up', 'Beat ''em up and platformer hybrid with digitized character sprites.', 'Infiltrate the Arkham Asylum and stop Two-Face and the Riddler''s scheme.', 'Enter the shadows in the Batman Forever video game for SNES.', 'Based on the 1995 film, control Batman or Robin. Use a variety of gadgets and Mortal Kombat-style combat moves to navigate through Gotham''s dark secrets.');
