INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-returns-europe', 'SNES', 'Batman Returns (Europe)', '1992', 'Action Platformer', 'Konami', '1', 'Cinematic action', 'Traditional belt-scrolling beat ''em up based on the 1992 film.', 'Fight through the Red Triangle Circus Gang to stop the Penguin and Catwoman.', 'Clean up Gotham City in the classic Batman Returns for SNES.', 'One of the most acclaimed beat ''em ups on the system. Use Batman''s cape, grapples, and pure strength to defeat waves of enemies in cinematic levels that follow the movie''s plot.');
