INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-blaze-japan', 'SNES', 'Battle Blaze (Japan)', '1992', 'Fighting', 'Sammy', '2', 'Weapon-based fighting', 'One-on-one fighting game with a fantasy setting and weapon-based combat.', 'Defeat all challengers in the tournament to earn the title of champion.', 'Engage in epic fantasy duels in Battle Blaze for the SNES.', 'Choose from a variety of warriors, each with their own unique weapons and beastly traits. Battle through atmospheric arenas in this 16-bit weapon-based brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-blaze-usa', 'SNES', 'Battle Blaze (USA)', '1992', 'Fighting', 'Sammy', '2', 'Weapon-based fighting', 'One-on-one fighting game with a fantasy setting and weapon-based combat.', 'Defeat all challengers in the tournament to earn the title of champion.', 'Engage in epic fantasy duels in Battle Blaze for the SNES.', 'Choose from a variety of warriors, each with their own unique weapons and beastly traits. Battle through atmospheric arenas in this 16-bit weapon-based brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-blaze-usa-beta', 'SNES', 'Battle Blaze (USA) (Beta)', '1992', 'Fighting', 'Sammy', '2', 'Weapon-based fighting', 'One-on-one fighting game with a fantasy setting and weapon-based combat.', 'Defeat all challengers in the tournament to earn the title of champion.', 'Explore the Battle Blaze Beta version on the Super Nintendo.', 'A development build of the fantasy fighter. Features early balancing, UI elements, and character moves that were tweaked for the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-cars-usa', 'SNES', 'Battle Cars (USA)', '1994', 'Racing', 'Malibu Interactive', '2', 'Combat racing', 'Futuristic combat racing game featuring armored vehicles and weapons.', 'Win races by outspeeding and destroying rival cars on high-tech tracks.', 'Drive and destroy in the futuristic racer Battle Cars for SNES.', 'Combining high-speed racing with vehicular combat, Battle Cars lets you upgrade your vehicle with missiles and shields to dominate the 16-bit road.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-clash-europe', 'SNES', 'Battle Clash (Europe)', '1992', 'Shooter', 'Intelligent Systems', '2', 'Light gun shooter', 'First-person light gun shooter utilizing the Super Scope.', 'Pilot a giant mech and destroy enemy robots in a futuristic war.', 'Experience explosive Super Scope action in Battle Clash on SNES.', 'A cinematic rail-shooter where you target specific parts of enemy mechs (STs). Manage your energy and timing to shoot down incoming missiles and dismantle your opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-clash-usa', 'SNES', 'Battle Clash (USA)', '1992', 'Shooter', 'Intelligent Systems', '2', 'Light gun shooter', 'First-person light gun shooter utilizing the Super Scope.', 'Pilot a giant mech and destroy enemy robots in a futuristic war.', 'Experience explosive Super Scope action in Battle Clash on SNES.', 'A cinematic rail-shooter where you target specific parts of enemy mechs (STs). Manage your energy and timing to shoot down incoming missiles and dismantle your opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-commander---hachibushuu-shura-no-heihou-japan', 'SNES', 'Battle Commander - Hachibushuu, Shura no Heihou (Japan)', '1992', 'Strategy', 'Banpresto', '1', 'Tactical war strategy', 'Tactical strategy game featuring crossover characters from various franchises.', 'Lead your mecha army to victory in turn-based strategic combat.', 'Master mecha strategy in Battle Commander for the SNES.', 'Featuring characters from Gundam, Mazinger Z, and Kamen Rider. Manage your units across diverse maps, utilizing terrain and unique unit abilities to defeat enemy forces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-cross-japan', 'SNES', 'Battle Cross (Japan)', '1992', 'Action', 'Jaleco', '2', 'Top-down arcade action', 'Isometric racing game with miniature cars and hazardous tracks.', 'Win the grand prix by navigating tight corners and avoiding obstacles.', 'Enjoy high-speed isometric racing in Battle Cross for the SNES.', 'A fast-paced racer where up to five players can compete. Use power-ups and master the drifting mechanics to stay ahead on the colorful, chaotic tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-dodge-ball---toukyuu-daigekitotsu!-japan', 'SNES', 'Battle Dodge Ball - Toukyuu Daigekitotsu! (Japan)', '1991', 'Sports', 'Technos Japan', '4', 'Dodgeball action', 'Dodgeball simulation featuring popular mecha and anime characters.', 'Defeat the opposing team by knocking out their players with the ball.', 'Play supernatural dodgeball in Battle Dodge Ball for the SNES.', 'Join characters from Ultraman, Gundam, and Kamen Rider in a super-powered dodgeball tournament. Use special moves and strategic passes to dominate the court.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-dodge-ball-ii-japan', 'SNES', 'Battle Dodge Ball II (Japan)', '1994', 'Sports', 'Technos Japan', '4', 'Dodgeball action', 'Sports simulation featuring super-powered dodgeball matches with iconic mecha and anime characters.', 'Eliminate the opposing team''s HP by hitting them with powerful ball attacks.', 'Play super-powered dodgeball with famous heroes in Battle Dodge Ball II for SNES.', 'A sequel to the cult classic, featuring characters from Gundam, Ultraman, and Kamen Rider. Master unique special shots and team formations to dominate the arena in this action-packed sports hybrid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-grand-prix-japan', 'SNES', 'Battle Grand Prix (Japan)', '1992', 'Racing', 'Atlus', '2', 'Top-down racing', 'Formula One racing simulation with split-screen multiplayer and various team selections.', 'Win the world championship by placing first in a series of global racing circuits.', 'Experience 16-bit F1 racing in the competitive Battle Grand Prix for SNES.', 'A detailed racing game offering various modes, including Grand Prix and versus. Customize your car''s settings and master the tracks to become the ultimate 16-bit racing legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-grand-prix-usa', 'SNES', 'Battle Grand Prix (USA)', '1992', 'Racing', 'Atlus', '2', 'Top-down racing', 'Formula One racing simulation with split-screen multiplayer and various team selections.', 'Win the world championship by placing first in a series of global racing circuits.', 'Experience 16-bit F1 racing in the competitive Battle Grand Prix for SNES.', 'A detailed racing game offering various modes, including Grand Prix and versus. Customize your car''s settings and master the tracks to become the ultimate 16-bit racing legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-jockey-japan', 'SNES', 'Battle Jockey (Japan)', '1994', 'Racing', 'Philips Media', '1', 'Horse racing simulation', 'Side-scrolling horse racing game with action and combat elements.', 'Win the race while using items and physical attacks to hinder opponents.', 'Experience chaotic horse racing action in Battle Jockey for the SNES.', 'A unique Japanese title that blends traditional horse racing with arcade combat. Use power-ups and well-timed attacks to cross the finish line first in this fast-paced competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-master---kyuukyoku-no-senshi-tachi-japan', 'SNES', 'Battle Master - Kyuukyoku no Senshi-tachi (Japan)', '1993', 'Strategy', 'Banpresto', '1', 'Tactical strategy RPG', 'One-on-one fighting game with a diverse roster of warriors and special moves.', 'Defeat all challengers in a martial arts tournament to prove your strength.', 'Master 16-bit martial arts in Battle Master: Kyuukyoku no Senshi-tachi.', 'A high-quality Japanese fighter featuring smooth animation and a deep combo system. Choose your warrior and battle through atmospheric stages to reach the final boss.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-pinball-japan', 'SNES', 'Battle Pinball (Japan)', '1995', 'Arcade', 'Banpresto', '1', 'Pinball action', 'Themed pinball simulation featuring popular Japanese characters and franchises.', 'Achieve high scores by completing board-specific missions and defeating bosses.', 'Enjoy themed pinball action in Battle Pinball for the Super Famicom.', 'Featuring boards based on Ultraman, Gundam, and more. Use the flippers to trigger special events and battle enemies directly on the pinball table in this crossover hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-racers-japan', 'SNES', 'Battle Racers (Japan)', '1991', 'Racing', 'Namco', '2', 'Top-down racing', 'Combat racing game featuring SD (Super Deformed) characters from famous franchises.', 'Cross the finish line first while using weapons to blast rivals off the track.', 'Race and battle with SD heroes in Battle Racers for the SNES.', 'A fun, competitive racer featuring characters from Ultraman, Kamen Rider, and Gundam. Use unique vehicle abilities and environmental hazards to secure your victory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-robot-retsuden-japan', 'SNES', 'Battle Robot Retsuden (Japan)', '1995', 'Action', 'Rumic Soft', '1', 'Mecha battle simulation', 'Strategic turn-based RPG focusing on giant robot combat and customization.', 'Lead your robot squad through tactical battles to defeat the enemy forces.', 'Command powerful mechs in Battle Robot Retsuden for the SNES.', 'Part of the "Battle" series crossover, this RPG focuses on the Banpresto universe. Upgrade your units and use strategic positioning to win tactical encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-soccer---field-no-hasha-japan', 'SNES', 'Battle Soccer - Field no Hasha (Japan)', '1994', 'Sports', 'Banpresto', '2', 'Arcade soccer', 'Arcade-style soccer game featuring robots, monsters, and heroes.', 'Score more goals than the opponent using special moves and physical force.', 'Play super-powered 16-bit football in Battle Soccer for the SNES.', 'A unique sports crossover where Godzilla, Ultraman, and Gundam robots compete on the pitch. Use devastating special shots and aggressive tactics to win the cup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-soccer---field-no-hasha-japan-en-by-hurkey-v10', 'SNES', 'Battle Soccer - Field no Hasha (Japan) [En by Hurkey v1.0]', '1994', 'Sports', 'Banpresto', '2', 'Arcade soccer', 'Arcade-style soccer game featuring robots, monsters, and heroes.', 'Score more goals than the opponent using special moves and physical force.', 'Play Battle Soccer in English with this SNES fan translation.', 'Experience the bizarre world of Battle Soccer with fully translated menus and dialogue. Lead your team of giant monsters and robots to world championship glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-soccer-2-japan', 'SNES', 'Battle Soccer 2 (Japan)', '1995', 'Sports', 'Banpresto', '2', 'Arcade soccer', 'Improved arcade-style soccer simulation with more teams and refined moves.', 'Win the Battle Soccer tournament by outplaying rivals on the field.', 'Experience the expanded sequel Battle Soccer 2 for the Super Famicom.', 'The sequel adds more characters and polished gameplay mechanics. Use advanced special shots and team strategies to dominate this unique 16-bit sports crossover.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-submarine-japan', 'SNES', 'Battle Submarine (Japan)', '1991', 'Simulation', 'Irem', '1', 'Submarine combat sim', 'Submarine combat simulation with a focus on tactical navigation and torpedo fire.', 'Sink enemy vessels and complete naval missions while managing depth.', 'Engage in underwater warfare in Battle Submarine for the SNES.', 'A rare submarine sim for the console. Manage your sonar, fuel, and oxygen levels while hunting enemy ships in the deep sea in this tactical 16-bit experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-tycoon---flash-hiders-sfx-japan', 'SNES', 'Battle Tycoon - Flash Hiders SFX (Japan)', '1995', 'Fighting', 'Right Stuff', '2', 'Anime fighting', 'One-on-one fighting game with RPG-style character growth and betting mechanics.', 'Defeat opponents to earn money and upgrade your fighter''s stats.', 'Experience the unique fighter Battle Tycoon: Flash Hiders SFX for SNES.', 'A high-quality 16-bit brawler that allows players to bet on fights and use the proceeds to customize their character''s attributes, blending fighting and light RPG elements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-tycoon---flash-hiders-sfx-japan-rev-a', 'SNES', 'Battle Tycoon - Flash Hiders SFX (Japan) (Rev A)', '1995', 'Fighting', 'Right Stuff', '2', 'Anime fighting', 'One-on-one fighting game with RPG-style character growth and betting mechanics.', 'Defeat opponents to earn money and upgrade your fighter''s stats.', 'Experience the unique fighter Battle Tycoon: Flash Hiders SFX for SNES.', 'A refined version of the original combat title. Master the complex move sets and utilize the growth system to build the ultimate 16-bit warrior.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-zeque-den-japan', 'SNES', 'Battle Zeque Den (Japan)', '1994', 'Action RPG', 'Asmik Ace', '1', 'Dark fantasy action RPG', 'Side-scrolling beat ''em up with a female protagonist and supernatural themes.', 'Fight through hordes of demons to stop an ancient evil from rising.', 'Unleash the power of the Zeque in Battle Zeque Den for the SNES.', 'Control one of three powerful female warriors in this atmospheric brawler. Features smooth combat, large sprites, and a unique 16-bit dark fantasy aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battletech-japan', 'SNES', 'Battletech (Japan)', '1993', 'Strategy', 'FASA Interactive', '1', 'Mech tactical strategy', 'Isometric action-strategy game where you pilot a massive BattleMech.', 'Complete various military objectives and destroy enemy mechs on the battlefield.', 'Pilot a giant mech in the classic BattleTech for the SNES.', 'Take command of a 70-ton war machine. Navigate through complex missions, manage your heat levels, and use a devastating arsenal to crush the opposition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battletech-3050-japan', 'SNES', 'Battletech 3050 (Japan)', '1994', 'Action', 'FASA Interactive', '1', 'Mech action combat', 'Isometric action-strategy game where you pilot a massive BattleMech.', 'Complete various military objectives and destroy enemy mechs on the battlefield.', 'Pilot a giant mech in the classic BattleTech 3050 for the SNES.', 'Experience the 3050 era of the BattleTech universe. Master the isometric controls and tactical combat to survive intense missions against the Clan invaders.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battletoads-&-double-dragon---the-ultimate-team-europe', 'SNES', 'Battletoads & Double Dragon - The Ultimate Team (Europe)', '1993', 'Beat ''em up', 'Rare', '2', 'Co-op brawler', 'Beat ''em up crossover featuring characters from both legendary franchises.', 'Defeat the Dark Queen and the Shadow Boss to save the universe.', 'Join the ultimate team-up in Battletoads & Double Dragon for SNES.', 'Control the Toads or the Lee brothers in this high-energy brawler. Navigate through treacherous levels filled with enemies, traps, and the series'' signature high difficulty.');
