INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battletoads-in-battlemaniacs-europe', 'SNES', 'Battletoads in Battlemaniacs (Europe)', '1993', 'Beat ''em up', 'Rare', '2', 'Arcade brawler', 'Hardcore beat ''em up featuring intense difficulty and varied gameplay segments.', 'Rescue your friends by fighting through the Dark Queen''s virtual world.', 'Face the brutal challenge of Battletoads in Battlemaniacs for SNES.', 'Zitz and Pimple take center stage in this visually stunning brawler. Features incredible animation, massive bosses, and the infamous difficulty the series is known for.');
