INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bazoe!-mahou-sekai-japan', 'SNES', 'Bazoe! Mahou Sekai (Japan)', '1994', 'RPG', 'Compile', '1', 'Fantasy RPG', 'Action-platformer with RPG elements and a magical world setting.', 'Explore the magical realm of Bazoe! to defeat the dark forces and find the legendary treasure.', 'Experience the rare JRPG adventure Bazoe! Mahou Sekai on SNES.', 'A charming Japanese title that blends platforming action with character progression. Navigate through vibrant levels, interact with unique NPCs, and master magical abilities to save the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bazooka-blitzkrieg-usa', 'SNES', 'Bazooka Blitzkrieg (USA)', '1989', 'Action', 'Bit Managers', '1', 'Arcade shooter', 'Light gun shooter for the Super Scope, featuring mecha and futuristic warfare.', 'Destroy waves of enemy robots and massive bosses to protect the city.', 'Engage in explosive Super Scope action with Bazooka Blitzkrieg for SNES.', 'A high-octane rail shooter where you take the role of a mecha pilot. Use your Super Scope to target weak points on enemy machines in this cinematic 16-bit arcade experience.');
