INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beauty-and-the-beast-europe', 'SNES', 'Beauty and the Beast (Europe)', '1994', 'Platformer', 'Probe Entertainment', '1', 'Animated film platformer', 'Action platformer where the player controls the Beast through various environments.', 'Defeat Gaston and break the enchantement to become human again.', 'Experience the Disney classic with Beauty and the Beast for SNES.', 'Navigate the Beast through dangerous forests and the castle. Use his strength and roar to defeat enemies and overcome obstacles in this faithful 16-bit adaptation of the animated film.');
