INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beavis-and-butt-head-europe', 'SNES', 'Beavis and Butt-Head (Europe)', '1994', 'Action', 'Vicom', 'New', 'Cartoon action', 'Action-adventure platformer featuring puzzles and a heavy focus on the show''s humor.', 'Find the GWAR concert tickets by navigating through town and completing tasks.', 'Join the duo in the hilarious Beavis and Butt-Head game for SNES.', 'Control Beavis and Butt-Head in a quest for concert tickets. Solve environmental puzzles, collect hidden items, and deal with iconic characters from the MTV show in this 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bebes-kids-usa', 'SNES', 'Bebe''s Kids (USA)', '1992', 'Action Platformer', 'Radical Entertainment', '1', 'Urban cartoon action', 'Side-scrolling beat ''em up based on the animated film with various mini-games.', 'Navigate the amusement park and survive the day while avoiding trouble.', 'Play the animated brawler Bebe''s Kids on the Super Nintendo.', 'Control Robin Harris'' kids through a series of challenging levels in a theme park. Fight off animatronic enemies and complete mini-games in this unique 16-bit licensed title.');
