INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('best-of-the-best---championship-karate-usa', 'SNES', 'Best of the Best - Championship Karate (USA)', '1993', 'Fighting', 'Loriciel', '2', 'Karate fighting', 'Realistic karate simulation with a focus on training and tactical combat.', 'Train your fighter and win the world championship through technical mastery.', 'Master martial arts in Best of the Best: Championship Karate for SNES.', 'A technical fighting game that emphasizes realistic movements and stamina management. Customize your training regime to build the ultimate karate champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('best-shot-pro-golf-japan', 'SNES', 'Best Shot Pro Golf (Japan)', '1994', 'Sports', 'Taito', '1', 'Golf simulation', 'Professional golf simulation with realistic physics and course management.', 'Complete various courses with the lowest score to win tournaments.', 'Hit the links in Best Shot Pro Golf for the Super Famicom.', 'A detailed golf title featuring accurate ball physics and environmental factors. Manage your clubs and wind speed to master the 18 holes in this 16-bit sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-ichigeki!-pachi-slot-daikouryaku-japan', 'SNES', 'Big Ichigeki! Pachi-Slot Daikouryaku (Japan)', '1992', 'Gambling', 'Konami', '1', 'Pachislot simulation', 'Pachi-slot simulation featuring realistic machine physics and gambling mechanics.', 'Master the slots and accumulate as much digital currency as possible.', 'Experience Japanese slots in Big Ichigeki! Pachi-Slot Daikouryaku for SNES.', 'A comprehensive simulation of Japanese Pachi-slot machines. Features multiple modes and machine types for fans of casino-style 16-bit gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-ichigeki!-pachi-slot-daikouryaku-2---universal-collection-japan', 'SNES', 'Big Ichigeki! Pachi-Slot Daikouryaku 2 - Universal Collection (Japan)', '1994', 'Gambling', 'Konami', '1', 'Pachislot simulation', 'Pachi-slot simulation featuring realistic machine physics and gambling mechanics.', 'Master the slots and accumulate as much digital currency as possible.', 'Experience Japanese slots in Big Ichigeki! Pachi-Slot Daikouryaku 2 for SNES.', 'The sequel to the popular slot sim, featuring updated machines from the Universal collection. Experience realistic slot mechanics and gambling strategy on your SNES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-run---the-supreme-4wd-challenge-japan', 'SNES', 'Big Run - The Supreme 4WD Challenge (Japan)', '1991', 'Racing', 'SEGA', '1', 'Top-down off-road racing', 'Off-road rally racing simulation based on the Paris-Dakar rally.', 'Navigate treacherous desert terrain to reach the finish line first.', 'Race across the desert in Big Run: The Supreme 4WD Challenge for SNES.', 'A challenging rally racer that tasks players with managing their vehicle''s health while driving at high speeds through challenging 16-bit desert environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-sky-trooper-europe', 'SNES', 'Big Sky Trooper (Europe)', '1995', 'Action', 'Sculptured Software', '1', 'Isometric sci-fi action', 'Top-down action game with sci-fi themes and planetary exploration.', 'Travel between planets to complete missions and stop the space invaders.', 'Save the galaxy in the quirky action game Big Sky Trooper for SNES.', 'From the creators of Maniac Mansion, this title features a mix of ship combat and on-foot exploration. Use your power suit to clear planets of the "Slug" menace.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-sky-trooper-usa', 'SNES', 'Big Sky Trooper (USA)', '1995', 'Action', 'Sculptured Software', '1', 'Isometric sci-fi action', 'Top-down action game with sci-fi themes and planetary exploration.', 'Travel between planets to complete missions and stop the space invaders.', 'Save the galaxy in the quirky action game Big Sky Trooper for SNES.', 'From the creators of Maniac Mansion, this title features a mix of ship combat and on-foot exploration. Use your power suit to clear planets of the "Slug" menace.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-sky-trooper-usa-beta', 'SNES', 'Big Sky Trooper (USA) (Beta)', '1995', 'Action', 'Sculptured Software', '1', 'Isometric sci-fi action', 'Top-down action game with sci-fi themes and planetary exploration.', 'Travel between planets to complete missions and stop the space invaders.', 'Explore the Big Sky Trooper Beta and its development on SNES.', 'A pre-release build of the space adventure. Discover early mission structures and mechanics that defined this unique LucasArts-style action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bijo-to-yajuu-japan', 'SNES', 'Bijo to Yajuu (Japan)', '1993', 'Adventure', 'Towachiki', '1', 'Visual novel adventure', 'Action platformer where the player controls the Beast through various environments.', 'Defeat Gaston and break the enchantement to become human again.', 'Experience the Disney classic with Bijo to Yajuu for the Super Famicom.', 'The Japanese version of Beauty and the Beast. Help the Beast overcome his enemies and find love to restore his human form in this 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bike-daisuki!-hashiriya-damashii---riders-spirits-japan', 'SNES', 'Bike Daisuki! Hashiriya Damashii - Rider''s Spirits (Japan)', '1993', 'Racing', 'Sega', '1', 'Arcade motorcycle racing', 'Combat racing game featuring motorcycle-riding spirits and special weapons.', 'Win high-speed races by using items and drifts to outplay rivals.', 'Experience supernatural motorcycle racing in Bike Daisuki! Hashiriya Damashii.', 'Known as Rider''s Spirits, this title is a motorcycle-themed alternative to Mario Kart. Features diverse characters, tight drifting mechanics, and competitive 16-bit racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('biker-mice-from-mars-europe', 'SNES', 'Biker Mice from Mars (Europe)', '1994', 'Action Platformer', 'Konami', '2', 'Cartoon action platformer', 'Isometric combat racing game featuring the iconic cartoon characters.', 'Win the planetary races and defeat the evil Lawrence Limburger.', 'Ride with the Biker Mice from Mars in this intense SNES racer.', 'One of the best isometric racers on the system. Use weapons, turbos, and the unique abilities of Throttle, Modo, and Vinnie to dominate the track.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('biker-mice-from-mars-usa', 'SNES', 'Biker Mice from Mars (USA)', '1994', 'Action Platformer', 'Konami', '2', 'Cartoon action platformer', 'Isometric combat racing game featuring the iconic cartoon characters.', 'Win the planetary races and defeat the evil Lawrence Limburger.', 'Ride with the Biker Mice from Mars in this intense SNES racer.', 'One of the best isometric racers on the system. Use weapons, turbos, and the unique abilities of Throttle, Modo, and Vinnie to dominate the track.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bill-laimbeers-combat-basketball-usa', 'SNES', 'Bill Laimbeer''s Combat Basketball (USA)', '1991', 'Sports', 'Electronic Arts', '2', 'Arcade basketball', 'Futuristic 2-on-2 basketball with no rules and heavy physical combat.', 'Outscore the opponent in a dystopian basketball tournament.', 'Play the brutal Bill Laimbeer''s Combat Basketball on SNES.', 'A unique sports hybrid where checking and physical violence are part of the game. Set in the year 2030, customize your robotic team to win by any means necessary.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bill-walsh-college-football-usa', 'SNES', 'Bill Walsh College Football (USA)', '1993', 'Sports', 'Electronic Arts', '2', 'College football simulation', 'College football simulation featuring authentic teams and formations.', 'Lead your college team to the bowl game victory.', 'Experience the intensity of Bill Walsh College Football on the SNES.', 'A classic American football title focusing on the college game. Features a wide variety of schools, playbooks, and the quest for the national championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bing-bing!-bingo-japan', 'SNES', 'Bing Bing! Bingo (Japan)', '1993', 'Board Game', 'Compile', '2', 'Bingo board game', 'Bingo-themed party game with various mini-games and anime-style characters.', 'Be the first to complete a bingo pattern and win the tournament.', 'Enjoy competitive bingo fun in Bing Bing! Bingo for the SNES.', 'A quirky Japanese title that turns the classic game of Bingo into a high-energy competition. Featuring colorful characters, multiple game modes, and interactive mini-games to spice up the 16-bit gambling experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bio-metal-europe', 'SNES', 'Bio Metal (Europe)', '1993', 'Shoot ''em up', 'Athena', '1', 'Horizontal sci-fi shooter', 'Side-scrolling shoot ''em up with an innovative "GAM" shield mechanic.', 'Destroy the biological alien invaders to save the human race.', 'Blast through enemies in the intense shooter Bio Metal on SNES.', 'Experience high-speed aerial combat with a twist. Master the orb-based shield system that can both protect your ship and be used as a devastating projectile weapon against alien bio-forms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bio-metal-japan', 'SNES', 'Bio Metal (Japan)', '1993', 'Shoot ''em up', 'Athena', '1', 'Horizontal sci-fi shooter', 'Side-scrolling shoot ''em up with an innovative "GAM" shield mechanic.', 'Destroy the biological alien invaders to save the human race.', 'Blast through enemies in the intense shooter Bio Metal on SNES.', 'The Japanese version of the sci-fi SHMUP. While the US version featured a Techno soundtrack, the original Japanese release offers a classic 16-bit arcade score to accompany the intense action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bio-metal-usa', 'SNES', 'Bio Metal (USA)', '1993', 'Shoot ''em up', 'Athena', '1', 'Horizontal sci-fi shooter', 'Side-scrolling shoot ''em up with an innovative "GAM" shield mechanic.', 'Destroy the biological alien invaders to save the human race.', 'Blast through enemies in the intense shooter Bio Metal on SNES.', 'Face waves of organic and mechanical threats. Use your rotating energy orbs strategically to navigate through narrow corridors and defeat screen-filling bosses in this technical shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishin-densetsu-zoku-japan', 'SNES', 'Bishin Densetsu Zoku (Japan)', '1993', 'Action', 'Riverhillsoft', '1', 'Erotic action adventure', 'Racing and combat hybrid set in a post-apocalyptic or "bosozoku" rebel world.', 'Win high-stakes street races and defeat rival gang members in combat.', 'Experience rebel street racing in Bishin Densetsu Zoku for SNES.', 'A unique Japanese title that blends top-down racing with side-scrolling fighting. Customize your vehicle and battle your way through rival territories to prove your dominance in the gang world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-janshi-suchie-pie-japan', 'SNES', 'Bishoujo Janshi Suchie-Pie (Japan)', '1994', 'Gambling', 'Jaleco', '1', 'Mahjong simulation', 'Mahjong simulation featuring anime-style female characters and special moves.', 'Defeat various opponents in Mahjong matches to progress through the story.', 'Play anime-style Mahjong in Bishoujo Janshi Suchie-Pie on SNES.', 'Join the "Suchie-Pie" magical girls in this colorful Mahjong title. Utilize special powers and "cheats" to win rounds and unlock beautiful 16-bit character art and story sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-janshi-suchie-pie-japan-rev-a', 'SNES', 'Bishoujo Janshi Suchie-Pie (Japan) (Rev A)', '1994', 'Gambling', 'Jaleco', '1', 'Mahjong simulation', 'Mahjong simulation featuring anime-style female characters and special moves.', 'Defeat various opponents in Mahjong matches to progress through the story.', 'Play anime-style Mahjong in Bishoujo Janshi Suchie-Pie on SNES.', 'The revised version of the popular Mahjong title, featuring polished gameplay mechanics and character interactions in a vibrant anime-themed gambling simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailormoon---another-story-japan', 'SNES', 'Bishoujo Senshi Sailormoon - Another Story (Japan)', '1995', 'RPG', 'Angel', '1', 'Turn-based story RPG', 'Turn-based JRPG featuring the iconic Sailor Scouts and a deep narrative.', 'Protect the Silver Crystal and stop a mysterious new threat to the timeline.', 'Experience the epic Sailor Moon RPG: Another Story on the SNES.', 'A massive JRPG that spans across multiple locations from the anime. Form teams with all the Sailor Scouts, use their signature attacks, and experience an original story unique to the SNES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailormoon---another-story-japan-en-by-fusoya-v10-~pretty-soldier-sailor-moon---another-story', 'SNES', 'Bishoujo Senshi Sailormoon - Another Story (Japan) [En by FuSoYa v1.0] (~Pretty Soldier Sailor Moon - Another Story)', '1995', 'RPG', 'Angel', '1', 'Turn-based story RPG', 'Turn-based JRPG featuring the iconic Sailor Scouts and a deep narrative.', 'Protect the Silver Crystal and stop a mysterious new threat to the timeline.', 'Play the English translation of Sailor Moon: Another Story on SNES.', 'The definitive way for Western fans to experience the Sailor Moon RPG. This fan translation makes the deep story, menu systems, and specialized combat accessible to all English speakers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailormoon---another-story-t-eng-v208', 'SNES', 'Bishoujo Senshi Sailormoon - Another Story (T-Eng v2.08)', '1995', 'RPG', 'Angel', '1', 'Turn-based story RPG', 'Turn-based JRPG featuring the iconic Sailor Scouts and a deep narrative.', 'Protect the Silver Crystal and stop a mysterious new threat to the timeline.', 'Play the English translation of Sailor Moon: Another Story on SNES.', 'An updated fan translation version featuring refined text and technical fixes. Help the Sailor Scouts face their past and future in this 16-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailormoon-japan', 'SNES', 'Bishoujo Senshi Sailormoon (Japan)', '1993', 'Beat ''em up', 'Angel', '2', 'Anime brawler', 'Side-scrolling beat ''em up featuring the five original Sailor Scouts.', 'Defeat the Dark Kingdom''s minions and stop Queen Beryl.', 'Battle as the Sailor Scouts in Bishoujo Senshi Sailormoon for SNES.', 'A classic brawler where you can play as Moon, Mercury, Mars, Jupiter, or Venus. Use each scout''s unique magic attacks to clear waves of enemies in various urban Tokyo environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailormoon-r-japan', 'SNES', 'Bishoujo Senshi Sailormoon R (Japan)', '1993', 'Beat ''em up', 'Angel', '2', 'Anime brawler', 'Side-scrolling beat ''em up based on the "R" season of the anime.', 'Rescue Chibiusa and defeat the Black Moon Clan invaders.', 'Continue the fight in Bishoujo Senshi Sailormoon R for the SNES.', 'The sequel adds more moves and playable characters. Features a fun "Chibiusa" mode for younger players and improved 16-bit graphics that capture the anime''s aesthetic perfectly.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailormoon-r-japan-en-by-fusoya-v10-~pretty-soldier-sailor-moon-r', 'SNES', 'Bishoujo Senshi Sailormoon R (Japan) [En by FuSoYa v1.0] (~Pretty Soldier Sailor Moon R)', '1993', 'Beat ''em up', 'Angel', '2', 'Anime brawler', 'Side-scrolling beat ''em up based on the "R" season of the anime.', 'Rescue Chibiusa and defeat the Black Moon Clan invaders.', 'Play Sailor Moon R in English with this SNES fan translation.', 'Now fully playable in English, follow the scouts as they battle through the "R" story arc. Experience the full narrative and combat moves of the second 16-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailormoon-s---jougai-rantou!-shuyaku-soudatsusen-japan', 'SNES', 'Bishoujo Senshi Sailormoon S - Jougai Rantou! Shuyaku Soudatsusen (Japan)', '1994', 'Beat ''em up', 'Angel', '2', 'Anime arena brawler', 'One-on-one fighting game featuring the Sailor Scouts with special moves.', 'Defeat the other scouts to determine who the strongest protector is.', 'Engage in Sailor Moon fighting action in this SNES combat title.', 'A competitive 2D fighter featuring fluid animation and a roster of favorite scouts. Master each character''s signature special attacks in fast-paced 16-bit duels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailormoon-s---kondo-wa-puzzle-de-oshioki-yo!-japan', 'SNES', 'Bishoujo Senshi Sailormoon S - Kondo wa Puzzle de Oshioki yo! (Japan)', '1995', 'Puzzle', 'Angel', '2', 'Anime puzzle game', 'Competitive puzzle game featuring falling blocks and Sailor Moon characters.', 'Outplay your opponent by clearing puzzle blocks and triggering attacks.', 'Enjoy Sailor Moon puzzle action in Kondo wa Puzzle de Oshioki yo!', 'A vibrant and addictive puzzle title. Compete against the computer or a friend, using strategic clears to send obstacles to your rival''s board in this anime-themed experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailormoon-s---kurukkurin-japan', 'SNES', 'Bishoujo Senshi Sailormoon S - Kurukkurin (Japan)', '1995', 'Action', 'Angel', '1', 'Arcade reflex action', 'A unique action-puzzle game where players move and rotate characters.', 'Clear the board and achieve high scores in this themed puzzle challenge.', 'Play the quirky Sailor Moon puzzle game Kurukkurin on SNES.', 'Unlike traditional block puzzles, Kurukkurin features a rotating mechanic centered around the characters. It''s a charming and visually bright title for puzzle and anime fans alike.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailormoon-sailor-stars---fuwa-fuwa-panic-2-japan-st', 'SNES', 'Bishoujo Senshi Sailormoon Sailor Stars - Fuwa Fuwa Panic 2 (Japan) (ST)', '1996', 'Action', 'Angel', '1', 'Chibi anime action', 'Competitive balloon-popping puzzle game with a story mode and multiplayer.', 'Popping more balloons than the opponent to win matches.', 'Experience the high-speed puzzle fun of Fuwa Fuwa Panic 2 for SNES.', 'Based on the Sailor Stars arc, this competitive puzzle game tasks players with clearing their screen of colorful balloons using speed and special power-ups from the scouts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailormoon-super-s---fuwa-fuwa-panic-english', 'SNES', 'Bishoujo Senshi Sailormoon Super S - Fuwa Fuwa Panic (English)', '1995', 'Puzzle', 'Angel', '2', 'Anime puzzle game', 'Competitive balloon-popping puzzle game, now accessible in English.', 'Popping more balloons than the opponent to win matches.', 'Play Fuwa Fuwa Panic in English with this SNES fan translation.', 'The first installment of the "Fuwa Fuwa" series, now translated for Western players. Enjoy the fast-paced balloon-popping gameplay with your favorite Sailor Moon characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailormoon-super-s---fuwa-fuwa-panic-japan', 'SNES', 'Bishoujo Senshi Sailormoon Super S - Fuwa Fuwa Panic (Japan)', '1995', 'Puzzle', 'Angel', '2', 'Anime puzzle game', 'Competitive balloon-popping puzzle game with a story mode and multiplayer.', 'Popping more balloons than the opponent to win matches.', 'Experience the high-speed puzzle fun of Fuwa Fuwa Panic for SNES.', 'The original Japanese release of the Super S themed puzzle game. Features beautiful 16-bit character sprites and intense competitive gameplay for one or two players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailormoon-super-s---zenin-sanka!!-shuyaku-soudatsusen-japan', 'SNES', 'Bishoujo Senshi Sailormoon Super S - Zenin Sanka!! Shuyaku Soudatsusen (Japan)', '1995', 'Beat ''em up', 'Angel', '2', 'Anime arena brawler', 'Expanded one-on-one fighting game with more characters and refined moves.', 'Win the tournament and prove your strength as a Sailor Scout.', 'Battle as your favorite scout in Zenin Sanka!! Super S for SNES.', 'The final 2D fighting game in the SNES series, featuring characters from the Super S season. Offers more balanced mechanics and more playable fighters than its predecessors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-wrestler-retsuden---blizzard-yuki-rannyuu!!-japan', 'SNES', 'Bishoujo Wrestler Retsuden - Blizzard Yuki Rannyuu!! (Japan)', '1994', 'Fighting', 'Athena', '2', 'Wrestling action', 'Female professional wrestling simulation with management elements.', 'Lead your wrestler to the top of the championship through skill and training.', 'Enter the ring in Bishoujo Wrestler Retsuden for the SNES.', 'Focuses on the world of "joshi" wrestling. Manage your fighter''s training and execute powerful moves in the ring to win the 16-bit championship title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blackhawk-europe-enfrde', 'SNES', 'Blackhawk (Europe) (En,Fr,De)', '1992', 'Shoot ''em up', 'Atelier Double', '1', 'Helicopter combat shooter', 'Cinematic action platformer featuring cover-based shooting and exploration.', 'Navigate a dark alien world and lead your people to freedom.', 'Survive the brutal world of Blackhawk (Blackthorne) on the SNES.', 'Known as Blackthorne in the US. Play as Kyle Vlaros in this cinematic platformer. Use a shotgun and tactical cover to defeat orc-like enemies and reclaim your throne.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blackthorne---fukushuu-no-kuroki-kyoku-japan', 'SNES', 'Blackthorne - Fukushuu no Kuroki Kyoku (Japan)', '1994', 'Action Platformer', 'Blizzard Entertainment', '1', 'Cinematic action platformer', 'Cinematic action platformer featuring cover-based shooting and exploration.', 'Navigate a dark alien world and lead your people to freedom.', 'Experience the epic revenge story in Blackthorne for the SNES.', 'The Japanese release of the Blizzard classic. Features detailed rotoscoped animation, a mature storyline, and intense tactical combat that was ahead of its time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blackthorne-usa', 'SNES', 'Blackthorne (USA)', '1994', 'Action Platformer', 'Blizzard Entertainment', '1', 'Cinematic action platformer', 'Cinematic action platformer featuring cover-based shooting and exploration.', 'Navigate a dark alien world and lead your people to freedom.', 'Experience the epic revenge story in Blackthorne for the SNES.', 'Master the art of shooting behind your back and utilizing environmental hazards. Blackthorne is a standout title for fans of "Prince of Persia" style cinematic platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blackthorne-usa-beta', 'SNES', 'Blackthorne (USA) (Beta)', '1994', 'Action Platformer', 'Blizzard Entertainment', '1', 'Cinematic action platformer', 'Cinematic action platformer featuring cover-based shooting and exploration.', 'Navigate a dark alien world and lead your people to freedom.', 'Explore the Blackthorne Beta and its development on SNES.', 'A pre-release build of the cinematic shooter. This version allows players to see early level designs and mechanical tweaks before the final 16-bit release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blazeon---the-bio-cyborg-challenge-usa', 'SNES', 'BlaZeon - The Bio-Cyborg Challenge (USA)', '1992', 'Shoot ''em up', 'Hudson Soft', '1', 'Arcade sci-fi shooter', 'Side-scrolling shoot ''em up where the player can hijack and pilot enemy robots.', 'Destroy the bio-mechanical invaders to save humanity.', 'Pilot enemy mechs in the intense shooter BlaZeon for SNES.', 'Featuring a unique "morphing" system, BlaZeon allows you to capture enemy robots and use their weapon systems as your own. Navigate through 16-bit space environments and defeat massive bio-cyborg bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blazeon-japan', 'SNES', 'BlaZeon (Japan)', '1992', 'Shoot ''em up', 'Hudson Soft', '1', 'Arcade sci-fi shooter', 'Side-scrolling shoot ''em up where the player can hijack and pilot enemy robots.', 'Destroy the bio-mechanical invaders to save humanity.', 'Pilot enemy mechs in the intense shooter BlaZeon for SNES.', 'Featuring a unique "morphing" system, BlaZeon allows you to capture enemy robots and use their weapon systems as your own. Navigate through 16-bit space environments and defeat massive bio-cyborg bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blazing-skies-europe', 'SNES', 'Blazing Skies (Europe)', '1993', 'Shoot ''em up', 'The Sales Curve', '1', 'Aerial combat shooter', 'First-person aerial combat simulation set during World War II.', 'Complete various bombing and dogfighting missions across different theaters.', 'Take to the skies in the WWII flight sim Blazing Skies for SNES.', 'Engage in intense dogfights and strategic bombing runs. Blazing Skies offers a detailed 16-bit simulation of classic air combat with various mission objectives and realistic physics for its time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('block-kuzushi-japan', 'SNES', 'Block Kuzushi (Japan)', '1999', 'Arcade', 'Nintendo', '2', 'Brick breaker', 'Classic brick-breaking arcade gameplay with power-ups.', 'Clear all the blocks on each stage using a ball and paddle.', 'Enjoy classic arcade fun in Block Kuzushi for the Super Famicom.', 'A straightforward and addictive "Arkanoid" style game. Use your reflexes to keep the ball in play, collect items, and clear increasingly difficult patterns of blocks in this Japanese 16-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blue-crystal-rod-the-japan', 'SNES', 'Blue Crystal Rod, The (Japan)', '1994', 'Action RPG', 'Namco', '1', 'Dark fantasy RPG', 'Action-adventure with light RPG elements and top-down exploration.', 'Protect the sacred rod and stop the dark forces from awakening.', 'Experience the fantasy adventure of The Blue Crystal Rod on SNES.', 'Part of the "Babylonian Castle Saga," this title features charming 16-bit graphics and a focus on story and character interaction. Navigate a magical world to fulfill your destiny.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blues-brothers-the-europe', 'SNES', 'Blues Brothers, The (Europe)', '1991', 'Platformer', 'Titus', '2', 'Comedy platformer', 'Side-scrolling platformer based on the iconic musical characters.', 'Navigate through the city and escape the law to make it to the big concert.', 'Join the band in The Blues Brothers platformer for the SNES.', 'Play as Jake or Elwood. Dodge the police, jump over obstacles, and collect records across various urban levels inspired by the movie in this fun 16-bit musical adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blues-brothers-the-europe-beta', 'SNES', 'Blues Brothers, The (Europe) (Beta)', '1991', 'Platformer', 'Titus', '2', 'Comedy platformer', 'Side-scrolling platformer based on the iconic musical characters.', 'Navigate through the city and escape the law to make it to the big concert.', 'Explore the Blues Brothers Beta and its development on SNES.', 'A pre-release version of the platformer. See early level layouts and test the core gameplay mechanics before the final 16-bit release.');
