INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bobbys-world-usa-proto', 'SNES', 'Bobby''s World (USA) (Proto)', '1994', 'Platformer', 'High Voltage Software', '1', 'Cartoon platformer', 'Side-scrolling action platformer based on the animated series.', 'Navigate through Bobby''s imagination to overcome everyday obstacles.', 'Experience the unreleased Bobby''s World prototype on SNES.', 'A rare look at a cancelled project. Help Bobby navigate through colorful, imaginative worlds based on the popular 90s cartoon, featuring unique platforming challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokujou-monogatari-japan', 'SNES', 'Bokujou Monogatari (Japan)', '1996', 'Simulation', 'Pack-In-Video', '1', 'Farming life simulation', 'Pioneering farming and life simulation with social and time management elements.', 'Successfully run a farm while building relationships in the village.', 'Start your farm life in the original Bokujou Monogatari for SNES.', 'Known as Harvest Moon in the West. Plant crops, raise livestock, and get married in this classic 16-bit sim that started the entire farming genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokujou-monogatari-japan-rev-a', 'SNES', 'Bokujou Monogatari (Japan) (Rev A)', '1996', 'Simulation', 'Pack-In-Video', '1', 'Farming life simulation', 'Pioneering farming and life simulation with social and time management elements.', 'Successfully run a farm while building relationships in the village.', 'Start your farm life in the original Bokujou Monogatari for SNES.', 'The revised Japanese version of the classic farming sim. Experience refined mechanics and seasonal events as you work to build the most prosperous farm in the land.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-b-daman-japan', 'SNES', 'Bomberman B-Daman (Japan)', '1996', 'Action', 'Hudson Soft', '2', 'Marble shooting action', 'Top-down puzzle game based on the marble-shooting B-Daman toy line.', 'Clear various grid-based puzzles by strategically shooting marbles.', 'Solve marble puzzles in Bomberman B-Daman for the SNES.', 'A unique crossover that blends Bomberman characters with B-Daman mechanics. Think fast and aim carefully to clear stages in this addictive 16-bit puzzle title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bombuzal-japan', 'SNES', 'Bombuzal (Japan)', '1993', 'Puzzle', 'Teeny Weeny Games', '1', 'Isometric puzzle', 'Isometric puzzle game focused on detonating explosives strategically.', 'Destroy all bombs on the board without getting caught in the blast.', 'Master explosives in the challenging puzzle game Bombuzal for SNES.', 'Navigate a series of increasingly complex levels. You must figure out the correct sequence to trigger bombs while ensuring you have a safe path to the exit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bonkers---hollywood-daisakusen!-japan', 'SNES', 'Bonkers - Hollywood Daisakusen! (Japan)', '1994', 'Platformer', 'Tose', '1', 'Cartoon action platformer', 'Action platformer featuring the erratic bobcat from the Disney series.', 'Solve mysteries in Hollywood and stop the toon villains.', 'Join the wacky fun in Bonkers: Hollywood Daisakusen for SNES.', 'Control Bonkers D. Bobcat in a series of colorful levels. Use your agility and toon gadgets to defeat enemies and solve cases in this 16-bit Disney adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bonkers-usa', 'SNES', 'Bonkers (USA)', '1994', 'Platformer', 'Tose', '1', 'Cartoon action platformer', 'Action platformer featuring the erratic bobcat from the Disney series.', 'Solve mysteries in Hollywood and stop the toon villains.', 'Join the wacky fun in Bonkers: Hollywood Daisakusen for SNES.', 'Control Bonkers D. Bobcat in a series of colorful levels. Use your agility and toon gadgets to defeat enemies and solve cases in this 16-bit Disney adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boogerman---a-pick-and-flick-adventure-europe', 'SNES', 'Boogerman - A Pick and Flick Adventure (Europe)', '1994', 'Platformer', 'Interplay Productions', '1', 'Gross-out cartoon platformer', 'Gross-out themed side-scrolling platformer with unique projectile mechanics.', 'Navigate through a world of filth to defeat the Boogerman and save the day.', 'Play the hilarious Boogerman: A Pick and Flick Adventure on SNES.', 'Use burps, farts, and nose-flicks as weapons. This 16-bit platformer is famous for its "gross" humor, detailed animation, and creative level design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boogerman---a-pick-and-flick-adventure-usa', 'SNES', 'Boogerman - A Pick and Flick Adventure (USA)', '1994', 'Platformer', 'Interplay Productions', '1', 'Gross-out cartoon platformer', 'Gross-out themed side-scrolling platformer with unique projectile mechanics.', 'Navigate through a world of filth to defeat the Boogerman and save the day.', 'Play the hilarious Boogerman: A Pick and Flick Adventure on SNES.', 'Use burps, farts, and nose-flicks as weapons. This 16-bit platformer is famous for its "gross" humor, detailed animation, and creative level design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boogerman-camera-fix', 'SNES', 'Boogerman Camera Fix', '2023', 'Utility', 'ROM Hack', '1', 'Technical camera fix', 'Gross-out themed side-scrolling platformer with unique projectile mechanics.', 'Navigate through a world of filth to defeat the Boogerman and save the day.', 'Experience Boogerman with an improved camera fix on the SNES.', 'A fan-made modification that improves the player''s view and scrolling, making the platforming and gross-out combat much smoother and more enjoyable.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bounty-sword-japan', 'SNES', 'Bounty Sword (Japan)', '1995', 'RPG', 'ITL', '1', 'Tactical fantasy RPG', 'Tactical turn-based RPG with an isometric view and high-fantasy setting.', 'Lead your mercenary band to victory in a world of war and magic.', 'Master tactical combat in Bounty Sword for the Super Famicom.', 'A deep strategy RPG featuring complex unit management, beautiful sprite art, and a compelling narrative. Strategize your movements and attacks to dominate the 16-bit battlefield.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowser-jrs-adventure', 'SNES', 'Bowser Jr''s Adventure', '2021', 'Platformer', 'Homebrew', '1', 'Fan-made Mario-style platformer', 'Unknown', 'Unknown', 'Join Bowser Jr. in his unique SNES fan adventure.', 'A community-created title or modification featuring the heir to the Koopa throne in a series of new platforming challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boxing-legends-of-the-ring-europe', 'SNES', 'Boxing Legends of the Ring (Europe)', '1993', 'Sports', 'Sculptured Software', '2', 'Boxing simulation', 'Realistic boxing simulation featuring legendary real-world fighters.', 'Climb the rankings and defeat champions to win the world title belt.', 'Box with legends in Boxing Legends of the Ring for the SNES.', 'Experience tactical 16-bit boxing. Manage your stamina, land precise combos, and face off against icons like Julio César Chávez and Sugar Ray Leonard.');
