INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brainies-the-europe', 'SNES', 'Brainies, The (Europe)', '1991', 'Puzzle', 'Titus France', '2', 'Logic puzzle game', 'Tile-based puzzle game where you move characters to specific targets.', 'Move all the Brainies to their designated spots before time runs out.', 'Test your logic in The Brainies, a challenging SNES puzzle game.', 'A colorful and brain-teasing title where you must plan your moves carefully. Navigate obstacles and use the environment to guide your characters to the goal in this addictive 16-bit puzzler.');
