INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brandish-2---expert-japan', 'SNES', 'Brandish 2 - Expert (Japan)', '1993', 'Action RPG', 'Nihon Falcom', '1', 'Isometric dungeon crawler', 'Hardcore overhead dungeon crawler with increased difficulty and new challenges.', 'Master the most difficult floors of the labyrinth to prove your skill.', 'Face the ultimate challenge in Brandish 2 Expert for the SNES.', 'A special edition of the sequel designed for veteran players. Features redesigned, more difficult floor layouts and tougher enemy encounters for the ultimate test of survival.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brandish-2---the-planet-buster-japan', 'SNES', 'Brandish 2 - The Planet Buster (Japan)', '1993', 'Action RPG', 'Nihon Falcom', '1', 'Isometric dungeon crawler', 'Expanded overhead dungeon crawler with a larger world and improved combat.', 'Journey through the kingdom of Bundivia to reclaim the Planet Buster sword.', 'Experience the epic sequel Brandish 2: The Planet Buster on SNES.', 'The sequel improves the controls and expands the lore. Featuring dual-wielding, new magic, and a massive world to explore using the series'' signature rotating perspective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brawl-brothers---rival-turf!-2-europe', 'SNES', 'Brawl Brothers - Rival Turf! 2 (Europe)', '1994', 'Beat ''em up', 'Jaleco', '2', 'Co-op street brawler', 'Belt-scrolling beat ''em up featuring multiple playable characters and combos.', 'Rescue the kidnapped martial arts masters from the criminal syndicate.', 'Fight through the streets in Brawl Brothers, the SNES brawler sequel.', 'Known in Japan as Rival Turf! 2, this game features refined combat, secret characters, and an "Angry" mode that boosts your power when taking damage.');
