INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breakthru!-usa', 'SNES', 'BreakThru! (USA)', '1994', 'Action', 'Data East', '2', 'Arcade-style action shooter', 'Fast-paced falling block puzzle game with various themes and difficulty levels.', 'Clear the board of colorful tiles before they stack to the top.', 'Enjoy addictive puzzle action in BreakThru! for the SNES.', 'A simple yet challenging puzzle title where you match blocks to clear them. Features different backgrounds and increasing speed to test your reflexes and 16-bit strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire---ryuu-no-senshi-japan', 'SNES', 'Breath of Fire - Ryuu no Senshi (Japan)', '1993', 'RPG', 'Capcom', '1', 'Turn-based fantasy RPG', 'Classic turn-based JRPG featuring a protagonist who can transform into dragons.', 'Lead the Light Dragon Clan to stop the Dark Dragon Empire''s world conquest.', 'Start the epic saga with Breath of Fire on the SNES.', 'Capcom''s flagship RPG series debuts with beautiful sprite art and a deep story. Help Ryu and Nina gather allies and master the power of the dragon to save the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-usa', 'SNES', 'Breath of Fire (USA)', '1993', 'RPG', 'Capcom', '1', 'Turn-based fantasy RPG', 'Classic turn-based JRPG featuring a protagonist who can transform into dragons.', 'Lead the Light Dragon Clan to stop the Dark Dragon Empire''s world conquest.', 'Start the epic saga with Breath of Fire on the SNES.', 'Capcom''s flagship RPG series debuts with beautiful sprite art and a deep story. Help Ryu and Nina gather allies and master the power of the dragon to save the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-ii---shimei-no-ko-japan', 'SNES', 'Breath of Fire II - Shimei no Ko (Japan)', '1994', 'RPG', 'Capcom', '1', 'Turn-based fantasy RPG', 'Deep turn-based JRPG with a focus on character-driven story and town building.', 'Investigate the mystery of the "Abyss" and clear Ryu''s family name.', 'Experience the masterpiece Breath of Fire II on the SNES.', 'The sequel introduces a town-building mechanic and a fusion system for party members. Featuring a dark, mature storyline and improved 16-bit combat and visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-ii---shimei-no-ko-japan-rev-a-np', 'SNES', 'Breath of Fire II - Shimei no Ko (Japan) (Rev A) (NP)', '1994', 'RPG', 'Capcom', '1', 'Turn-based fantasy RPG', 'Deep turn-based JRPG with a focus on character-driven story and town building.', 'Investigate the mystery of the "Abyss" and clear Ryu''s family name.', 'Experience the masterpiece Breath of Fire II on the SNES.', 'The revised Nintendo Power version, featuring minor bug fixes and optimizations for a smoother 16-bit role-playing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-ii-europe', 'SNES', 'Breath of Fire II (Europe)', '1995', 'RPG', 'Capcom', '1', 'Turn-based fantasy RPG', 'Deep turn-based JRPG with a focus on character-driven story and town building.', 'Investigate the mystery of the "Abyss" and clear Ryu''s family name.', 'Experience the masterpiece Breath of Fire II on the SNES.', 'The European release of the classic RPG. Join Ryu on his quest through a world filled with magic, dragons, and high-stakes 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-ii-usa', 'SNES', 'Breath of Fire II (USA)', '1995', 'RPG', 'Capcom', '1', 'Turn-based fantasy RPG', 'Deep turn-based JRPG with a focus on character-driven story and town building.', 'Investigate the mystery of the "Abyss" and clear Ryu''s family name.', 'Experience the masterpiece Breath of Fire II on the SNES.', 'The North American release. Explore a vast world, manage your town, and unleash dragon powers in one of the system''s most beloved RPGs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-ii-usa-beta', 'SNES', 'Breath of Fire II (USA) (Beta)', '1995', 'RPG', 'Capcom', '1', 'Turn-based fantasy RPG', 'Deep turn-based JRPG with a focus on character-driven story and town building.', 'Investigate the mystery of the "Abyss" and clear Ryu''s family name.', 'Explore the Breath of Fire II Beta for the Super Nintendo.', 'An early look at the development of this RPG classic. See early translations and mechanics as they were being polished for the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-ii-usa-en+hack-by-d4s+watercrown-v12b', 'SNES', 'Breath of Fire II (USA) [En+Hack by d4s+Watercrown v1.2b]', '1995', 'RPG', 'ROM Hack', '1', 'Rebalanced turn-based RPG', 'Deep turn-based JRPG featuring a complete fan-made re-translation and balance.', 'Experience the full story with a more accurate and polished translation.', 'Play the definitive version of Breath of Fire II with this SNES hack.', 'This version fixes the notorious translation issues of the original release, providing a much clearer story and updated gameplay balance for a better experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-ii-usa-en+hack-by-d4s+watercrown-v12b-original-title-screen-music', 'SNES', 'Breath of Fire II (USA) [En+Hack by d4s+Watercrown v1.2b] (Original Title Screen Music)', '1995', 'RPG', 'ROM Hack', '1', 'Rebalanced turn-based RPG', 'Deep turn-based JRPG featuring a complete fan-made re-translation and music fix.', 'Experience the game with the original Japanese title screen score.', 'Enjoy the restored Breath of Fire II experience with this fan hack.', 'In addition to a superior translation, this version restores the original Japanese music that was changed for the Western release, providing the most authentic experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-ii-usa-text-hack-by-beaux-v066-translation-fix', 'SNES', 'Breath of Fire II (USA) [Text Hack by Beaux v0.66] (Translation Fix)', '1995', 'RPG', 'ROM Hack', '1', 'Translation-fixed RPG', 'Deep turn-based JRPG featuring refined dialogue and text corrections.', 'Follow the story of the Dragon Clan with fixed grammar and clarity.', 'Read the improved story of Breath of Fire II with this text hack.', 'A dedicated project to clean up the game''s script. This version ensures the narrative and character interactions flow naturally, making the 16-bit story much more engaging.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brett-hull-hockey-95-usa', 'SNES', 'Brett Hull Hockey ''95 (USA)', '1994', 'Sports', 'Radical Entertainment', '2', 'Ice hockey simulation', 'Fast-paced ice hockey simulation featuring the legendary sniper Brett Hull.', 'Lead your team to the Stanley Cup by winning the playoff series.', 'Experience pro ice hockey in Brett Hull Hockey ''95 for SNES.', 'Featuring the signature "Hull Shot," this updated edition offers improved player logic and faster gameplay. Choose your professional team and dominate the ice in this 16-bit sports classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brett-hull-hockey-europe', 'SNES', 'Brett Hull Hockey (Europe)', '1994', 'Sports', 'Radical Entertainment', '2', 'Ice hockey simulation', 'Fast-paced ice hockey simulation featuring the legendary sniper Brett Hull.', 'Lead your team to the Stanley Cup by winning the playoff series.', 'Experience pro ice hockey in Brett Hull Hockey for the SNES.', 'The original entry in the series. Master the slapshot and physical defense to climb the rankings. Features realistic hockey physics and a focus on the NHL''s biggest stars of the 90s.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brett-hull-hockey-usa', 'SNES', 'Brett Hull Hockey (USA)', '1994', 'Sports', 'Radical Entertainment', '2', 'Ice hockey simulation', 'Fast-paced ice hockey simulation featuring the legendary sniper Brett Hull.', 'Lead your team to the Stanley Cup by winning the playoff series.', 'Experience pro ice hockey in Brett Hull Hockey for the SNES.', 'The original entry in the series. Master the slapshot and physical defense to climb the rankings. Features realistic hockey physics and a focus on the NHL''s biggest stars of the 90s.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bronkie-the-bronchiasaurus-usa-enes', 'SNES', 'Bronkie the Bronchiasaurus (USA) (En,Es)', '1994', 'Platformer', 'Radium', '1', 'Educational cartoon platformer', 'Educational platformer focused on asthma management and health.', 'Navigate through levels while collecting inhalers and avoiding asthma triggers.', 'Learn and play with Bronkie the Bronchiasaurus on the SNES.', 'Part of a series of "educational health" games. Control Bronkie, a dinosaur with asthma, and learn about triggers like smoke and dust while completing traditional platforming challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brunswick-world-tournament-of-champions-usa', 'SNES', 'Brunswick World Tournament of Champions (USA)', '1994', 'Sports', 'Loriciel', '2', 'Bowling simulation', 'Realistic bowling simulation featuring professional tournament structures.', 'Win the World Tournament of Champions by mastering your bowling technique.', 'Hit the lanes in Brunswick World Tournament of Champions for SNES.', 'A detailed sports sim with authentic physics. Customize your ball''s weight and your throw''s spin to master different oil patterns and defeat the world''s best virtual bowlers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brutal---paws-of-fury-europe-enfrde', 'SNES', 'Brutal - Paws of Fury (Europe) (En,Fr,De)', '1994', 'Fighting', 'GameTek', '2', 'Anthropomorphic martial arts', 'One-on-one fighting game featuring anthropomorphic animals and a growth system.', 'Defeat all martial arts masters to prove your animal spirit''s dominance.', 'Unleash the beast in Brutal: Paws of Fury for the SNES.', 'A unique fighter where characters learn new moves as they progress. Choose from a diverse roster of animal warriors, each with their own fighting style and philosophy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brutal---paws-of-fury-usa', 'SNES', 'Brutal - Paws of Fury (USA)', '1994', 'Fighting', 'GameTek', '2', 'Anthropomorphic martial arts', 'One-on-one fighting game featuring anthropomorphic animals and a growth system.', 'Defeat all martial arts masters to prove your animal spirit''s dominance.', 'Unleash the beast in Brutal: Paws of Fury for the SNES.', 'A unique fighter where characters learn new moves as they progress. Choose from a diverse roster of animal warriors, each with their own fighting style and philosophy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brutal---paws-of-fury-usa-beta', 'SNES', 'Brutal - Paws of Fury (USA) (Beta)', '1994', 'Fighting', 'GameTek', '2', 'Anthropomorphic martial arts', 'One-on-one fighting game featuring anthropomorphic animals and a growth system.', 'Defeat all martial arts masters to prove your animal spirit''s dominance.', 'Explore the Brutal: Paws of Fury Beta version on SNES.', 'A pre-release version of the animal-themed brawler. See early move sets and character balancing as they were being developed for the final Super Nintendo release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-3-ji-no-wide-shou---98-06-gatsugou-japan', 'SNES', 'BS 3-ji no Wide Shou - 98-06 Gatsugou (Japan)', '1998', 'Variety', 'Nintendo', '1', 'Satellite variety show', 'Digital magazine/lifestyle content broadcasted via the Satellaview.', 'View news, entertainment, and cultural content from June 1998.', 'Discover the rare BS 3-ji no Wide Shou magazine for Satellaview.', 'A fascinating piece of gaming history. This was a "magazine" style broadcast that provided players with news and interactive content directly to their Super Famicom via satellite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-albert-odyssey-japan', 'SNES', 'BS Albert Odyssey (Japan)', '1996', 'RPG', 'Square', '1', 'Turn-based RPG', 'Tactical turn-based RPG content released for the Satellaview system.', 'Experience a condensed or side-story adventure in the Albert Odyssey world.', 'Explore the Satellaview exclusive BS Albert Odyssey on SNES.', 'A special broadcast version of the classic JRPG. It features the series'' signature tactical grid combat and high-fantasy storytelling in a unique episodic format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-arkanoid---doh-it-again-japan', 'SNES', 'BS Arkanoid - Doh It Again (Japan)', '1996', 'Arcade', 'Taito', '2', 'Brick breaker', 'Classic brick-breaking arcade action released via the Satellaview.', 'Clear all blocks and defeat bosses in these exclusive satellite stages.', 'Enjoy satellite-exclusive levels in BS Arkanoid for SNES.', 'This version of the classic puzzle game features unique stage layouts and challenges that were only available through the Japanese Satellaview service.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-b-dash---2-gatsugou-japan', 'SNES', 'BS B-Dash - 2 Gatsugou (Japan)', '1997', 'Action', 'Nintendo', '1', 'Satellite action demo', 'Interactive digital magazine broadcast for the Satellaview system.', 'Explore news and gaming content from the February broadcast.', 'Check out the BS B-Dash digital magazine for the Satellaview.', 'A monthly digital publication that offered SNES users in Japan news, tips, and interactive previews of upcoming games through their satellite link.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-b-dash---3-gatsugou-japan', 'SNES', 'BS B-Dash - 3 Gatsugou (Japan)', '1997', 'Action', 'Nintendo', '1', 'Satellite action demo', 'Interactive digital magazine broadcast for the Satellaview system.', 'Explore news and gaming content from the March broadcast.', 'Check out the BS B-Dash digital magazine for the Satellaview.', 'A monthly digital publication that offered SNES users in Japan news, tips, and interactive previews of upcoming games through their satellite link.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-cheap-de-gorgeous-vol-1-japan', 'SNES', 'BS Cheap de Gorgeous Vol. 1 (Japan)', '1997', 'Compilation', 'Nintendo', '1', 'Satellite mini-game collection', 'Quirky digital variety show or mini-game collection for Satellaview.', 'Participate in various interactive segments and enjoy the unique humor.', 'Experience the bizarre BS Cheap de Gorgeous on the SNES.', 'One of the more experimental Satellaview broadcasts. It featured a mix of oddball humor, digital art, and interactive elements designed for the Japanese satellite audience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-chrono-trigger---character-zukan-japan', 'SNES', 'BS Chrono Trigger - Character Zukan (Japan)', '1995', 'Reference', 'Square', '1', 'Character encyclopedia', 'Digital encyclopedia focused on the characters of the hit JRPG.', 'Explore the backstories and stats of the Chrono Trigger cast.', 'Discover the BS Chrono Trigger Character Zukan on Satellaview.', 'A must-have for fans of the legendary RPG. This digital guide provided deep lore, character profiles, and artwork that weren''t included in the main game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-chrono-trigger---jet-bike-special-japan', 'SNES', 'BS Chrono Trigger - Jet Bike Special (Japan)', '1995', 'Racing', 'Square', '1', 'Time trial racing', 'Racing mini-game based on the famous segment from Chrono Trigger.', 'Defeat Johnny in high-speed jet bike races to earn rewards.', 'Race through time in BS Chrono Trigger: Jet Bike Special for SNES.', 'A standalone expansion of the 2300 AD racing mini-game. Features improved tracks and more competitive AI for fans of the original Chrono Trigger segment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-chrono-trigger---music-library-japan', 'SNES', 'BS Chrono Trigger - Music Library (Japan)', '1995', 'Music', 'Square', '1', 'Music library', 'Digital music player featuring the iconic soundtrack of the game.', 'Listen to the legendary Yasunori Mitsuda score through your console.', 'Enjoy the BS Chrono Trigger Music Library on the Satellaview.', 'This satellite broadcast allowed players to enjoy the high-quality 16-bit soundtrack of Chrono Trigger in a dedicated jukebox-style interface on their SNES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-columbus-no-tamagoyaki---dai-1-kai-japan', 'SNES', 'BS Columbus no Tamagoyaki - Dai-1-kai (Japan)', '1996', 'Puzzle', 'Nintendo', '1', 'Puzzle game', 'Historical trivia or educational quiz game broadcast via Satellaview.', 'Answer questions correctly to learn about world history and explorers.', 'Test your knowledge in BS Columbus no Tamagoyaki for SNES.', 'Part of an educational series. This broadcast focused on historical facts and the "egg of Columbus" legend, using interactive quizzes to engage the player.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-columbus-no-tamagoyaki---dai-2-kai-japan', 'SNES', 'BS Columbus no Tamagoyaki - Dai-2-kai (Japan)', '1996', 'Puzzle', 'Nintendo', '1', 'Puzzle game', 'Historical trivia or educational quiz game broadcast via Satellaview.', 'Answer questions correctly to learn about world history and explorers.', 'Test your knowledge in BS Columbus no Tamagoyaki for SNES.', 'Part of an educational series. This broadcast focused on historical facts and the "egg of Columbus" legend, using interactive quizzes to engage the player.');
