INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-cu-on-pa-sfc-japan', 'SNES', 'BS Cu-On-Pa SFC (Japan)', '1996', 'Puzzle', 'Nintendo', '1', 'Action puzzle', 'Tile-matching puzzle game with a focus on color and pattern recognition.', 'Clear the board by matching blocks in this satellite-exclusive version.', 'Master the puzzles of BS Cu-On-Pa for the Satellaview.', 'A refined version of the cubic puzzle game. Players must rotate a cube to match colors on the floor, requiring spatial awareness and quick thinking in this 16-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-daibakushou-jinsei-gekijou-japan', 'SNES', 'BS Daibakushou Jinsei Gekijou (Japan)', '1996', 'Simulation', 'Taito', '1', 'Life simulation', 'Digital board game featuring humorous life scenarios for Satellaview.', 'Navigate the "game of life" and achieve the best possible outcome.', 'Play the satellite version of BS Daibakushou Jinsei Gekijou.', 'A digital board game where players experience various life events, from school to retirement. This Satellaview version included special seasonal content and events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-dandan-belt-conveyor---gyuunyuu-no-maki-japan', 'SNES', 'BS Dandan Belt Conveyor - Gyuunyuu no Maki (Japan)', '1996', 'Action', 'Nintendo', '1', 'Action puzzle', 'Interactive puzzle or mini-game broadcast for Satellaview.', 'Navigate the conveyor belt and complete the milk-themed tasks.', 'Enjoy the quirky BS Dandan Belt Conveyor on the SNES.', 'A unique Japanese mini-game focused on timing and coordination. Players manage a fast-moving belt to complete objectives in this charmingly odd satellite broadcast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-do-re-mi-de-fu-2!---5-10-gou-japan', 'SNES', 'BS Do-Re-Mi de Fu 2! - 5-10 Gou (Japan)', '1996', 'Educational', 'Nintendo', '1', 'Music learning program', 'Music-themed interactive broadcast or rhythm-lite experience.', 'Interact with the musical segments and enjoy the 16-bit melodies.', 'Experience the musical joy of BS Do-Re-Mi de Fu 2! on SNES.', 'Part of a recurring musical series on Satellaview. It combined beautiful 16-bit audio with interactive visual elements, providing a relaxing and creative satellite experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-do-re-mi-de-fu-2!---5-25-gou-japan', 'SNES', 'BS Do-Re-Mi de Fu 2! - 5-25 Gou (Japan)', '1996', 'Educational', 'Nintendo', '1', 'Music learning program', 'Music-themed interactive broadcast or rhythm-lite experience.', 'Interact with the musical segments and enjoy the 16-bit melodies.', 'Experience the musical joy of BS Do-Re-Mi de Fu 2! on SNES.', 'Part of a recurring musical series on Satellaview. It combined beautiful 16-bit audio with interactive visual elements, providing a relaxing and creative satellite experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-dokapon-gaiden---honoo-no-audition-japan', 'SNES', 'BS Dokapon Gaiden - Honoo no Audition (Japan)', '1996', 'RPG', 'Asmik Ace', '1', 'Board-style RPG', 'Hybrid of board game and RPG with competitive multiplayer elements.', 'Win the "Flame Audition" by outsmarting and outfighting your rivals.', 'Experience the rare BS Dokapon Gaiden on the Satellaview.', 'A satellite-exclusive entry in the Dokapon series. It combines turn-based exploration with wacky combat and betrayal mechanics, featuring a unique "audition" storyline for the Super Famicom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-dragon-quest-japan', 'SNES', 'BS Dragon Quest (Japan)', '1996', 'RPG', 'Square', '1', 'Turn-based fantasy RPG', 'Turn-based JRPG featuring a condensed version of the classic quest.', 'Navigate the kingdom of Alefgard and defeat the Dragonlord.', 'Play the legendary BS Dragon Quest via Satellaview on SNES.', 'A special broadcast version of the game that started it all. It featured rearranged music and updated 16-bit graphics, delivered in episodic chunks to Japanese players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-dragon-slayer---eiyuu-densetsu-japan', 'SNES', 'BS Dragon Slayer - Eiyuu Densetsu (Japan)', '1996', 'RPG', 'Nihon Falcom', '1', 'Classic JRPG', 'Classic turn-based RPG with a focus on party management and exploration.', 'Lead the prince on a quest to reclaim his kingdom from an evil sorcerer.', 'Experience the satellite version of BS Dragon Slayer on SNES.', 'A streamlined version of the Legend of Heroes saga. This BS version offered a focused RPG experience with high-quality 16-bit visuals and traditional turn-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-dynami-tracer-japan', 'SNES', 'BS Dynami Tracer (Japan)', '1996', 'Racing', 'Nintendo', '1', 'Time trial racing', 'Racing and action hybrid featuring futuristic vehicles and speed.', 'Complete various courses and objectives within the broadcast time.', 'Zoom through the stars in BS Dynami Tracer for the SNES.', 'A unique Square-developed title for Satellaview. It blends fast-paced racing with exploration and mini-games, set in a vibrant 16-bit sci-fi universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-f-zero-japan', 'SNES', 'BS F-Zero (Japan)', '1996', 'Racing', 'Nintendo', '1', 'Futuristic racing', 'High-speed futuristic racing utilizing Mode 7 graphics and new tracks.', 'Win the Grand Prix by outracing high-speed hovercraft rivals.', 'Master the exclusive tracks of BS F-Zero for the Satellaview.', 'The ultimate expansion of the original F-Zero. It features new vehicles and specialized tracks that were never available on the standard retail cartridge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-f-zero-grand-prix---ace-league---dai-4-shuu-japan', 'SNES', 'BS F-Zero Grand Prix - Ace League - Dai-4-shuu (Japan)', '1996', 'Racing', 'Nintendo', '1', 'Futuristic racing tournament', 'High-speed futuristic racing utilizing Mode 7 graphics and new tracks.', 'Achieve the top rank in the Ace League''s exclusive satellite tracks.', 'Race the elite Ace League in BS F-Zero Grand Prix on SNES.', 'Part of the episodic F-Zero broadcast. The Ace League offered some of the most challenging track layouts designed for veteran 16-bit pilots.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-f-zero-grand-prix---king-league---dai-3-shuu-japan', 'SNES', 'BS F-Zero Grand Prix - King League - Dai-3-shuu (Japan)', '1996', 'Racing', 'Nintendo', '1', 'Futuristic racing tournament', 'High-speed futuristic racing utilizing Mode 7 graphics and new tracks.', 'Dominate the King League to prove you are the fastest in the galaxy.', 'Conquer the King League in BS F-Zero Grand Prix for SNES.', 'This specific broadcast focused on the King League tracks, featuring complex hairpins and massive jumps that pushed the SNES hardware to its limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-f-zero-grand-prix---knight-league---dai-1-shuu-japan', 'SNES', 'BS F-Zero Grand Prix - Knight League - Dai-1-shuu (Japan)', '1996', 'Racing', 'Nintendo', '1', 'Futuristic racing tournament', 'High-speed futuristic racing utilizing Mode 7 graphics and new tracks.', 'Navigate the Knight League circuits to earn the championship title.', 'Start your engines for the Knight League in BS F-Zero on SNES.', 'The opening league of the BS F-Zero series. It introduced players to the new satellite-only content with a balanced set of futuristic racing tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-f-zero-grand-prix---queen-league---dai-2-shuu-japan', 'SNES', 'BS F-Zero Grand Prix - Queen League - Dai-2-shuu (Japan)', '1996', 'Racing', 'Nintendo', '1', 'Futuristic racing tournament', 'High-speed futuristic racing utilizing Mode 7 graphics and new tracks.', 'Master the Queen League tracks and outpace the competition.', 'Experience the Queen League in BS F-Zero Grand Prix for SNES.', 'The second league in the satellite broadcast series, offering a mid-tier difficulty spike and unique environmental hazards across the Mode 7 circuits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-f-zero-grand-prix-2---dai-1-shuu-japan', 'SNES', 'BS F-Zero Grand Prix 2 - Dai-1-shuu (Japan)', '1997', 'Racing', 'Nintendo', '1', 'Futuristic racing tournament', 'High-speed futuristic racing with updated vehicles and revamped graphics.', 'Navigate the new tracks of Grand Prix 2 to remain the champion.', 'Fly through the tracks of BS F-Zero Grand Prix 2 on SNES.', 'The direct sequel to the BS F-Zero broadcasts. It featured even more refined vehicle handling and a fresh set of tracks designed for the 16-bit speed demon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-fenek---6-getsu-japan', 'SNES', 'BS Fenek - 6 Getsu (Japan)', '1996', 'Variety', 'Nintendo', '1', 'Satellite variety content', 'Digital magazine and interactive content for the Satellaview.', 'Explore the June issue''s gaming news and lifestyle segments.', 'Check out the June edition of BS Fenek on the Satellaview.', 'An interactive "broadcast magazine" that kept Japanese gamers updated with the latest trends, tips, and hidden secrets of the Super Famicom era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-freud-no-chousenjou---1-gou-japan', 'SNES', 'BS Freud no Chousenjou - 1 Gou (Japan)', '1996', 'Puzzle', 'Nintendo', '1', 'Logic challenge game', 'Psychology-themed puzzle and quiz game based on Freudian theories.', 'Solve the mental challenges and puzzles to unlock the subconscious.', 'Test your mind in BS Freud no Chousenjou on the Satellaview.', 'A truly unique educational title that uses puzzles and interactive scenarios to explore psychological concepts in a quirky 16-bit format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-freud-no-chousenjou---2-gou-japan', 'SNES', 'BS Freud no Chousenjou - 2 Gou (Japan)', '1996', 'Puzzle', 'Nintendo', '1', 'Logic challenge game', 'Psychology-themed puzzle and quiz game based on Freudian theories.', 'Solve the mental challenges and puzzles to unlock the subconscious.', 'Test your mind in BS Freud no Chousenjou on the Satellaview.', 'The second installment of the psychological challenge series, featuring more complex riddles and deeper dives into the human mind.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-freud-no-chousenjou---3-gou-japan', 'SNES', 'BS Freud no Chousenjou - 3 Gou (Japan)', '1996', 'Puzzle', 'Nintendo', '1', 'Logic challenge game', 'Psychology-themed puzzle and quiz game based on Freudian theories.', 'Solve the mental challenges and puzzles to unlock the subconscious.', 'Test your mind in BS Freud no Chousenjou on the Satellaview.', 'Continuing the series of mental tests, this broadcast offered new interactive stories and psychological "battles" for the player to solve.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-freud-no-chousenjou---4-gou-japan', 'SNES', 'BS Freud no Chousenjou - 4 Gou (Japan)', '1996', 'Puzzle', 'Nintendo', '1', 'Logic challenge game', 'Psychology-themed puzzle and quiz game based on Freudian theories.', 'Solve the mental challenges and puzzles to unlock the subconscious.', 'Test your mind in BS Freud no Chousenjou on the Satellaview.', 'Episode four of this mental workout series, focusing on dream analysis and personality quizzes through the 16-bit lens.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-freud-no-chousenjou---5-gou-japan', 'SNES', 'BS Freud no Chousenjou - 5 Gou (Japan)', '1996', 'Puzzle', 'Nintendo', '1', 'Logic challenge game', 'Psychology-themed puzzle and quiz game based on Freudian theories.', 'Solve the mental challenges and puzzles to unlock the subconscious.', 'Test your mind in BS Freud no Chousenjou on the Satellaview.', 'A deeper exploration of Freud''s theories, packaged as a series of engaging and sometimes bizarre 16-bit mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-freud-no-chousenjou---6-gou-japan', 'SNES', 'BS Freud no Chousenjou - 6 Gou (Japan)', '1996', 'Puzzle', 'Nintendo', '1', 'Logic challenge game', 'Psychology-themed puzzle and quiz game based on Freudian theories.', 'Solve the mental challenges and puzzles to unlock the subconscious.', 'Test your mind in BS Freud no Chousenjou on the Satellaview.', 'The final chapter in the Freud series, challenging players to master their own psychology through the most difficult puzzles in the broadcast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-game-tora-no-taikoban-5-17-japan', 'SNES', 'BS Game Tora no Taikoban 5-17 (Japan)', '1996', 'Variety', 'Nintendo', '1', 'Gaming news program', 'Compilation of gaming tips, previews, and interactive demos.', 'Explore the "Tiger''s Choice" of the latest 16-bit gaming content.', 'Discover BS Game Tora no Taikoban on the Satellaview.', 'An interactive program that served as a digital "seal of approval" for recommended games, providing demos and expert tips via satellite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-game-tora-no-taikoban-5-31-japan', 'SNES', 'BS Game Tora no Taikoban 5-31 (Japan)', '1996', 'Variety', 'Nintendo', '1', 'Gaming news program', 'Compilation of gaming tips, previews, and interactive demos.', 'Explore the "Tiger''s Choice" of the latest 16-bit gaming content.', 'Discover BS Game Tora no Taikoban on the Satellaview.', 'The late-May edition of the Tiger''s Choice program, featuring updated game rankings and new interactive previews for Japanese players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-gekkan-coin-toss---deck-1-japan', 'SNES', 'BS Gekkan Coin Toss - Deck 1 (Japan)', '1996', 'Card Game', 'Nintendo', '1', 'Deck-based card game', 'Card-based strategy game or interactive digital collectible experience.', 'Build your deck and win the coin toss battles.', 'Play the rare BS Gekkan Coin Toss on the Satellaview.', 'A satellite-exclusive title focused on probability and deck management. Players competed in unique matches where a coin toss could change the entire strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-golf-daisuki!-ob-club-japan', 'SNES', 'BS Golf Daisuki! O.B. Club (Japan)', '1996', 'Sports', 'Nintendo', '1', 'Golf instruction game', 'Golf simulation with a focus on precision and course management.', 'Complete the satellite-exclusive holes with the lowest possible score.', 'Tee off in BS Golf Daisuki! O.B. Club for the SNES.', 'A detailed golf title designed for the Satellaview. It features a mix of traditional golf mechanics and quirky, broadcast-exclusive course designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-goods-press---3-gatsugou-japan', 'SNES', 'BS Goods Press - 3 Gatsugou (Japan)', '1996', 'Variety', 'Nintendo', '1', 'Product showcase program', 'Digital shopping and lifestyle magazine broadcast for Satellaview.', 'Browse the latest consumer goods and tech of March 1997.', 'Explore the March issue of BS Goods Press on the SNES.', 'A fascinating look at 90s tech and fashion. This digital magazine allowed players to "shop" and learn about the latest gadgets directly through their console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-goods-press---6-gatsugou-japan', 'SNES', 'BS Goods Press - 6 Gatsugou (Japan)', '1996', 'Variety', 'Nintendo', '1', 'Product showcase program', 'Digital shopping and lifestyle magazine broadcast for Satellaview.', 'Browse the latest consumer goods and tech of June 1997.', 'Explore the June issue of BS Goods Press on the SNES.', 'The summer edition of the digital magazine, showcasing gadgets and lifestyle products tailored for the Japanese satellite audience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-goods-press---7-gatsugou-japan', 'SNES', 'BS Goods Press - 7 Gatsugou (Japan)', '1996', 'Variety', 'Nintendo', '1', 'Product showcase program', 'Digital shopping and lifestyle magazine broadcast for Satellaview.', 'Browse the latest consumer goods and tech of July 1997.', 'Explore the July issue of BS Goods Press on the SNES.', 'Stay updated with the latest 16-bit era trends in this interactive lifestyle catalog delivered straight to the Super Famicom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-heisei-gunjin-shougi-japan', 'SNES', 'BS Heisei Gunjin Shougi (Japan)', '1996', 'Board Game', 'Nintendo', '2', 'Military shogi simulation', 'Traditional Japanese military-themed board game (Gunjin Shougi).', 'Outmaneuver the opponent''s pieces and capture their flag.', 'Play the strategic BS Heisei Gunjin Shougi on Satellaview.', 'A modernized version of the classic military board game. Use hidden unit ranks and strategic movement to win this digital 16-bit war of wits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-ikari-no-yousai-japan', 'SNES', 'BS Ikari no Yousai (Japan)', '1996', 'Action', 'Nintendo', '1', 'Action adventure episode', 'Top-down action game featuring a lone soldier infiltrating a base.', 'Defeat the enemy forces and clear the fortress of its defenders.', 'Experience the intense BS Ikari no Yousai on the SNES.', 'The satellite version of the game known as "Operation Logic Bomb." It features fast-paced shooting and tactical exploration through a high-tech labyrinth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-kaizou-chounin-shubibin-man-zero-japan', 'SNES', 'BS Kaizou Chounin Shubibin Man Zero (Japan)', '1996', 'Action Platformer', 'Nintendo', '1', 'Heroic action platformer', 'Side-scrolling beat ''em up and platformer with superhero themes.', 'Stop the alien invasion using your super-powered combat moves.', 'Play the legendary BS Shubibin Man Zero on the Satellaview.', 'A rare and highly sought-after brawler. Control a robotic hero through vibrant levels, using powerful combos and special attacks to save the day in this 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-kirby-no-omochabako---baseball-japan', 'SNES', 'BS Kirby no Omochabako - Baseball (Japan)', '1996', 'Sports', 'Nintendo', '2', 'Baseball mini-game', 'Sports mini-game featuring Kirby in a simplified baseball match.', 'Score more runs than the opponent by timing your swings and pitches.', 'Play Kirby''s 16-bit baseball in BS Kirby no Omochabako.', 'Part of the "Kirby''s Toy Box" series. A charming and accessible baseball game where you control Kirby''s team. Simple controls and vibrant 16-bit graphics make this a satellite classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-kirby-no-omochabako---guruguru-ball-japan', 'SNES', 'BS Kirby no Omochabako - Guruguru Ball (Japan)', '1996', 'Puzzle', 'Nintendo', '2', 'Physics-based ball puzzle', 'Physics-based puzzle game where you guide Kirby as a rolling ball.', 'Navigate Kirby through hazardous courses to reach the goal.', 'Guide Kirby in the rolling puzzle BS Kirby no Omochabako: Guruguru Ball.', 'A unique entry in Kirby''s Toy Box. Use timing and environmental tilt to roll Kirby through narrow paths, avoiding obstacles in this creative 16-bit puzzle experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-kirby-no-omochabako---hoshi-kuzushi-japan', 'SNES', 'BS Kirby no Omochabako - Hoshi Kuzushi (Japan)', '1996', 'Puzzle', 'Nintendo', '2', 'Brick-breaking puzzle', 'Brick-breaking action featuring Kirby as the paddle or projectile.', 'Clear all the stars on the screen to progress to the next stage.', 'Enjoy Kirby''s take on Arkanoid in BS Kirby no Omochabako: Hoshi Kuzushi.', 'Another gem from the Toy Box collection. Kirby uses his powers to break star blocks in this fast-paced and colorful 16-bit arcade-style mini-game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-kodomo-chousadan-mighty-pockets-chousa-1---junk-ya-black-no-ie-japan', 'SNES', 'BS Kodomo Chousadan Mighty Pockets Chousa 1 - Junk-ya Black no Ie (Japan)', '1996', 'Adventure', 'Nintendo', '1', 'Episodic mystery adventure', 'Isometric adventure game featuring a group of young detectives.', 'Investigate the mystery of Junk-ya Black''s house and find clues.', 'Join the young detectives in BS Kodomo Chousadan Mighty Pockets.', 'A charming Japanese adventure where you lead a squad of kids to solve environmental puzzles and interact with quirky NPCs in a beautifully detailed 16-bit world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-kodomo-chousadan-mighty-pockets-chousa-2---hanzai-toshi-big-apple-japan', 'SNES', 'BS Kodomo Chousadan Mighty Pockets Chousa 2 - Hanzai Toshi Big Apple (Japan)', '1996', 'Adventure', 'Nintendo', '1', 'Episodic mystery adventure', 'Isometric adventure game featuring a group of young detectives.', 'Navigate the "Big Apple" city and uncover a criminal conspiracy.', 'Solve crimes in the city with BS Kodomo Chousadan Mighty Pockets 2.', 'The second investigation takes the team to a metropolitan setting. Use teamwork and deduction to solve the mystery of the Big Apple in this satellite-exclusive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-kodomo-chousadan-mighty-pockets-chousa-3---kyakusen-queen-patra-no-nazo-japan', 'SNES', 'BS Kodomo Chousadan Mighty Pockets Chousa 3 - Kyakusen Queen Patra no Nazo (Japan)', '1996', 'Adventure', 'Nintendo', '1', 'Episodic mystery adventure', 'Isometric adventure game featuring a group of young detectives.', 'Uncover the secrets hidden aboard the luxury cruise ship Queen Patra.', 'Mystery on the high seas in BS Kodomo Chousadan Mighty Pockets 3.', 'The third episode of the series. Explore the ship, interview passengers, and solve complex puzzles to reveal the truth behind the Queen Patra''s mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-koi-wa-balance---tatoeba-k-kun-no-tabou-na-ichijitsu-hen-japan', 'SNES', 'BS Koi wa Balance - Tatoeba K-kun no Tabou na Ichijitsu Hen (Japan)', '1996', 'Adventure', 'Nintendo', '1', 'Romantic slice-of-life story', 'Quirky life simulation and dating hybrid with a focus on time management.', 'Balance K-kun''s daily schedule while maintaining his romantic relationships.', 'Manage romance and life in BS Koi wa Balance for Satellaview.', 'A unique "social" game where choices matter. Help the protagonist navigate a busy day of appointments and dates in this text-heavy 16-bit Japanese simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-konae-chan-no-dokidoki-pengin-kazoku-japan', 'SNES', 'BS Konae-chan no Dokidoki Pengin Kazoku (Japan)', '1996', 'Adventure', 'Nintendo', '1', 'Children’s comedy adventure', 'Action-puzzle game featuring a family of penguins.', 'Help the penguin family navigate through icy levels while avoiding predators.', 'Enjoy family fun with BS Konae-chan no Dokidoki Pengin Kazoku.', 'A colorful and lighthearted title. Use the penguins'' unique abilities to solve environmental puzzles and reach safety in this charming 16-bit satellite adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-koubo-kenshou-magazine-japan', 'SNES', 'BS Koubo Kenshou Magazine (Japan)', '1996', 'Variety', 'Nintendo', '1', 'Design contest program', 'Interactive digital magazine featuring contests and reader-submitted content.', 'Read the latest news and participate in digital prize draws.', 'Stay updated with the BS Koubo Kenshou Magazine for SNES.', 'A fascinating digital publication delivered via satellite. It allowed Japanese players to interact with the magazine staff and enter competitions directly from their consoles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-lets-pachinko-nante-gindama-1-japan', 'SNES', 'BS Let''s Pachinko Nante Gindama 1 (Japan)', '1996', 'Gambling', 'Nintendo', '1', 'Pachinko simulation', 'Pachinko simulation with realistic ball physics and machine mechanics.', 'Accumulate the highest number of silver balls through luck and skill.', 'Experience Japanese Pachinko in BS Let''s Pachinko Nante Gindama.', 'The first installment of the satellite Pachinko series. Features authentic machine designs and the addictive gambling gameplay popular in Japanese arcades.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-lets-pachinko-nante-gindama-2-japan', 'SNES', 'BS Let''s Pachinko Nante Gindama 2 (Japan)', '1996', 'Gambling', 'Nintendo', '1', 'Pachinko simulation', 'Pachinko simulation with realistic ball physics and machine mechanics.', 'Accumulate the highest number of silver balls through luck and skill.', 'Experience Japanese Pachinko in BS Let''s Pachinko Nante Gindama 2.', 'The second volume of the Pachinko series, offering new machine layouts and updated bonus features for digital gambling enthusiasts on the Super Famicom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-lets-pachinko-nante-gindama-3-japan', 'SNES', 'BS Let''s Pachinko Nante Gindama 3 (Japan)', '1996', 'Gambling', 'Nintendo', '1', 'Pachinko simulation', 'Pachinko simulation with realistic ball physics and machine mechanics.', 'Accumulate the highest number of silver balls through luck and skill.', 'Experience Japanese Pachinko in BS Let''s Pachinko Nante Gindama 3.', 'Volume three of the series. Refine your ball-launching technique and trigger special animations to win big in this 16-bit Pachinko simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-lets-pachinko-nante-gindama-4-japan', 'SNES', 'BS Let''s Pachinko Nante Gindama 4 (Japan)', '1996', 'Gambling', 'Nintendo', '1', 'Pachinko simulation', 'Pachinko simulation with realistic ball physics and machine mechanics.', 'Accumulate the highest number of silver balls through luck and skill.', 'Experience Japanese Pachinko in BS Let''s Pachinko Nante Gindama 4.', 'The final entry in the satellite Pachinko collection. Features the most advanced machine logic and bonus rounds in the series for the Satellaview system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-lord-monarch-japan', 'SNES', 'BS Lord Monarch (Japan)', '1996', 'Strategy', 'Nintendo', '1', 'Real-time strategy', 'Strategic board-game RPG hybrid focused on kingdom expansion and combat.', 'Conquer the entire map by managing your troops and defeating rival lords.', 'Master 16-bit strategy in the satellite version of BS Lord Monarch.', 'A fast-paced real-time strategy game. Manage resources, build paths, and send your armies to dominate the continent in this deep Falcom-developed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-marvelous-camp-arnold-course---dai-1-shuu-japan', 'SNES', 'BS Marvelous Camp Arnold Course - Dai-1-shuu (Japan)', '1996', 'Action Adventure', 'Nintendo', '1', 'Action adventure course', 'Action-adventure with puzzle elements, serving as a spin-off to Marvelous.', 'Complete the first week of training at Camp Arnold''s outdoor course.', 'Join the adventure in BS Marvelous Camp Arnold Course - Week 1.', 'A satellite-exclusive expansion of "Marvelous: Mouhitotsu no Takarajima." Lead your trio of characters through team-based puzzles and outdoor challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-marvelous-camp-arnold-course---dai-2-shuu-japan', 'SNES', 'BS Marvelous Camp Arnold Course - Dai-2-shuu (Japan)', '1996', 'Action Adventure', 'Nintendo', '1', 'Action adventure course', 'Action-adventure with puzzle elements, serving as a spin-off to Marvelous.', 'Complete the second week of training and solve new campsite mysteries.', 'Join the adventure in BS Marvelous Camp Arnold Course - Week 2.', 'The story continues with more complex puzzles. Use the unique abilities of Dion, Max, and Jack to navigate the forest and complete Arnold''s tasks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-marvelous-camp-arnold-course---dai-3-shuu-japan', 'SNES', 'BS Marvelous Camp Arnold Course - Dai-3-shuu (Japan)', '1996', 'Action Adventure', 'Nintendo', '1', 'Action adventure course', 'Action-adventure with puzzle elements, serving as a spin-off to Marvelous.', 'Overcome the third week''s challenges and discover hidden treasures.', 'Join the adventure in BS Marvelous Camp Arnold Course - Week 3.', 'Week three increases the difficulty with elaborate environmental riddles. Master the character-switching mechanic to progress through the campsite''s secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-marvelous-camp-arnold-course---dai-4-shuu-japan', 'SNES', 'BS Marvelous Camp Arnold Course - Dai-4-shuu (Japan)', '1996', 'Action Adventure', 'Nintendo', '1', 'Action adventure course', 'Action-adventure with puzzle elements, serving as a spin-off to Marvelous.', 'Finish the final week of Camp Arnold and graduate from the course.', 'The grand finale of BS Marvelous Camp Arnold Course - Week 4.', 'The concluding chapter of the Camp Arnold saga. Solve the final set of puzzles and complete your 16-bit outdoor training in this rare expansion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-marvelous-time-athletic-course---dai-1-shuu-japan', 'SNES', 'BS Marvelous Time Athletic Course - Dai-1-shuu (Japan)', '1996', 'Action Adventure', 'Nintendo', '1', 'Athletic action course', 'Isometric action-adventure focused on speed and obstacle navigation.', 'Clear the first athletic course within the strict time limit.', 'Test your reflexes in BS Marvelous Time Athletic Course - Week 1.', 'A standalone challenge series based on the Marvelous engine. Focuses on pure agility and quick puzzle-solving across a series of treacherous 16-bit courses.');
