INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-marvelous-time-athletic-course---dai-3-shuu-japan', 'SNES', 'BS Marvelous Time Athletic Course - Dai-3-shuu (Japan)', '1996', 'Action Adventure', 'Nintendo', '1', 'Athletic action course', 'Isometric action-adventure focused on speed and obstacle navigation.', 'Clear the third athletic course within the strict time limit.', 'Test your reflexes in BS Marvelous Time Athletic Course - Week 3.', 'A high-stakes obstacle course that tests your mastery of the game''s movement mechanics. Avoid traps and solve quick puzzles under pressure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-marvelous-time-athletic-course---dai-4-shuu-japan', 'SNES', 'BS Marvelous Time Athletic Course - Dai-4-shuu (Japan)', '1996', 'Action Adventure', 'Nintendo', '1', 'Athletic action course', 'Isometric action-adventure focused on speed and obstacle navigation.', 'Complete the final athletic course and achieve the best time record.', 'The ultimate challenge in BS Marvelous Time Athletic Course - Week 4.', 'The final and most difficult week of the athletic series. Only the fastest players can navigate this complex 16-bit labyrinth before time runs out.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-nichibutsu-mahjong---renshuu-mahjong---ichimantou-japan', 'SNES', 'BS Nichibutsu Mahjong - Renshuu Mahjong - Ichimantou (Japan)', '1996', 'Gambling', 'Nichibutsu', '1', 'Mahjong training', 'Mahjong simulation with a focus on practice and technical mastery.', 'Win Mahjong matches to earn the Ichimantou rank and improve your skills.', 'Master Mahjong strategy in BS Nichibutsu Mahjong: Renshuu Mahjong.', 'A focused Mahjong title designed for players to practice their hands. Features a clean interface and competitive AI to help you master the traditional Japanese game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-nichibutsu-mahjong---renshuu-mahjong---nimantou-japan', 'SNES', 'BS Nichibutsu Mahjong - Renshuu Mahjong - Nimantou (Japan)', '1996', 'Gambling', 'Nichibutsu', '1', 'Mahjong training', 'Mahjong simulation with a focus on practice and technical mastery.', 'Win Mahjong matches to earn the Nimantou rank and improve your skills.', 'Master Mahjong strategy in BS Nichibutsu Mahjong: Renshuu Mahjong.', 'The second level of the Mahjong practice series. Offers tougher opponents and more complex scenarios to test your 16-bit gambling and strategy skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-nichibutsu-mahjong-japan', 'SNES', 'BS Nichibutsu Mahjong (Japan)', '1996', 'Gambling', 'Nichibutsu', '1', 'Mahjong simulation', 'Traditional Mahjong simulation with professional rules and tournament play.', 'Win matches against skilled AI opponents to climb the Mahjong rankings.', 'Play professional Mahjong in BS Nichibutsu Mahjong for the Satellaview.', 'A high-quality Mahjong experience featuring detailed 16-bit graphics and a variety of modes. Master the tiles and outsmart your rivals in this satellite-exclusive gambling sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-nintama-rantarou-2-japan', 'SNES', 'BS Nintama Rantarou 2 (Japan)', '1996', 'Adventure', 'Nintendo', '1', 'Anime adventure', 'Action-platformer based on the popular anime featuring young ninjas.', 'Navigate through obstacle-filled levels to complete ninja training.', 'Join the ninja apprentices in BS Nintama Rantarou 2 for the SNES.', 'Control Rantarou and his friends in this charming 16-bit platformer. Use unique ninja tools and agility to overcome traps and enemies in this satellite broadcast version.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-nintendo-hp---5-17-gou-japan', 'SNES', 'BS Nintendo HP - 5-17 Gou (Japan)', '1996', 'Variety', 'Nintendo', '1', 'Official website magazine', 'Digital "Home Page" magazine featuring official Nintendo news and tips.', 'Explore the latest 16-bit game updates and official announcements.', 'Check out the BS Nintendo HP digital magazine for Satellaview.', 'An interactive portal that served as Nintendo''s official satellite news channel. Players could browse through game previews, secret codes, and company news directly on their TV.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-nintendo-hp---5-31-gou-japan', 'SNES', 'BS Nintendo HP - 5-31 Gou (Japan)', '1996', 'Variety', 'Nintendo', '1', 'Official website magazine', 'Digital "Home Page" magazine featuring official Nintendo news and tips.', 'Explore the latest 16-bit game updates and official announcements.', 'Check out the BS Nintendo HP digital magazine for Satellaview.', 'The late-May edition of Nintendo''s satellite newsletter. Discover historical insights into upcoming Super Famicom releases and official developer interviews from the 90s.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-nintendo-power-magazine-107-japan', 'SNES', 'BS Nintendo Power Magazine 107 (Japan)', '1996', 'Magazine', 'Nintendo', '1', 'Gaming magazine', 'Digital lifestyle and gaming magazine delivered via satellite.', 'Read reviews, tips, and articles from the Nintendo Power 107 broadcast.', 'Explore the BS Nintendo Power Magazine 107 on the Satellaview.', 'A Japanese-exclusive digital magazine. It provided in-depth coverage of the SNES ecosystem, including walkthroughs and high-score rankings for the satellite community.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-panel-de-pon---event-98-japan', 'SNES', 'BS Panel de Pon - Event ''98 (Japan)', '1998', 'Puzzle', 'Nintendo', '2', 'Event puzzle competition', 'Competitive match-three puzzle game with a fantasy theme.', 'Defeat opponents by clearing blocks and triggering chain reactions.', 'Experience the rare BS Panel de Pon Event ''98 on the SNES.', 'A special tournament edition of the game known in the West as Tetris Attack. Features exclusive puzzles and competitive modes used during the 1998 satellite event.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-parlor!-parlor!---dai-2-shuu-japan', 'SNES', 'BS Parlor! Parlor! - Dai-2-shuu (Japan)', '1996', 'Gambling', 'Nintendo', '1', 'Pachinko simulation', 'Pachinko and slot simulation featuring authentic machine mechanics.', 'Win the most digital credits by mastering the satellite slot machines.', 'Test your luck in BS Parlor! Parlor! for the Satellaview.', 'Volume two of the popular gambling simulation. Experience realistic 16-bit renditions of Japanese parlor machines with exclusive broadcast-only bonus features.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-pokekame-magazine-japan', 'SNES', 'BS Pokekame Magazine (Japan)', '1996', 'Magazine', 'Nintendo', '1', 'Character magazine', 'Photography-themed digital magazine or interactive hobbyist content.', 'Learn photography tips and explore galleries of 16-bit images.', 'Discover the world of photography in BS Pokekame Magazine for SNES.', 'A unique Satellaview broadcast dedicated to the "Pocket Camera" and general photography. It featured community galleries and interactive tutorials for creative players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-radical-dreamers-japan', 'SNES', 'BS Radical Dreamers (Japan)', '1996', 'Adventure', 'Square', '1', 'Narrative text adventure', 'Text-based visual novel adventure set in the Chrono Trigger universe.', 'Infiltrate Viper Manor to steal the legendary Frozen Flame.', 'Play the legendary Chrono Trigger sequel, Radical Dreamers, on SNES.', 'A atmospheric text-adventure where your choices determine the fate of Serge, Kid, and Magil. This 16-bit classic bridges the gap between Chrono Trigger and Chrono Cross.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-satella-walker-2---sate-bou-o-sukuidase!-japan', 'SNES', 'BS Satella Walker 2 - Sate Bou o Sukuidase! (Japan)', '1996', 'Adventure', 'Nintendo', '1', 'Action news challenge', 'Adventure and mini-game hybrid featuring the Satellaview mascot.', 'Help Sate Bou on his quest to save the satellite world.', 'Join the mascot adventure in BS Satella Walker 2 for the SNES.', 'A quirky and colorful adventure featuring the faces of the Satellaview service. Explore vibrant environments and complete mini-games to progress through the story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-shanghai---banri-no-choujou-japan', 'SNES', 'BS Shanghai - Banri no Choujou (Japan)', '1996', 'Puzzle', 'Sunsoft', '1', 'Classic tile puzzle', 'Classic tile-matching puzzle game with a Chinese architecture theme.', 'Clear all Mahjong tiles from the board by finding matching pairs.', 'Master the Great Wall in BS Shanghai: Banri no Choujou on SNES.', 'A polished 16-bit version of the classic puzzle game. Features beautiful backdrops and challenging tile layouts that require sharp observation and strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-shin-onigashima---dai-1-wa---kataribe-no-koya-japan', 'SNES', 'BS Shin Onigashima - Dai-1-wa - Kataribe no Koya (Japan)', '1996', 'Adventure', 'Nintendo', '1', 'Episodic folklore adventure', 'Japanese-style visual novel based on traditional folklore and myths.', 'Follow the narrative path of the storyteller to uncover ancient mysteries.', 'Experience the mythic BS Shin Onigashima on the Satellaview.', 'A remake of the Famicom classic. This first chapter introduces the world and characters in a beautifully illustrated 16-bit adventure inspired by Japanese legends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-shin-onigashima---dai-2-wa---kataribe-no-koya-japan', 'SNES', 'BS Shin Onigashima - Dai-2-wa - Kataribe no Koya (Japan)', '1996', 'Adventure', 'Nintendo', '1', 'Episodic folklore adventure', 'Japanese-style visual novel based on traditional folklore and myths.', 'Continue the mythic journey and solve environmental puzzles to progress.', 'Experience the mythic BS Shin Onigashima on the Satellaview.', 'The second chapter of the saga. Deepen your understanding of the folklore-driven plot through interactive dialogue and point-and-click exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-shin-onigashima---dai-3-wa---kataribe-no-koya-japan', 'SNES', 'BS Shin Onigashima - Dai-3-wa - Kataribe no Koya (Japan)', '1996', 'Adventure', 'Nintendo', '1', 'Episodic folklore adventure', 'Japanese-style visual novel based on traditional folklore and myths.', 'Uncover the secrets of the storyteller''s hut and the dark spirits.', 'Experience the mythic BS Shin Onigashima on the Satellaview.', 'Part three of the episodic adventure. Features improved 16-bit graphics and a hauntingly beautiful soundtrack that brings Japanese myths to life.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-shin-onigashima---dai-4-wa---kataribe-no-koya-japan', 'SNES', 'BS Shin Onigashima - Dai-4-wa - Kataribe no Koya (Japan)', '1996', 'Adventure', 'Nintendo', '1', 'Episodic folklore adventure', 'Japanese-style visual novel based on traditional folklore and myths.', 'Reach the climax of the story and defeat the demonic forces.', 'The grand finale of BS Shin Onigashima on the Satellaview.', 'The concluding chapter of the "Kataribe no Koya" arc. Witness the dramatic resolution of the story in this high-quality 16-bit visual novel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-sousa-sentai-wappers---mission-1---sousa-sentai-wappers-kenzan-japan', 'SNES', 'BS Sousa Sentai Wappers - Mission 1 - Sousa Sentai Wappers Kenzan (Japan)', '1996', 'Action', 'Nintendo', '1', 'Heroic action episode', 'Top-down action-strategy game featuring a specialized investigation team.', 'Complete the first mission by infiltrating and clearing the enemy zone.', 'Join the elite squad in BS Sousa Sentai Wappers for the SNES.', 'A unique satellite title where you lead a team of investigators. Use specialized equipment and tactical movement to solve cases and defeat criminals in the first mission.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-sousa-sentai-wappers---mission-2---kikiippatsu-kou-wapper-no-maki-japan', 'SNES', 'BS Sousa Sentai Wappers - Mission 2 - Kikiippatsu Kou Wapper no Maki (Japan)', '1996', 'Action', 'Nintendo', '1', 'Heroic action episode', 'Top-down action-strategy game featuring a specialized investigation team.', 'Stop the criminal syndicate before their plan reaches its final stage.', 'Join the elite squad in BS Sousa Sentai Wappers Mission 2 for SNES.', 'The second mission ups the ante with more complex levels and tougher enemy encounters. Coordinate your team''s abilities to survive this 16-bit tactical challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-sousa-sentai-wappers---soushuu-hen-japan', 'SNES', 'BS Sousa Sentai Wappers - Soushuu Hen (Japan)', '1996', 'Action', 'Nintendo', '1', 'Compilation episode', 'Top-down action-strategy game featuring a specialized investigation team.', 'Complete a series of high-stakes missions to restore peace.', 'Experience the full BS Sousa Sentai Wappers collection on SNES.', 'A compilation broadcast that allowed players to experience the best moments and missions from the Wappers series in one 16-bit package.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-special-tee-shot-japan', 'SNES', 'BS Special Tee Shot (Japan)', '1996', 'Sports', 'Nintendo', '1', 'Golf mini-game', 'Isometric puzzle-golf game with a focus on physics and obstacles.', 'Get the ball into the hole using the fewest strokes possible.', 'Play the prototype of Kirby''s Dream Course: BS Special Tee Shot.', 'Before it was a Kirby game, it was Tee Shot. Navigate surreal isometric courses filled with traps and moving platforms in this clever 16-bit physics puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-spriggan-powered---bs-version-japan', 'SNES', 'BS Spriggan Powered - BS Version (Japan)', '1996', 'Shoot ''em up', 'Naxat Soft', '1', 'Enhanced sci-fi shooter', 'Side-scrolling shoot ''em up with a focus on elemental weapon systems.', 'Destroy the alien fleet and protect the planet from destruction.', 'Unleash elemental power in BS Spriggan Powered for the SNES.', 'A high-octane SHMUP featuring massive sprites and intense action. This special BS version includes exclusive scoring modes and rearranged level structures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-st-giga-pg---10-gatsugou-japan', 'SNES', 'BS St. Giga PG - 10 Gatsugou (Japan)', '1996', 'Magazine', 'St.GIGA', '1', 'Broadcast program guide', 'Digital scheduling and programming guide for the St. Giga satellite service.', 'Check the broadcast schedule and upcoming game releases for October.', 'Explore the BS St. Giga October programming guide on SNES.', 'A piece of gaming history, this interactive guide allowed players to see when their favorite Soundlink and data games would be broadcasted via satellite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-super-earth-defense-force-japan', 'SNES', 'BS Super Earth Defense Force (Japan)', '1996', 'Shoot ''em up', 'Jaleco', '1', 'Arcade sci-fi shooter', 'Side-scrolling shoot ''em up with a futuristic military theme.', 'Navigate through space and enemy bases to destroy the core.', 'Experience the intense action of BS Super Earth Defense Force.', 'The satellite version of the classic "S.E.D.F." Use a variety of upgradeable weapons and master tight patterns to survive waves of 16-bit mechanical enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-super-famicom-wars---bs-ban-japan', 'SNES', 'BS Super Famicom Wars - BS Ban (Japan)', '1996', 'Strategy', 'Intelligent Systems', '2', 'Turn-based war strategy', 'Turn-based strategy game featuring military units and territory control.', 'Outmaneuver the enemy army and capture their headquarters.', 'Master the rare BS Super Famicom Wars on the Satellaview.', 'A specialized version of the classic Nintendo strategy series. Features exclusive maps and scenarios that were only playable during the Japanese satellite broadcasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-super-mahjong-taikai-japan', 'SNES', 'BS Super Mahjong Taikai (Japan)', '1996', 'Gambling', 'Nintendo', '1', 'Mahjong tournament', 'Mahjong tournament simulation featuring a grand tournament structure.', 'Win the national Mahjong tournament and become the grand champion.', 'Enter the high-stakes world of BS Super Mahjong Taikai on SNES.', 'A deep simulation of the Japanese game. Features a competitive AI and a progression system that rewards skillful play and strategic tile management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-super-ninja-kun-japan', 'SNES', 'BS Super Ninja-kun (Japan)', '1996', 'Action Platformer', 'Jaleco', '1', 'Cute ninja action', 'Side-scrolling action platformer featuring a fast and agile ninja.', 'Defeat the rival ninja clans and save the village from an ancient evil.', 'Enjoy high-speed ninja action in BS Super Ninja-kun for the SNES.', 'Control the cute but deadly Ninja-kun. Use speed, jumping skills, and shurikens to clear vibrant levels and defeat massive 16-bit bosses in this satellite version.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-super-tsume-shougi-1000-japan', 'SNES', 'BS Super Tsume Shougi 1000 (Japan)', '1996', 'Board Game', 'Nintendo', '1', 'Shogi puzzle challenge', 'Logic-based puzzle game focused on Shogi end-game scenarios.', 'Solve 1000 different Shogi puzzles by finding the checkmate move.', 'Master Japanese chess in BS Super Tsume Shougi 1000 for SNES.', 'A massive collection of "Tsume" (checkmate) puzzles. This satellite broadcast tested players'' knowledge of Shogi strategy across a huge variety of challenging scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-super-volley-ii-japan', 'SNES', 'BS Super Volley II (Japan)', '1996', 'Sports', 'Nintendo', '2', 'Arcade volleyball', 'Arcade-style volleyball simulation with fast-paced 16-bit action.', 'Win the national volleyball tournament by outscoring rival teams.', 'Experience competitive volleyball in BS Super Volley II for SNES.', 'A streamlined satellite version of the popular sports title. Features smooth animations and responsive controls, allowing players to execute spikes and blocks in intense 16-bit matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-sutte-hakkun---98-event-version-japan', 'SNES', 'BS Sutte Hakkun - ''98 Event Version (Japan)', '1998', 'Puzzle', 'Nintendo', '1', 'Event puzzle edition', 'Innovative action-puzzle game where you suck and inject colors to change objects.', 'Solve environmental puzzles to reach the goal in this special event version.', 'Master the unique puzzles of BS Sutte Hakkun on Satellaview.', 'A cult classic puzzle game. Use Hakkun to move colors between objects, altering their physics (gravity, movement) to navigate through creative and challenging 16-bit levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-sutte-hakkun---bs-version-2-10-8-japan', 'SNES', 'BS Sutte Hakkun - BS Version 2 10-8 (Japan)', '1996', 'Puzzle', 'Nintendo', '1', 'Experimental puzzle', 'Innovative action-puzzle game where you suck and inject colors to change objects.', 'Complete the specific puzzle sets featured in the October broadcast.', 'Solve the October puzzles in BS Sutte Hakkun Version 2 for SNES.', 'This satellite broadcast offered exclusive levels not found in the retail version, testing players'' logic with new color-based mechanics and platforming challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-sutte-hakkun---bs-version-2-6-3-japan', 'SNES', 'BS Sutte Hakkun - BS Version 2 6-3 (Japan)', '1996', 'Puzzle', 'Nintendo', '1', 'Experimental puzzle', 'Innovative action-puzzle game where you suck and inject colors to change objects.', 'Complete the specific puzzle sets featured in the June broadcast.', 'Solve the June puzzles in BS Sutte Hakkun Version 2 for SNES.', 'Part of the episodic puzzle series. Use Hakkun''s unique abilities to manipulate the environment and find the most efficient path to the end of each stage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-sutte-hakkun---event-version-japan', 'SNES', 'BS Sutte Hakkun - Event Version (Japan)', '1996', 'Puzzle', 'Nintendo', '1', 'Event puzzle edition', 'Innovative action-puzzle game where you suck and inject colors to change objects.', 'Compete in special timed puzzle challenges during the satellite event.', 'Test your puzzle skills in the BS Sutte Hakkun Event Version.', 'A rare version of the game used for official Satellaview competitions. Players had to solve complex puzzles under time pressure to achieve high scores and rankings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-tantei-club---yuki-ni-kieta-kako---chuuhen-japan', 'SNES', 'BS Tantei Club - Yuki ni Kieta Kako - Chuuhen (Japan)', '1996', 'Adventure', 'Nintendo', '1', 'Episodic mystery adventure', 'Detective-themed visual novel adventure with a focus on investigation.', 'Solve the middle chapter of the mystery "The Past that Vanished in the Snow."', 'Uncover the truth in BS Tantei Club: Yuki ni Kieta Kako.', 'Part of the Famicom Tantei Club series. This 16-bit remake for Satellaview features beautiful art and a gripping narrative as you investigate a cold case in a snowy village.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-tantei-club---yuki-ni-kieta-kako---kouhen-japan', 'SNES', 'BS Tantei Club - Yuki ni Kieta Kako - Kouhen (Japan)', '1996', 'Adventure', 'Nintendo', '1', 'Episodic mystery adventure', 'Detective-themed visual novel adventure with a focus on investigation.', 'Reach the dramatic conclusion of the "Past that Vanished in the Snow" mystery.', 'The grand finale of BS Tantei Club: Yuki ni Kieta Kako on SNES.', 'The concluding chapter of the episodic detective story. Use your deduction skills to identify the culprit and solve the dark secrets of the village in this high-quality visual novel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-tantei-club---yuki-ni-kieta-kako---zenhen-japan', 'SNES', 'BS Tantei Club - Yuki ni Kieta Kako - Zenhen (Japan)', '1996', 'Adventure', 'Nintendo', '1', 'Episodic mystery adventure', 'Detective-themed visual novel adventure with a focus on investigation.', 'Investigate the initial clues of the mystery "The Past that Vanished in the Snow."', 'Start the investigation in BS Tantei Club: Yuki ni Kieta Kako.', 'The opening act of the satellite-exclusive mystery. Interview witnesses and search for clues in a beautifully atmospheric 16-bit rendition of a classic Japanese adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-treasure-conflix-japan', 'SNES', 'BS Treasure Conflix (Japan)', '1996', 'Puzzle', 'Nintendo', '2', 'Competitive puzzle action', 'Sci-fi strategy and exploration game with a focus on mercenary combat.', 'Navigate the galaxy to find treasures while surviving ship-to-ship battles.', 'Explore the stars in the rare BS Treasure Conflix on Satellaview.', 'A unique Square-developed title. It blends top-down navigation with Mode 7 combat sequences, offering a deep 16-bit sci-fi experience with RPG and strategy elements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-waiwai-check-3-7-japan', 'SNES', 'BS Waiwai Check 3-7 (Japan)', '1996', 'Variety', 'Nintendo', '1', 'Entertainment variety show', 'Interactive digital magazine or variety show broadcasted for Satellaview.', 'Explore the news, mini-games, and community content for early March.', 'Check out the quirky BS Waiwai Check on the Satellaview.', 'A variety-style program that featured interactive polls, news segments, and small digital activities for the Japanese Super Famicom satellite audience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-wario-no-mori---futatabi-japan', 'SNES', 'BS Wario no Mori - Futatabi (Japan)', '1996', 'Puzzle', 'Nintendo', '2', 'Updated puzzle classic', 'Action-puzzle game based on the Wario''s Woods engine.', 'Clear the forest of monsters by matching colors and using Wario''s moves.', 'Enjoy the satellite-exclusive BS Wario no Mori: Futatabi.', 'A refined version of the classic puzzle game. Take control of Toad and arrange falling monsters and bombs to clear the grid in this addictive 16-bit competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-wizardry-v---saika-no-chuushin-japan', 'SNES', 'BS Wizardry V - Saika no Chuushin (Japan)', '1996', 'RPG', 'Sir-Tech', '1', 'Dungeon crawler RPG', 'First-person dungeon crawler RPG with a deep turn-based combat system.', 'Navigate the dangerous depths of the labyrinth to find ancient artifacts.', 'Experience the 16-bit classic BS Wizardry V on the Satellaview.', 'A satellite-exclusive version of the legendary RPG. Manage your party, map out treacherous corridors, and engage in tactical combat against deadly fantasy creatures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-yoshi-no-panepon---bs-ban-japan-enja', 'SNES', 'BS Yoshi no Panepon - BS Ban (Japan) (En,Ja)', '1996', 'Puzzle', 'Nintendo', '2', 'Competitive puzzle', 'Competitive match-three puzzle game featuring Yoshi and friends.', 'Defeat opponents by clearing blocks and creating massive chain reactions.', 'Play the rare BS Yoshi no Panepon on the Satellaview.', 'The satellite version of the puzzle classic (Tetris Attack). Features exclusive levels and characters, offering the same addictive gameplay with unique broadcast-only content.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-yung-hakase-no-shinsatsu-shitsu---dai-1-gou-japan', 'SNES', 'BS Yung Hakase no Shinsatsu Shitsu - Dai-1-gou (Japan)', '1996', 'Educational', 'Nintendo', '1', 'Medical education program', 'Interactive psychological quiz or educational simulation.', 'Participate in Dr. Yung''s diagnosis and learn about mental health.', 'Explore the mind in BS Yung Hakase no Shinsatsu Shitsu for SNES.', 'A bizarre and educational "medical" title. Players interact with Dr. Yung through quizzes and scenarios to receive a psychological "diagnosis" in a 16-bit format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-yung-hakase-no-shinsatsu-shitsu---dai-2-gou-japan', 'SNES', 'BS Yung Hakase no Shinsatsu Shitsu - Dai-2-gou (Japan)', '1996', 'Educational', 'Nintendo', '1', 'Medical education program', 'Interactive psychological quiz or educational simulation.', 'Complete the second round of psychological tests and scenarios.', 'Explore the mind in BS Yung Hakase no Shinsatsu Shitsu 2 for SNES.', 'The follow-up to the first medical broadcast. Features new questions, oddball humor, and deeper psychological profiles for the satellite audience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-zootto-mahjong---event-version-japan', 'SNES', 'BS Zootto Mahjong - Event Version (Japan)', '1998', 'Gambling', 'Nintendo', '1', 'Mahjong event version', 'Competitive Mahjong event with a focus on high-score rankings.', 'Win matches against AI or players to climb the official event leaderboards.', 'Play the competitive BS Zootto Mahjong Event Version.', 'A special tournament-focused version of the Mahjong sim. Players competed durante a live broadcast window to prove their mastery and win digital prizes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bs-zootto-mahjong---preview-ban-japan', 'SNES', 'BS Zootto Mahjong - Preview Ban (Japan)', '1998', 'Gambling', 'Nintendo', '1', 'Mahjong preview version', 'Mahjong simulation preview featuring core gameplay mechanics.', 'Test the Mahjong systems and experience a sample of the full broadcast.', 'Check out the BS Zootto Mahjong Preview Ban on SNES.', 'A demo version released via satellite to generate interest. It features the basic rules and a few practice matches to get players ready for the full event.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubsy-ii', 'SNES', 'Bubsy II', '1994', 'Platformer', 'Accolade', '1', 'Cartoon platformer', 'Side-scrolling platformer featuring a fast-moving bobcat with a lot of attitude.', 'Navigate through various themed worlds to defeat the evil Otho.', 'Join the wacky adventure in Bubsy II for the Super Nintendo.', 'Bubsy returns with new gadgets, like a portable hole and a diving suit. Explore levels based on history and music in this fast-paced 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubsy-in-claws-encounters-of-the-furred-kind', 'SNES', 'Bubsy in Claws Encounters of the Furred Kind', '1993', 'Platformer', 'Accolade', '1', 'Cartoon platformer', 'Side-scrolling platformer featuring a fast-moving bobcat with a lot of attitude.', 'Protect the world''s wool supply from the alien "Woolies."', 'Experience the original Bubsy in Claws Encounters of the Furred Kind.', 'Known for its massive levels and high speed. Use Bubsy''s glide ability to explore sprawling stages, collect yarn balls, and avoid hazards in this 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bugs-life-a-world-pirate', 'SNES', 'Bug''s Life, A (World) (Pirate)', '1999', 'Platformer', 'Unknown', '1', 'Pirate movie platformer', 'Side-scrolling action platformer based on the Pixar movie (bootleg version).', 'Lead Flik through various levels to save the ant colony.', 'Play the rare pirate version of A Bug''s Life on the SNES.', 'An unofficial 16-bit port of the popular movie. Despite being a pirate original, it features unique sprite work and platforming levels that attempt to recreate Flik''s journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bugs-bunny---hachamecha-daibouken-japan', 'SNES', 'Bugs Bunny - Hachamecha Daibouken (Japan)', '1994', 'Platformer', 'Konami', '1', 'Looney Tunes platformer', 'Action platformer featuring the famous Looney Tunes rabbit.', 'Navigate through various movie-set themed worlds to reach the end.', 'Join the wacky fun in Bugs Bunny: Hachamecha Daibouken for SNES.', 'A colorful Japanese-exclusive platformer where Bugs must outsmart familiar foes. Use his agility and classic cartoon antics to clear stages filled with humor and 16-bit charm.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bugs-bunny-in-rabbit-rampage-europe', 'SNES', 'Bugs Bunny in Rabbit Rampage (Europe)', '1994', 'Platformer', 'Viacom New Media', '1', 'Cartoon platformer', 'Innovative action platformer where the environment changes based on the story.', 'Escape the animator''s traps and confront the pencil that creates the world.', 'Help Bugs Bunny escape the animator in Rabbit Rampage for SNES.', 'A visually impressive game where the animator''s pencil acts as both an ally and an enemy. Experience varied gameplay styles across levels inspired by classic Looney Tunes shorts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bugs-bunny-in-rabbit-rampage-usa', 'SNES', 'Bugs Bunny in Rabbit Rampage (USA)', '1994', 'Platformer', 'Viacom New Media', '1', 'Cartoon platformer', 'Innovative action platformer where the environment changes based on the story.', 'Escape the animator''s traps and confront the pencil that creates the world.', 'Help Bugs Bunny escape the animator in Rabbit Rampage for SNES.', 'A visually impressive game where the animator''s pencil acts as both an ally and an enemy. Experience varied gameplay styles across levels inspired by classic Looney Tunes shorts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bulls-vs-blazers-and-the-nba-playoffs-europe', 'SNES', 'Bulls vs Blazers and the NBA Playoffs (Europe)', '1992', 'Sports', 'Electronic Arts', '2', 'Arcade basketball', 'Classic basketball simulation featuring the 1992 NBA season.', 'Lead the Bulls, Blazers, or other NBA teams to the championship.', 'Experience 16-bit NBA action in Bulls vs Blazers on the SNES.', 'Featuring real players and signature moves, this EA Sports classic offers realistic (for the time) basketball gameplay, complete with the full NBA playoff structure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bulls-vs-blazers-and-the-nba-playoffs-europe-rev-a', 'SNES', 'Bulls vs Blazers and the NBA Playoffs (Europe) (Rev A)', '1992', 'Sports', 'Electronic Arts', '2', 'Arcade basketball', 'Classic basketball simulation featuring the 1992 NBA season.', 'Lead the Bulls, Blazers, or other NBA teams to the championship.', 'Experience 16-bit NBA action in Bulls vs Blazers on the SNES.', 'The revised European version, featuring minor gameplay balancing and bug fixes to provide a smoother basketball simulation for the Super Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bulls-vs-blazers-and-the-nba-playoffs-usa', 'SNES', 'Bulls vs Blazers and the NBA Playoffs (USA)', '1992', 'Sports', 'Electronic Arts', '2', 'Arcade basketball', 'Classic basketball simulation featuring the 1992 NBA season.', 'Lead the Bulls, Blazers, or other NBA teams to the championship.', 'Experience 16-bit NBA action in Bulls vs Blazers on the SNES.', 'Take command of superstars like Michael Jordan and Clyde Drexler. This title set the foundation for future NBA sims with its attention to team stats and authentic 90s atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bulls-vs-blazers-and-the-nba-playoffs-usa-rev-a', 'SNES', 'Bulls vs Blazers and the NBA Playoffs (USA) (Rev A)', '1992', 'Sports', 'Electronic Arts', '2', 'Arcade basketball', 'Classic basketball simulation featuring the 1992 NBA season.', 'Lead the Bulls, Blazers, or other NBA teams to the championship.', 'Experience 16-bit NBA action in Bulls vs Blazers on the SNES.', 'The Revised Edition (Rev A) for the USA market, fixing several statistical errors and improving player AI for a more competitive playoff experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('burai---hachigyoku-no-yuushi-densetsu-japan', 'SNES', 'Burai - Hachigyoku no Yuushi Densetsu (Japan)', '1993', 'RPG', 'Riverhillsoft', '1', 'Turn-based fantasy RPG', 'Traditional turn-based JRPG with a focus on eight distinct protagonists.', 'Unite the eight heroes of the legend to defeat the dark god.', 'Experience the epic Burai: Hachigyoku no Yuushi Densetsu on SNES.', 'A classic JRPG featuring detailed character portraits and a deep story. Manage your party''s equipment and magic across a vast 16-bit world inspired by Japanese mythology.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bushi-seiryuuden---futari-no-yuusha-japan', 'SNES', 'Bushi Seiryuuden - Futari no Yuusha (Japan)', '1993', 'RPG', 'Game Arts', '1', 'Story-driven RPG', 'Unique hybrid of turn-based RPG and side-scrolling action-puzzle.', 'Lead the warrior and his spirit companion to save the world.', 'Discover the Game Freak gem Bushi Seiryuuden for the SNES.', 'Developed by Game Freak, this title blends tactical movement with platforming. Every action counts as a turn, requiring strategic planning to defeat enemies and navigate levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bust-a-move-usa', 'SNES', 'Bust-A-Move (USA)', '1994', 'Puzzle', 'Taito', '2', 'Arcade puzzle action', 'Classic bubble-matching puzzle game featuring the characters from Bubble Bobble.', 'Clear the board of colorful bubbles by matching three or more.', 'Enjoy the addictive puzzle action of Bust-A-Move on the SNES.', 'Known as Puzzle Bobble in Japan, this title features cute dinosaurs Bub and Bob. Use the bubble launcher to create chain reactions and clear levels in this timeless 16-bit puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bust-a-move-usa-hack-by-dragon-eye-studios-v050-~bust-m-up', 'SNES', 'Bust-A-Move (USA) [Hack by Dragon Eye Studios v0.50] (~Bust-M-Up)', '1994', 'Puzzle', 'ROM Hack', '2', 'Modified arcade puzzle', 'Classic bubble-matching puzzle game with fan-made level modifications.', 'Clear the board using new and rearranged puzzle patterns.', 'Play the Bust-M-Up fan mod of Bust-A-Move on the SNES.', 'A technical hack that introduces new challenges and level layouts to the original game, providing a fresh experience for veteran fans of the 16-bit puzzle classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cacoma-knight-japan', 'SNES', 'Cacoma Knight (Japan)', '1992', 'Puzzle', 'Naxat Soft', '1', 'Action puzzle', 'Action-puzzle game where you draw lines to capture territory.', 'Reclaim the land of Bizyland by surrounding and defeating enemies.', 'Master the territory puzzles in Cacoma Knight for the SNES.', 'Known as Qix-style gameplay. Move your cursor to draw shapes and capture percentages of the screen while avoiding enemies in this colorful 16-bit Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cacoma-knight-in-bizyland-usa', 'SNES', 'Cacoma Knight in Bizyland (USA)', '1992', 'Puzzle', 'Naxat Soft', '1', 'Action puzzle', 'Action-puzzle game where you draw lines to capture territory.', 'Reclaim the land of Bizyland by surrounding and defeating enemies.', 'Master the territory puzzles in Cacoma Knight for the SNES.', 'The Western release of the Qix-inspired puzzle game. Features diverse themes and boss battles that require quick reflexes and spatial strategy to clear each stage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cal-ripken-jr-baseball-europe', 'SNES', 'Cal Ripken Jr. Baseball (Europe)', '1992', 'Sports', 'Equilibrium', '2', 'Baseball simulation', 'Realistic baseball simulation featuring the legendary Cal Ripken Jr.', 'Win the world series by outplaying professional baseball teams.', 'Play ball with Cal Ripken Jr. Baseball for the Super Nintendo.', 'A detailed sports sim with multiple camera angles and roster management. Master pitching, hitting, and fielding to lead your team to the 16-bit championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cal-ripken-jr-baseball-usa', 'SNES', 'Cal Ripken Jr. Baseball (USA)', '1992', 'Sports', 'Equilibrium', '2', 'Baseball simulation', 'Realistic baseball simulation featuring the legendary Cal Ripken Jr.', 'Win the world series by outplaying professional baseball teams.', 'Play ball with Cal Ripken Jr. Baseball for the Super Nintendo.', 'A detailed sports sim with multiple camera angles and roster management. Master pitching, hitting, and fielding to lead your team to the 16-bit championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cal-ripken-jr-baseball-usa-beta', 'SNES', 'Cal Ripken Jr. Baseball (USA) (Beta)', '1992', 'Sports', 'Equilibrium', '2', 'Baseball simulation', 'Realistic baseball simulation featuring the legendary Cal Ripken Jr.', 'Win the world series by outplaying professional baseball teams.', 'Check out the Cal Ripken Jr. Baseball Beta version on SNES.', 'A pre-release build of the baseball sim. See early player stats and mechanical tweaks as they were being developed for the final 16-bit release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('california-games-ii-europe-enfrde', 'SNES', 'California Games II (Europe) (En,Fr,De)', '1994', 'Sports', 'Epyx', '4', 'Multi-sport competition', 'Extreme sports compilation featuring skateboarding, surfing, and more.', 'Achieve the highest scores across multiple California-themed sports events.', 'Experience extreme sports in California Games II for the SNES.', 'Includes events like hang gliding, jet skiing, and bodyboarding. Master the unique controls for each sport to become the ultimate 16-bit extreme champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('california-games-ii-japan-enja', 'SNES', 'California Games II (Japan) (En,Ja)', '1994', 'Sports', 'Epyx', '4', 'Multi-sport competition', 'Extreme sports compilation featuring skateboarding, surfing, and more.', 'Achieve the highest scores across multiple California-themed sports events.', 'Experience extreme sports in California Games II for the SNES.', 'The Japanese release of the sports classic. Compete in vibrant 16-bit environments and master various disciplines to secure your spot on the leaderboards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('california-games-ii-usa', 'SNES', 'California Games II (USA)', '1994', 'Sports', 'Epyx', '4', 'Multi-sport competition', 'Extreme sports compilation featuring skateboarding, surfing, and more.', 'Achieve the highest scores across multiple California-themed sports events.', 'Experience extreme sports in California Games II for the SNES.', 'Includes events like hang gliding, jet skiing, and bodyboarding. Master the unique controls for each sport to become the ultimate 16-bit extreme champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('call-of-cthulhu', 'SNES', 'Call Of Cthulhu', 'Unknown', 'Adventure', 'Unknown', '1', 'Horror adventure', 'Unknown', 'Unknown', 'Explore the mysterious Call Of Cthulhu experience on SNES.', 'Unknown');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cameltry-japan', 'SNES', 'Cameltry (Japan)', '1989', 'Puzzle', 'Taito', '1', 'Physics-based puzzle', 'Action-puzzle game where you tilt the environment to guide a ball.', 'Guide the ball to the exit of the maze before time runs out.', 'Roll through mazes in the addictive Cameltry for the SNES.', 'A unique 16-bit title where you rotate the entire level instead of the ball. Navigate complex labyrinths filled with obstacles in this fast-paced arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cannon-fodder-europe', 'SNES', 'Cannon Fodder (Europe)', '1993', 'Strategy', 'Sensible Software', '2', 'Isometric war action', 'Squad-based strategy and action game with a dark sense of humor.', 'Lead your soldiers through various war zones to complete objectives.', 'Command your troops in the classic Cannon Fodder for the SNES.', 'A high-stakes strategy game where every soldier has a name. Manage your squad carefully to survive dozens of missions in this challenging 16-bit combat title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cannondale-cup-usa', 'SNES', 'Cannondale Cup (USA)', '1993', 'Racing', 'American Softworks', '2', 'Mountain bike racing', 'Off-road mountain bike racing simulation with sponsorship elements.', 'Win the Cannondale Cup by outracing rivals on treacherous trails.', 'Race mountain bikes in Cannondale Cup for the Super Nintendo.', 'A unique sports title focusing on downhill and cross-country biking. Manage your stamina and vehicle health to cross the finish line first in this 16-bit racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('capcoms-mvp-football-usa', 'SNES', 'Capcom''s MVP Football (USA)', '1991', 'Sports', 'Capcom', '2', 'American football', 'American football simulation featuring realistic plays and player stats.', 'Lead your team to victory in the professional football league.', 'Experience pro football in Capcom''s MVP Football for SNES.', 'Capcom''s take on the gridiron. Features detailed playbooks, smooth 16-bit animations, and a focus on the tactical side of American football.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('capcoms-soccer-shootout-usa', 'SNES', 'Capcom''s Soccer Shootout (USA)', '1994', 'Sports', 'Capcom', '2', 'Arcade soccer', 'Fast-paced arcade soccer simulation with special moves and power-ups.', 'Win the international tournament by outscoring the world''s best teams.', 'Score big goals in Capcom''s Soccer Shootout for the SNES.', 'A fan-favorite soccer game known for its fluid gameplay and indoor soccer mode. Execute powerful shots and tactical plays to win the 16-bit cup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('capcoms-soccer-shootout-usa-beta', 'SNES', 'Capcom''s Soccer Shootout (USA) (Beta)', '1994', 'Sports', 'Capcom', '2', 'Arcade soccer', 'Fast-paced arcade soccer simulation with special moves and power-ups.', 'Win the international tournament by outscoring the world''s best teams.', 'Explore the Capcom''s Soccer Shootout Beta version on SNES.', 'An early build of the classic soccer title. Features initial team balances and gameplay mechanics used during the development of this 16-bit sports hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-america-and-the-avengers-europe', 'SNES', 'Captain America and the Avengers (Europe)', '1993', 'Action', 'Data East', '2', 'Comic-style beat ''em up', 'Side-scrolling beat ''em up featuring the iconic Marvel superhero team.', 'Defeat Red Skull and his army to save the world.', 'Assemble the team in Captain America and the Avengers for SNES.', 'Play as Captain America, Iron Man, Hawkeye, or Vision. Use each hero''s unique projectiles and melee attacks to clear waves of 16-bit comic book villains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-america-and-the-avengers-usa', 'SNES', 'Captain America and the Avengers (USA)', '1993', 'Action', 'Data East', '2', 'Comic-style beat ''em up', 'Side-scrolling beat ''em up featuring the iconic Marvel superhero team.', 'Defeat Red Skull and his army to save the world.', 'Assemble the team in Captain America and the Avengers for SNES.', 'Play as Captain America, Iron Man, Hawkeye, or Vision. Use each hero''s unique projectiles and melee attacks to clear waves of 16-bit comic book villains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-commando-europe', 'SNES', 'Captain Commando (Europe)', '1992', 'Beat ''em up', 'Capcom', '2', 'Arcade brawler', 'Sci-fi belt-scrolling beat ''em up featuring a diverse team of heroes.', 'Protect the Earth from the "Scumocide" alien invaders.', 'Battle through the future in Captain Commando for the SNES.', 'Control the Captain, Mack the Knife, Ginzu the Ninja, or Baby Head. A faithful arcade port featuring massive mechs to pilot and intense 16-bit action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-commando-japan', 'SNES', 'Captain Commando (Japan)', '1992', 'Beat ''em up', 'Capcom', '2', 'Arcade brawler', 'Sci-fi belt-scrolling beat ''em up featuring a diverse team of heroes.', 'Protect the Earth from the "Scumocide" alien invaders.', 'Battle through the future in Captain Commando for the SNES.', 'The Japanese version of the Capcom classic. Face off against genetically modified criminals in a neon-soaked 16-bit future with cooperative multiplayer action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-commando-usa', 'SNES', 'Captain Commando (USA)', '1992', 'Beat ''em up', 'Capcom', '2', 'Arcade brawler', 'Sci-fi belt-scrolling beat ''em up featuring a diverse team of heroes.', 'Protect the Earth from the "Scumocide" alien invaders.', 'Battle through the future in Captain Commando for the SNES.', 'Master the art of the dash-attack and utilize environmental weapons. Captain Commando is a standout title in the SNES brawler library for its creative character designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-novolin-usa-enfres', 'SNES', 'Captain Novolin (USA) (En,Fr,Es)', '1992', 'Action', 'Spinnaker Software', '1', 'Educational action', 'Educational platformer focused on diabetes management.', 'Navigate through levels while maintaining blood sugar levels.', 'Learn and play with Captain Novolin on the Super Nintendo.', 'A rare health-focused game. Control the superhero Captain Novolin as he fights sugary enemies and teaches players about diet and insulin management in a 16-bit world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-tsubasa-iii---koutei-no-chousen-japan', 'SNES', 'Captain Tsubasa III - Koutei no Chousen (Japan)', '1992', 'Sports', 'Tecmo', '2', 'Anime soccer', 'Cinematic soccer RPG where actions are chosen through a menu system.', 'Win the World Youth Cup by defeating rival teams like Germany.', 'Lead Oliver Atom to victory in Captain Tsubasa III for SNES.', 'Experience the "Tecmo Cup" style gameplay with high-quality 16-bit animations. Use special shots like the Drive Shot and Tiger Shot to dominate international rivals in this cinematic classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-tsubasa-iv---pro-no-rival-tachi-japan', 'SNES', 'Captain Tsubasa IV - Pro no Rival-tachi (Japan)', '1993', 'Sports', 'Tecmo', '2', 'Anime soccer', 'Cinematic soccer RPG featuring a branching storyline and professional leagues.', 'Navigate Tsubasa''s professional career and overcome new rivals.', 'Experience the pro soccer life in Captain Tsubasa IV on SNES.', 'This entry introduces multiple story paths and a deeper focus on club teams. Manage stamina and strategy to execute spectacular special moves in this 16-bit anime-style simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-tsubasa-j---the-way-to-world-youth-japan', 'SNES', 'Captain Tsubasa J - The Way to World Youth (Japan)', '1994', 'Sports', 'Tecmo', '2', 'Anime soccer', 'Fast-paced soccer RPG based on the "J" series of the popular anime.', 'Lead the next generation of Japanese players to world dominance.', 'Play the high-energy Captain Tsubasa J for the Super Famicom.', 'Featuring updated graphics and a more aggressive pace, this title follows the World Youth arc. Master the new character abilities and team tactics to win the 16-bit championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-tsubasa-v---hasha-no-shougou-campione-japan', 'SNES', 'Captain Tsubasa V - Hasha no Shougou Campione (Japan)', '1995', 'Sports', 'Tecmo', '2', 'Anime soccer', 'The final 16-bit entry, blending traditional soccer gameplay with RPG menus.', 'Win the Italian league and prove you are the ultimate "Campione."', 'Become a soccer legend in Captain Tsubasa V for the SNES.', 'A departure from previous entries, offering more direct control over players while retaining cinematic special moves. Follow Tsubasa''s journey in the Serie A in this polished 16-bit finale.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('caravan-shooting-collection-japan', 'SNES', 'Caravan Shooting Collection (Japan)', '1995', 'Shooter', 'Namcot', '1', 'Vertical shooter compilation', 'Compilation of classic Hudson Soft arcade shoot ''em ups.', 'Achieve the highest score in 2-minute and 5-minute timed challenges.', 'Play the classic Caravan Shooting Collection on the SNES.', 'Includes the 8-bit hits Star Force, Star Soldier, and Hector ''87. Perfect for score-chasers, this collection features faithful 16-bit ports of legendary competitive shooters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('card-master---rimusaria-no-fuuin-japan', 'SNES', 'Card Master - Rimusaria no Fuuin (Japan)', '1992', 'RPG', 'Konami', '1', 'Turn-based fantasy RPG', 'Turn-based JRPG with a unique card-based battle and magic system.', 'Seal the ancient evil by collecting powerful elemental cards.', 'Master the cards in Card Master: Rimusaria no Fuuin for SNES.', 'Known as Arcana in the West. Navigate first-person dungeons and use a strategic card system for combat, featuring beautiful 16-bit artwork and a deep fantasy narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('carrier-aces-europe', 'SNES', 'Carrier Aces (Europe)', '1990', 'Simulation', 'Synergistic Software', '1', 'WWII air combat simulation', 'Flight combat simulation set during World War II carrier operations.', 'Complete carrier-based missions including dogfights and bombing runs.', 'Take to the skies in the WWII sim Carrier Aces for the SNES.', 'Features a split-screen view for taking off and landing. Pilot various Allied and Axis planes in tactical 16-bit aerial combat across the Pacific theater.');
