INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---dracula-x---remove-final-boss-room-pits', 'SNES', 'Castlevania - Dracula X - Remove final boss room pits', '1995', 'Action', 'ROM Hack', '1', 'Modified gothic action platformer', 'Side-scrolling action platformer with a fan-made modification for fairness.', 'Defeat Dracula without falling into the frustrating floor pits.', 'Play the Castlevania: Dracula X Pit-Fix mod on SNES.', 'This hack removes the controversial pits in the final boss room against Dracula, focusing the challenge purely on combat and timing rather than accidental environmental deaths.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---dracula-x-usa', 'SNES', 'Castlevania - Dracula X (USA)', '1995', 'Action', 'Konami', '1', 'Gothic action platformer', 'Side-scrolling action platformer featuring Richter Belmont.', 'Rescue Maria and Annette and defeat Count Dracula.', 'Face the darkness in Castlevania: Dracula X for the SNES.', 'A reimagining of Rondo of Blood. Features intense difficulty, branching paths, and incredible 16-bit graphics and music. Use the whip and sub-weapons to survive the demonic castle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---vampires-kiss-europe', 'SNES', 'Castlevania - Vampire''s Kiss (Europe)', '1995', 'Action', 'Konami', '1', 'Gothic action platformer', 'Side-scrolling action platformer featuring Richter Belmont.', 'Rescue Maria and Annette and defeat Count Dracula.', 'Experience Vampire''s Kiss, the European Castlevania classic.', 'The PAL version of Dracula X. Battle through gothic stages, master the Item Crash moves, and experience some of the most challenging platforming in the 16-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cb-chara-wars---ushinawareta-gag-japan', 'SNES', 'CB Chara Wars - Ushinawareta Gag (Japan)', '1992', 'Action', 'Bandai', '2', 'Chibi-style action', 'Top-down action game featuring SD (chibi) versions of Go Nagai characters.', 'Stop the "lost gag" crisis and defeat the bizarre enemies.', 'Join the wacky fight in CB Chara Wars for the Super Famicom.', 'Control iconic characters like Devilman and Mazinger Z in a cute, humorous style. Fight through waves of enemies and bosses in this unique 16-bit crossover adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('champions-world-class-soccer-europe-enfrdees', 'SNES', 'Champions World Class Soccer (Europe) (En,Fr,De,Es)', '1993', 'Sports', 'Park Place Productions', '2', 'Arcade soccer', 'Soccer simulation featuring international teams and tournament modes.', 'Win the World Cup by defeating the best national teams.', 'Experience Champions World Class Soccer on the SNES.', 'A realistic take on the sport for its time, featuring customizable formations and a variety of weather conditions. Master the passing game to win the 16-bit trophy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('champions-world-class-soccer-japan', 'SNES', 'Champions World Class Soccer (Japan)', '1993', 'Sports', 'Park Place Productions', '2', 'Arcade soccer', 'Soccer simulation featuring international teams and tournament modes.', 'Win the World Cup by defeating the best national teams.', 'Experience Champions World Class Soccer on the SNES.', 'A realistic take on the sport for its time, featuring customizable formations and a variety of weather conditions. Master the passing game to win the 16-bit trophy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('champions-world-class-soccer-usa-enfrdees', 'SNES', 'Champions World Class Soccer (USA) (En,Fr,De,Es)', '1993', 'Sports', 'Park Place Productions', '2', 'Arcade soccer', 'Soccer simulation featuring international teams and tournament modes.', 'Win the World Cup by defeating the best national teams.', 'Experience Champions World Class Soccer on the SNES.', 'A realistic take on the sport for its time, featuring customizable formations and a variety of weather conditions. Master the passing game to win the 16-bit trophy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('championship-pool-europe', 'SNES', 'Championship Pool (Europe)', '1993', 'Sports', 'Bit Managers', '2', 'Pool simulation', 'Top-down pool and billiards simulation with realistic physics.', 'Win the tournament by clearing the table in various pool disciplines.', 'Master the cue in Championship Pool for the SNES.', 'Includes 8-ball, 9-ball, and snooker. Featuring a precision aiming system and tournament progression, it''s a solid 16-bit simulation for billiards fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('championship-pool-usa', 'SNES', 'Championship Pool (USA)', '1993', 'Sports', 'Bit Managers', '2', 'Pool simulation', 'Top-down pool and billiards simulation with realistic physics.', 'Win the tournament by clearing the table in various pool disciplines.', 'Master the cue in Championship Pool for the SNES.', 'Includes 8-ball, 9-ball, and snooker. Featuring a precision aiming system and tournament progression, it''s a solid 16-bit simulation for billiards fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('championship-soccer-94-usa-enfrdeit', 'SNES', 'Championship Soccer ''94 (USA) (En,Fr,De,It)', '1994', 'Sports', 'Sculptured Software', '2', 'Arcade soccer', 'Soccer simulation focusing on speed and arcade-style play.', 'Outscore your opponents in various international leagues.', 'Play fast-paced soccer in Championship Soccer ''94 for SNES.', 'A localized version of Sensible Soccer. Known for its zoomed-out view and tight controls, allowing for tactical 16-bit gameplay and spectacular goals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chaos-engine-the-europe', 'SNES', 'Chaos Engine, The (Europe)', '1994', 'Action', 'The Bitmap Brothers', '2', 'Isometric run-and-gun', 'Top-down run-and-gun shooter set in a steampunk world.', 'Navigate through the metal labyrinth and destroy the Chaos Engine.', 'Experience the cult classic The Chaos Engine on SNES.', 'Known as Soldiers of Fortune in the US. Choose two mercenaries with unique skills and fight through Victorian-era levels filled with puzzles and deadly machines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chaos-seed---fuusui-kairouki-japan', 'SNES', 'Chaos Seed - Fuusui Kairouki (Japan)', '1996', 'RPG', 'Neverland', '1', 'Simulation-heavy RPG', 'Deep dungeon-crawling RPG with environmental manipulation and "Feng Shui."', 'Explore ancient ruins and balance the spiritual energy of the world.', 'Discover the complex RPG Chaos Seed for the Super Famicom.', 'A unique blend of action-RPG and simulation. Build rooms, manage resources, and engage in real-time combat while following a branching narrative in a beautiful 16-bit world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chavez-usa', 'SNES', 'Chavez (USA)', '1993', 'Sports', 'Telegames', '2', 'Boxing simulation', 'Realistic boxing simulation featuring the Mexican champion Julio César Chávez.', 'Climb the rankings and win the world title belt.', 'Step into the ring with Chavez for the Super Nintendo.', 'A Spanish-language localized version of Riddick Bowe Boxing. Features a career mode where you train your fighter and execute tactical combos in 16-bit matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chavez-usa-beta', 'SNES', 'Chavez (USA) (Beta)', '1993', 'Sports', 'Telegames', '2', 'Boxing simulation', 'Realistic boxing simulation featuring the Mexican champion Julio César Chávez.', 'Climb the rankings and win the world title belt.', 'Explore the Chavez Beta and its development on SNES.', 'A pre-release build of the boxing title. Test early AI behaviors and sprite animations used during the creation of this 16-bit sports game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chavez-ii-usa', 'SNES', 'Chavez II (USA)', '1994', 'Sports', 'Telegames', '2', 'Boxing simulation', 'The sequel to the boxing hit, featuring updated rosters and moves.', 'Defend your title against a new generation of boxers.', 'Experience the intense sequel Chavez II on the SNES.', 'Improves on the original with faster gameplay and more detailed fighter sprites. Continue your legacy in the ring and master the sweet science of 16-bit boxing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chessmaster-the-europe', 'SNES', 'Chessmaster, The (Europe)', '1991', 'Board Game', 'Software Toolworks', '2', 'Chess simulation', 'Traditional chess simulation with multiple difficulty levels and tutorials.', 'Checkmate the opponent''s king using strategic 16-bit chess moves.', 'Master the board in The Chessmaster for the SNES.', 'A robust chess engine for the Super Nintendo. Featuring various board styles, a dedicated teaching mode, and a range of AI personalities from novice to grandmaster level.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chessmaster-the-japan', 'SNES', 'Chessmaster, The (Japan)', '1991', 'Board Game', 'Software Toolworks', '2', 'Chess simulation', 'Traditional chess simulation with multiple difficulty levels and tutorials.', 'Checkmate the opponent''s king using strategic 16-bit chess moves.', 'Master the board in The Chessmaster for the SNES.', 'The Japanese edition of the classic chess title. Offers a clean interface and deep strategic gameplay for fans of the traditional board game on the 16-bit console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chessmaster-the-usa', 'SNES', 'Chessmaster, The (USA)', '1991', 'Board Game', 'Software Toolworks', '2', 'Chess simulation', 'Traditional chess simulation with multiple difficulty levels and tutorials.', 'Checkmate the opponent''s king using strategic 16-bit chess moves.', 'Master the board in The Chessmaster for the SNES.', 'Test your tactical skills against the "Chessmaster." Analyze your games, solve chess puzzles, and compete against a variety of virtual opponents in this comprehensive simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chester-cheetah---too-cool-to-fool-usa', 'SNES', 'Chester Cheetah - Too Cool to Fool (USA)', '1992', 'Platformer', 'Virgin Games', '1', 'Cartoon mascot platformer', 'Side-scrolling platformer featuring the smooth Cheetos mascot.', 'Collect the hidden parts of your scooter and escape the zoo.', 'Join the cool cat in Chester Cheetah: Too Cool to Fool on SNES.', 'A vibrant platformer where Chester uses his "cool" factor to navigate obstacles. Collect Cheetos snacks for power-ups and avoid the zookeeper''s traps in this 16-bit snack-themed adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chester-cheetah---wild-wild-quest-usa', 'SNES', 'Chester Cheetah - Wild Wild Quest (USA)', '1992', 'Platformer', 'Virgin Games', '1', 'Cartoon mascot platformer', 'Side-scrolling platformer with a map-based progression system.', 'Travel across the USA to reclaim Chester''s stolen map.', 'Go on a journey in Chester Cheetah: Wild Wild Quest for SNES.', 'The sequel features more diverse environments across America. Dash through levels, avoid enemies, and use special items to recover the map pieces in this fast-paced 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chester-cheetah---wild-wild-quest-usa-beta', 'SNES', 'Chester Cheetah - Wild Wild Quest (USA) (Beta)', '1992', 'Platformer', 'Virgin Games', '1', 'Cartoon mascot platformer', 'Side-scrolling platformer with a map-based progression system.', 'Travel across the USA to reclaim Chester''s stolen map.', 'Explore the Chester Cheetah: Wild Wild Quest Beta on SNES.', 'A pre-release version of the game. See early level designs and mechanical tweaks that were being tested before Chester''s final 16-bit cross-country quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chibi-maruko-chan---harikiri-365-nichi-no-maki-japan', 'SNES', 'Chibi Maruko-chan - Harikiri 365 Nichi no Maki (Japan)', '1992', 'Adventure', 'Bandai', '1', 'Family-friendly narrative adventure', 'Digital board game based on the popular "Chibi Maruko-chan" anime.', 'Participate in daily activities and mini-games to win the year-long event.', 'Enjoy family fun in Chibi Maruko-chan: Harikiri 365 Nichi on SNES.', 'Follow Maruko through a full year of seasonal events. Featuring charming 16-bit graphics and voices from the anime, this title focuses on fun, accessible mini-games for all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chibi-maruko-chan---mezase!-minami-no-island!!-japan', 'SNES', 'Chibi Maruko-chan - Mezase! Minami no Island!! (Japan)', '1995', 'Adventure', 'Bandai', '1', 'Family-friendly narrative adventure', 'Party game with various mini-games set on a tropical island.', 'Compete against family and friends to become the island champion.', 'Visit the tropics in Chibi Maruko-chan: Mezase! Minami no Island.', 'Join Maruko and her friends in a series of summer-themed challenges. Use strategy and reflexes to win tropical mini-games in this colorful 16-bit Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chinhai-japan', 'SNES', 'Chinhai (Japan)', '1991', 'Puzzle', 'Jaleco', '2', 'Arcade-style puzzle', 'Tile-matching puzzle game with a focus on speed and strategy.', 'Clear the screen of tiles by finding matching sets and patterns.', 'Test your speed in the Japanese puzzle game Chinhai for SNES.', 'A straightforward and addictive 16-bit puzzler. Match tiles quickly to prevent the board from filling up, featuring increasing difficulty and hidden bonus stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chomper-ville', 'SNES', 'Chomper Ville', '1993', 'Action', 'U.S. Gold', '1', 'Isometric action adventure', 'Unknown', 'Unknown', 'Explore the mysterious Chomper Ville on the SNES.', 'Unknown');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('choplifter-iii---rescue-survive-europe', 'SNES', 'Choplifter III - Rescue Survive (Europe)', '1992', 'Shooter', 'Beam Software', '1', 'Helicopter action shooter', 'Side-scrolling shooter where you pilot a combat helicopter.', 'Rescue hostages from enemy territory while surviving heavy fire.', 'Save the day in Choplifter III: Rescue Survive for the SNES.', 'The classic arcade series reaches its 16-bit peak. Pilot your chopper through war zones, manage fuel and ammo, and return prisoners to base in intense, multi-layered levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('choplifter-iii---rescue-survive-japan', 'SNES', 'Choplifter III - Rescue Survive (Japan)', '1992', 'Shooter', 'Beam Software', '1', 'Helicopter action shooter', 'Side-scrolling shooter where you pilot a combat helicopter.', 'Rescue hostages from enemy territory while surviving heavy fire.', 'Save the day in Choplifter III: Rescue Survive for the SNES.', 'The Japanese version of the intense helicopter rescue sim. Features detailed 16-bit sprites, challenging boss encounters, and a variety of terrains from deserts to urban ruins.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('choplifter-iii---rescue-survive-usa', 'SNES', 'Choplifter III - Rescue Survive (USA)', '1992', 'Shooter', 'Beam Software', '1', 'Helicopter action shooter', 'Side-scrolling shooter where you pilot a combat helicopter.', 'Rescue hostages from enemy territory while surviving heavy fire.', 'Save the day in Choplifter III: Rescue Survive for the SNES.', 'Master the delicate controls of the rescue chopper. This entry adds more weapons and specialized gear to help you survive the toughest 16-bit combat missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('choplifter-iii---rescue-survive-usa-beta', 'SNES', 'Choplifter III - Rescue Survive (USA) (Beta)', '1992', 'Shooter', 'Beam Software', '1', 'Helicopter action shooter', 'Side-scrolling shooter where you pilot a combat helicopter.', 'Rescue hostages from enemy territory while surviving heavy fire.', 'Check out the Choplifter III Beta version for the SNES.', 'An early build of the helicopter action game. Discover initial mission layouts and difficulty balancing used during the development of this 16-bit rescue classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-aniki---bakuretsu-rantou-hen-japan', 'SNES', 'Chou Aniki - Bakuretsu Rantou Hen (Japan)', '1995', 'Action', 'Fixer', '2', 'Erotic parody beat ''em up', 'Bizarre one-on-one fighting game featuring muscular, surreal characters.', 'Defeat the strange warriors of the empire to prove your strength.', 'Experience the madness of Chou Aniki: Bakuretsu Rantou Hen.', 'A cult classic known for its "bodybuilding" aesthetic and surreal humor. Master the unique moves of Idaten and Benten in this eccentric 16-bit fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-mahou-tairiku-wozz-japan', 'SNES', 'Chou Mahou Tairiku Wozz (Japan)', '1991', 'Action', 'Renovation Products', '1', 'Fantasy action platformer', 'Turn-based JRPG featuring a "steampunk meets fantasy" world.', 'Stop the invasion of the "Wozz" world using magic and machines.', 'Explore the unique Chou Mahou Tairiku Wozz on the SNES.', 'Featuring beautiful 16-bit visuals and a vehicle-crafting system. Lead a trio of heroes summoned from Earth to save a magical land in this deep and creative RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-mahou-tairiku-wozz-japan-en-by-transcorp-v10-~magical-land-of-wozz-the', 'SNES', 'Chou Mahou Tairiku Wozz (Japan) [En by TransCorp v1.0] (~Magical Land of Wozz, The)', '1991', 'Action', 'Renovation Products', '1', 'Fantasy action platformer', 'Turn-based JRPG featuring a "steampunk meets fantasy" world.', 'Experience the epic story of Wozz with a full English translation.', 'Play The Magical Land of Wozz in English on the SNES.', 'The definitive fan translation of this hidden gem. Now Western players can enjoy the deep story, humor, and innovative crafting mechanics of this 16-bit RPG masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-makai-taisen!-dorabot-chan-japan', 'SNES', 'Chou Makai Taisen! Dorabot-chan (Japan)', '1993', 'Action', 'Bandai', '1', 'Comedic sci-fi action', 'Side-scrolling action platformer featuring a young dragon boy.', 'Navigate through monster-filled levels to defeat the evil sorcerer.', 'Join the dragon boy in Chou Makai Taisen! Dorabot-chan.', 'A charming Japanese platformer where you use dragon powers to defeat enemies. Features vibrant 16-bit graphics and creative level designs for fans of the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-makaimura-japan', 'SNES', 'Chou Makaimura (Japan)', '1991', 'Action', 'Capcom', '1', 'Gothic hardcore action platformer', 'Side-scrolling action platformer known for its high difficulty.', 'Rescue Princess Prin-Prin from the demon realm as the knight Arthur.', 'Face the ultimate challenge in Chou Makaimura for the SNES.', 'Known as Super Ghouls ''n Ghosts in the West. Master the double-jump, upgrade your armor, and survive the punishing 16-bit levels to defeat the Emperor Sardius.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('choujikuu-yousai-macross---scrambled-valkyrie-japan', 'SNES', 'Choujikuu Yousai Macross - Scrambled Valkyrie (Japan)', '1993', 'Shooter', 'Zemekis', '1', 'Anime sci-fi shooter', 'Horizontal shoot ''em up with transforming mechs and Mode 7 effects.', 'Destroy the Zentradi forces to save the Earth from destruction.', 'Experience Macross: Scrambled Valkyrie, a top-tier SNES shooter.', 'Pilot three different transforming Valkyries (Fighter, Gerwalk, Battroid). Features incredible 16-bit graphics, multiple fire modes, and a soundtrack that captures the spirit of the anime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('choukou-goukami-xardion-japan', 'SNES', 'Choukou Goukami Xardion (Japan)', '1993', 'Action', 'Athena', '1', 'Futuristic run-and-gun', 'Side-scrolling action-platformer featuring customizable giant robots.', 'Stop the mechanical threat of Xardion by mastering three unique mechs.', 'Control giant robots in Choukou Goukami Xardion for SNES.', 'Switch between three mechs—Triton, Alunos, and Panthera—each with distinct abilities and leveling systems. A deep and atmospheric 16-bit sci-fi adventure with RPG elements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger---bugfix-and-uncensoring', 'SNES', 'Chrono Trigger - Bugfix and Uncensoring', '1995', 'RPG', 'ROM Hack', '1', 'Polished classic JRPG', 'Masterpiece turn-based JRPG with technical fixes and restored content.', 'Experience the original vision of the game without bugs or censorship.', 'Play the Uncensored & Bugfixed Chrono Trigger on SNES.', 'This version restores the original Japanese dialogue context (like references to alcohol) and fixes long-standing technical bugs, providing the most "pure" 16-bit experience possible.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger---complete', 'SNES', 'Chrono Trigger - Complete', '1995', 'RPG', 'ROM Hack', '1', 'Enhanced classic JRPG', 'Masterpiece turn-based JRPG featuring a compilation of best fan fixes.', 'Journey through time with the most complete and polished version available.', 'Experience Chrono Trigger Complete, the ultimate fan version.', 'A comprehensive mod that combines bug fixes, script translations, and graphical touch-ups into one definitive 16-bit package for the SNES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger---crimson-echoes-fan-made-game', 'SNES', 'Chrono Trigger - Crimson Echoes (Fan Made Game)', '2004', 'RPG', 'Fan Made', '1', 'Story-driven JRPG expansion', 'Epic fan-made sequel featuring a brand new story and world map.', 'Follow the heroes five years after the original game to stop a new threat.', 'Play the legendary fan-sequel Chrono Trigger: Crimson Echoes.', 'A massive project by Kajar Laboratories. Featuring dozens of hours of gameplay, new eras, and deep character development, it bridges the gap between Chrono Trigger and Chrono Cross.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger---flames-of-eternity-rc7c', 'SNES', 'Chrono Trigger - Flames of Eternity RC7C', '2009', 'RPG', 'Fan Made', '1', 'Dark narrative JRPG', 'Massive fan-made expansion and spiritual successor to Crimson Echoes.', 'Navigate through new timelines and stop a temporal disaster.', 'Experience the epic Flames of Eternity RC7C on the SNES.', 'Building upon the Crimson Echoes foundation, this version polishes the gameplay, adds new music, and completes the ambitious story started by the fan community.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger---master-quest', 'SNES', 'Chrono Trigger - Master Quest', '2002', 'RPG', 'Fan Made', '1', 'Rebalanced JRPG challenge', 'Enhanced difficulty mod with redesigned dungeons and boss encounters.', 'Test your mastery of the game with more complex and strategic battles.', 'Challenge yourself with Chrono Trigger: Master Quest on SNES.', 'A complete overhaul for veterans. Dungeons feature new layouts and bosses require specific tactics and dual/triple tech management to defeat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger---master-quest-jr-version', 'SNES', 'Chrono Trigger - Master Quest Jr. version', '2002', 'RPG', 'Fan Made', '1', 'Simplified JRPG challenge', 'A slightly more accessible version of the Master Quest difficulty mod.', 'Enjoy a significant challenge that isn''t as punishing as the full Master Quest.', 'Play Chrono Trigger: Master Quest Jr. for a balanced challenge.', 'Retains the new dungeon designs and AI improvements of the Master Quest but with more forgiving damage values, perfect for a fresh 16-bit experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger---music-library-japan-bs-en-by-terminus-v100e', 'SNES', 'Chrono Trigger - Music Library (Japan) (BS) [En by Terminus v1.00e]', '1995', 'Music', 'Square', '1', 'Soundtrack viewer', 'Digital music player featuring the iconic soundtrack, now in English.', 'Listen to the legendary Yasunori Mitsuda score with translated menus.', 'Enjoy the BS Chrono Trigger Music Library in English on SNES.', 'The translated version of the rare Satellaview broadcast. It allows players to enjoy the high-quality SNES soundtrack in a dedicated, interactive interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger---prophets-guile', 'SNES', 'Chrono Trigger - Prophet''s Guile', '2008', 'RPG', 'Fan Made', '1', 'Short story-driven JRPG', 'Story-driven fan expansion focusing on the character Magus.', 'Experience the events of the game from the perspective of the Prophet.', 'Uncover the secrets of Magus in Chrono Trigger: Prophet''s Guile.', 'A standalone side-story created by Kajar Laboratories. Follow Magus during his time in the Kingdom of Zeal as he plots to destroy Lavos from within.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger---schala-edition', 'SNES', 'Chrono Trigger - Schala Edition', '2008', 'RPG', 'ROM Hack', '1', 'Alternate narrative JRPG', 'Special edition mod that makes Schala a playable character.', 'Rescue Schala from her fate and include her in your time-traveling party.', 'Play as Schala in the unique Chrono Trigger: Schala Edition.', 'A fan-favorite mod that alters the story to allow Schala to join the team. Includes new dialogue, specialized techs for her, and a modified ending.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger---start-out-with-marle', 'SNES', 'Chrono Trigger - Start out with Marle', '1995', 'RPG', 'ROM Hack', '1', 'Alternate party start JRPG', 'Turn-based JRPG with a party-swapping mod to start with different characters.', 'Journey through time to prevent the global apocalypse starting with Marle.', 'Start your journey with Marle in this Chrono Trigger SNES mod.', 'A specialized fan modification that alters the starting party. Experience the early game with Marle’s abilities from the beginning while maintaining the legendary narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-japan', 'SNES', 'Chrono Trigger (Japan)', '1995', 'RPG', 'Square', '1', 'Time travel JRPG', 'Masterpiece turn-based JRPG featuring time travel and multiple endings.', 'Travel across different eras to save the future of the planet.', 'Experience the original Chrono Trigger (Japan) on the Super Famicom.', 'The legendary collaboration between Final Fantasy and Dragon Quest creators. Features a seamless battle system and a story that spans from prehistory to the end of time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-japan-sample', 'SNES', 'Chrono Trigger (Japan) (Sample)', '1995', 'RPG', 'Square', '1', 'Time travel JRPG', 'Masterpiece turn-based JRPG featuring time travel and multiple endings.', 'Explore a pre-release version of the game used for demonstration.', 'Check out the rare Chrono Trigger Sample version on SNES.', 'A fascinating piece of history. This Japanese sample version contains specific segments used for store displays before the final 16-bit release in 1995.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-usa', 'SNES', 'Chrono Trigger (USA)', '1995', 'RPG', 'Square', '1', 'Time travel JRPG', 'Masterpiece turn-based JRPG featuring time travel and multiple endings.', 'Travel across different eras to save the future of the planet.', 'Play the legendary Chrono Trigger (USA) on the Super Nintendo.', 'Widely considered one of the greatest RPGs of all time. Follow Crono and friends through time. Features 13 different endings based on your choices and timing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-usa-en-by-chrono-compendium-v101', 'SNES', 'Chrono Trigger (USA) [En by Chrono Compendium v1.01]', '1995', 'RPG', 'ROM Hack', '1', 'Fan-translated JRPG', 'Masterpiece turn-based JRPG featuring a refined fan-made translation.', 'Experience the epic story with a more accurate and polished script.', 'Play the definitive Chrono Trigger translation by Chrono Compendium.', 'A dedicated fan project that re-translates the script to be more faithful to the creators'' intent, fixing localization errors from the original 1995 release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-usa-en-by-doctor-l-v101', 'SNES', 'Chrono Trigger (USA) [En by Doctor L v1.01]', '1995', 'RPG', 'ROM Hack', '1', 'Fan-translated JRPG', 'Masterpiece turn-based JRPG featuring a refined fan-made translation.', 'Experience the epic story with a more accurate and polished script.', 'Enjoy the Doctor L translation of Chrono Trigger for the SNES.', 'A high-quality re-translation effort focusing on natural dialogue and technical fixes, providing a fresh perspective on the classic 16-bit time-travel narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-usa-hack-by-kajar-laboratories-demo-2-~chrono-trigger---crimson-echos', 'SNES', 'Chrono Trigger (USA) [Hack by Kajar Laboratories Demo 2] (~Chrono Trigger - Crimson Echos)', '2004', 'RPG', 'Fan Made', '1', 'Story-driven JRPG expansion', 'Epic fan-made sequel featuring a brand new story and world map.', 'Follow the heroes five years after the original game to stop a new threat.', 'Explore the Crimson Echoes Demo by Kajar Laboratories.', 'An early look at the massive fan-sequel project. It showcases the new eras, characters, and improved battle mechanics that define this legendary 16-bit mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-usa-hack-by-kajar-laboratories-v10-~chrono-trigger---prophets-guile', 'SNES', 'Chrono Trigger (USA) [Hack by Kajar Laboratories v1.0] (~Chrono Trigger - Prophet''s Guile)', '2008', 'RPG', 'Fan Made', '1', 'Short narrative JRPG', 'Story-driven fan expansion focusing on the character Magus.', 'Experience the events of the game from the perspective of the Prophet.', 'Uncover the secrets of Magus in Chrono Trigger: Prophet''s Guile.', 'A standalone side-story. Lead Magus through the halls of Zeal as he uses his future knowledge to manipulate events and prepare for his final battle with Lavos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-usa-hack-by-kajar-laboratories-v21-~chrono-trigger-coliseum', 'SNES', 'Chrono Trigger (USA) [Hack by Kajar Laboratories v2.1] (~Chrono Trigger Coliseum)', '2008', 'RPG', 'Fan Made', '1', 'Arena-style battle JRPG', 'Combat-focused mod featuring an arena-style gauntlet.', 'Defeat waves of increasingly difficult enemies to earn rare rewards.', 'Test your combat skills in Chrono Trigger Coliseum for SNES.', 'A modification that focuses entirely on the battle system. Face off against every boss and enemy in the game in a challenging, tournament-style 16-bit format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-101', 'SNES', 'Chrono Trigger 1.01', '1995', 'RPG', 'Square', '1', 'Time travel JRPG', 'Masterpiece turn-based JRPG with minor technical and text fixes.', 'Journey through time to prevent the global apocalypse caused by Lavos.', 'Play the refined Chrono Trigger 1.01 version on the SNES.', 'A minor update to the original release that addresses small bugs and typos, ensuring the smoothest possible 16-bit RPG experience for purists.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-6-letter-name', 'SNES', 'Chrono Trigger 6-Letter Name', '1995', 'RPG', 'ROM Hack', '1', 'Expanded character naming', 'Turn-based JRPG mod that allows for longer character naming conventions.', 'Journey through time with custom 6-letter names for your party.', 'Customize your team in Chrono Trigger 6-Letter Name mod.', 'A technical hack that expands the character name limit from 5 to 6 characters, allowing fans to use more accurate names (like "Magus") without abbreviations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-devolution', 'SNES', 'Chrono Trigger Devolution', '1999', 'RPG', 'ROM Hack', '1', 'Minimalist JRPG challenge', 'Enhanced version of the original game with restored content and features.', 'Save the world from Lavos with modern quality-of-life improvements.', 'Experience the Chrono Trigger Devolution mod on the SNES.', 'A comprehensive "best of" version that integrates features from later ports (like the DS version) back into the original 16-bit SNES engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-impossible', 'SNES', 'Chrono Trigger Impossible', '2000', 'RPG', 'ROM Hack', '1', 'Extreme difficulty JRPG', 'Extreme difficulty hack for veteran players seeking a brutal challenge.', 'Survive the journey through time with vastly stronger enemies.', 'Face the ultimate challenge in Chrono Trigger Impossible.', 'Every enemy and boss has been completely redesigned with new AI and higher stats. Only for those who have fully mastered every mechanic of the original game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-lavos-awakening-hardtype', 'SNES', 'Chrono Trigger Lavos'' Awakening (Hardtype)', '2002', 'RPG', 'ROM Hack', '1', 'Hardtype difficulty overhaul', 'Hardcore rebalance mod focusing on a darker atmosphere and higher difficulty.', 'Stop Lavos in a world where the stakes and the enemies are higher.', 'Experience the grueling Lavos'' Awakening Hardtype mod.', 'Increases tactical depth. You''ll need to master every dual and triple tech to survive the revamped boss encounters and environmental hazards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-platinum', 'SNES', 'Chrono Trigger Platinum', '2003', 'RPG', 'ROM Hack', '1', 'Balanced enhancement JRPG', 'Comprehensive overhaul mod with new items, rebalanced techs, and secrets.', 'Explore a familiar world with thousands of mechanical improvements.', 'Play the definitive Chrono Trigger Platinum edition on SNES.', 'A "Gold Standard" mod that balances the entire game. It buffs underused characters, adds new equipment, and makes the late-game content more engaging.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-trigger-plus-26', 'SNES', 'Chrono Trigger plus 2.6', '2006', 'RPG', 'ROM Hack', '1', 'Content-expanded JRPG', 'Massive expansion mod adding new side quests and lore-friendly content.', 'Experience the classic story with new areas and characters.', 'Explore more of the world in Chrono Trigger plus 2.6.', 'This mod integrates new events, restores cut content from the original development, and adds meaningful side stories that flesh out the 16-bit world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuck-rock-europe', 'SNES', 'Chuck Rock (Europe)', '1991', 'Platformer', 'Core Design', '1', 'Prehistoric action platformer', 'Side-scrolling platformer featuring a caveman with a unique headbutt attack.', 'Rescue your girlfriend from the rival caveman clan.', 'Join the prehistoric fun in Chuck Rock for the Super Nintendo.', 'Control Chuck as he headbutts his way through dinosaurs and prehistoric traps. Use rocks to reach higher platforms and defeat bosses in this classic 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuck-rock-usa', 'SNES', 'Chuck Rock (USA)', '1991', 'Platformer', 'Core Design', '1', 'Prehistoric action platformer', 'Side-scrolling platformer featuring a caveman with a unique headbutt attack.', 'Rescue your girlfriend from the rival caveman clan.', 'Join the prehistoric fun in Chuck Rock for the Super Nintendo.', 'Control Chuck as he headbutts his way through dinosaurs and prehistoric traps. Use rocks to reach higher platforms and defeat bosses in this classic 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuck-rock-usa-beta', 'SNES', 'Chuck Rock (USA) (Beta)', '1991', 'Platformer', 'Core Design', '1', 'Prehistoric action platformer', 'Side-scrolling platformer featuring a caveman with a unique headbutt attack.', 'Rescue your girlfriend from the rival caveman clan.', 'Check out the Chuck Rock Beta and its development on SNES.', 'A pre-release build of the prehistoric platformer. Discover early level layouts and sprite work that were adjusted before the final 16-bit retail release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('circuit-usa-japan', 'SNES', 'Circuit USA (Japan)', '1991', 'Racing', 'Nintendo', '1', 'Arcade-style top-down racing', 'Futuristic racing game featuring high-speed circuits across the USA.', 'Win the national racing championship by outperforming rival drivers.', 'Race across America in the fast-paced Circuit USA for SNES.', 'Utilizing Mode 7 effects for a sense of speed, this title challenges players to master various tracks and weather conditions in a competitive 16-bit racing circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('civilization---sekai-shichi-daibunmei-japan', 'SNES', 'Civilization - Sekai Shichi Daibunmei (Japan)', '1993', 'Strategy', 'MicroProse', '1', 'Turn-based grand strategy', 'Deep grand strategy and empire-building simulation.', 'Lead your civilization from the Stone Age to the Space Age.', 'Build an empire in the SNES version of Sid Meier''s Civilization.', 'A surprisingly deep port of the PC classic. Manage resources, research technologies, and engage in diplomacy or war to become the dominant power on Earth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('civilization-usa', 'SNES', 'Civilization (USA)', '1994', 'Strategy', 'MicroProse', '1', 'Turn-based grand strategy', 'Deep grand strategy and empire-building simulation.', 'Lead your civilization from the Stone Age to the Space Age.', 'Build an empire in the SNES version of Sid Meier''s Civilization.', 'A surprisingly deep port of the PC classic. Manage resources, research technologies, and engage in diplomacy or war to become the dominant power on Earth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('civilization-usa-beta', 'SNES', 'Civilization (USA) (Beta)', '1994', 'Strategy', 'MicroProse', '1', 'Turn-based grand strategy', 'Deep grand strategy and empire-building simulation.', 'Lead your civilization from the Stone Age to the Space Age.', 'Explore the Civilization Beta version for the Super Nintendo.', 'A pre-release version of the strategy epic. See how the complex UI and mechanics were adapted for the SNES controller during development.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-kong', 'SNES', 'Classic Kong', '1981', 'Platformer', 'Nintendo', '1', 'Arcade-style platformer', 'Arcade-style platformer inspired by the 1981 classic Donkey Kong.', 'Climb the girders and rescue the girl from the giant ape.', 'Experience the homebrew tribute Classic Kong on the SNES.', 'A faithful recreation of the original arcade gameplay with updated 16-bit graphics. Dodge barrels, climb ladders, and time your jumps to reach the top.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-road-japan', 'SNES', 'Classic Road (Japan)', '1993', 'Strategy', 'Hect', '1', 'Turn-based road-building strategy', 'Realistic horse racing simulation with betting and stable management.', 'Train your horses and win the most prestigious races in Japan.', 'Master the tracks in Classic Road for the Super Famicom.', 'A deep simulation where you manage every aspect of a racehorse''s career. Study the odds, choose your jockey, and aim for the Triple Crown.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-road-ii-japan', 'SNES', 'Classic Road II (Japan)', '1995', 'Strategy', 'Hect', '1', 'Advanced turn-based strategy', 'Realistic horse racing simulation with betting and stable management.', 'Train your horses and win the most prestigious races in Japan.', 'Master the tracks in Classic Road II for the Super Famicom.', 'The sequel expands on the original with more detailed stats, new breeding mechanics, and improved 16-bit visuals for horse racing enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clay-fighter---tournament-edition-usa', 'SNES', 'Clay Fighter - Tournament Edition (USA)', '1993', 'Fighting', 'Interplay', '2', 'Clay animation fighting game', 'One-on-one fighting game featuring stop-motion clay animation.', 'Win the tournament against eccentric clay-based warriors.', 'Fight in the arena with Clay Fighter: Tournament Edition.', 'A specialized version of the first game with improved balance and new stages. Features the same wacky characters like Bad Mr. Frosty and Bonker the Clown.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clay-fighter-europe', 'SNES', 'Clay Fighter (Europe)', '1993', 'Fighting', 'Interplay', '2', 'Clay animation fighting game', 'One-on-one fighting game featuring stop-motion clay animation.', 'Defeat the other clay fighters to prove you are the best in the land.', 'Experience the wacky Clay Fighter on the Super Nintendo.', 'Famous for its unique "Claymation" art style and humorous tone. Master absurd special moves in this 16-bit fighter that parodies the genre''s tropes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clay-fighter-usa', 'SNES', 'Clay Fighter (USA)', '1993', 'Fighting', 'Interplay', '2', 'Clay animation fighting game', 'One-on-one fighting game featuring stop-motion clay animation.', 'Defeat the other clay fighters to prove you are the best in the land.', 'Experience the wacky Clay Fighter on the Super Nintendo.', 'Choose from a cast of bizarre characters and battle across colorful stages. A fun and accessible fighter with a distinct 16-bit visual identity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clay-fighter-2---judgment-clay-europe', 'SNES', 'Clay Fighter 2 - Judgment Clay (Europe)', '1994', 'Fighting', 'Interplay', '2', 'Sequel clay animation fighting game', 'One-on-one fighting game featuring new characters and gameplay mechanics.', 'Survive the "Judgment Clay" tournament and defeat the boss.', 'The clay combat continues in Clay Fighter 2 for the SNES.', 'Featuring a new cast and a slightly darker tone. This sequel introduces more complex combos and refined 16-bit clay animation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clay-fighter-2---judgment-clay-usa', 'SNES', 'Clay Fighter 2 - Judgment Clay (USA)', '1994', 'Fighting', 'Interplay', '2', 'Sequel clay animation fighting game', 'One-on-one fighting game featuring new characters and gameplay mechanics.', 'Survive the "Judgment Clay" tournament and defeat the boss.', 'The clay combat continues in Clay Fighter 2 for the SNES.', 'Battle with characters like Tiny and Nana Hacklease. This entry focuses on faster gameplay and more "punny" humor in its 16-bit combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('claymates-europe', 'SNES', 'Claymates (Europe)', '1993', 'Platformer', 'Interplay', '1', 'Clay animation platformer', 'Puzzle-platformer where you morph into different clay animals.', 'Navigate through the neighborhood to rescue your father.', 'Morph and explore in the unique Claymates for the SNES.', 'A creative title from Interplay. Change into a cat, a fish, or a mouse to solve environmental puzzles and defeat enemies in a vibrant 16-bit world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('claymates-usa', 'SNES', 'Claymates (USA)', '1993', 'Platformer', 'Interplay', '1', 'Clay animation platformer', 'Puzzle-platformer where you morph into different clay animals.', 'Navigate through the neighborhood to rescue your father.', 'Morph and explore in the unique Claymates for the SNES.', 'Use each animal''s unique abilities (like the cat''s climbing or the fish''s swimming) to uncover secrets and progress through diverse stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('claymates-usa-sample', 'SNES', 'Claymates (USA) (Sample)', '1993', 'Platformer', 'Interplay', '1', 'Clay animation platformer', 'Puzzle-platformer where you morph into different clay animals.', 'Navigate through the neighborhood to rescue your father.', 'Check out the Claymates Sample version on the SNES.', 'A demonstration build used to showcase the morphing mechanics and the high-quality 16-bit clay graphics before the official release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cliffhanger-europe', 'SNES', 'Cliffhanger (Europe)', '1993', 'Action', 'Sony Imagesoft', '1', 'Movie-based action platformer', 'Action-adventure platformer based on the 1993 Sylvester Stallone film.', 'Rescue your friends and defeat the terrorists on the mountain.', 'Battle through the cold in Cliffhanger for the Super Nintendo.', 'Navigate treacherous mountain slopes, climb cliffs, and engage in hand-to-hand combat in this 16-bit movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cliffhanger-usa', 'SNES', 'Cliffhanger (USA)', '1993', 'Action', 'Sony Imagesoft', '1', 'Movie-based action platformer', 'Action-adventure platformer based on the 1993 Sylvester Stallone film.', 'Rescue your friends and defeat the terrorists on the mountain.', 'Battle through the cold in Cliffhanger for the Super Nintendo.', 'Features both platforming and beat ''em up sections. Survive avalanches and face off against bosses in the rugged 16-bit wilderness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clock-tower-japan', 'SNES', 'Clock Tower (Japan)', '1995', 'Horror', 'Human Entertainment', '1', 'Psychological survival horror', 'Survival horror adventure with point-and-click exploration.', 'Escape the Barrows mansion while avoiding the "Scissorman."', 'Experience the original survival horror, Clock Tower, on SNES.', 'A cult classic known for its terrifying atmosphere. Hide, solve puzzles, and make life-or-death choices in this 16-bit pioneer of the horror genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clock-tower-japan-en-by-aeon-genesis-v101', 'SNES', 'Clock Tower (Japan) [En by Aeon Genesis v1.01]', '1995', 'Horror', 'Human Entertainment', '1', 'Fan-translated survival horror', 'Survival horror adventure with point-and-click exploration.', 'Escape the mansion and uncover the secrets of the Barrows family in English.', 'Play the English translation of Clock Tower on the SNES.', 'The definitive fan translation by Aeon Genesis. Experience the full story and chilling tension of this Japanese horror masterpiece in English for the first time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clockwerx-japan', 'SNES', 'Clockwerx (Japan)', '1994', 'Puzzle', 'T&E Soft', '1', 'Rotational puzzle game', 'Puzzle game where you rotate clock gears to guide a spark.', 'Connect the gears correctly to reach the exit before time runs out.', 'Solve the mechanical puzzles of Clockwerx for the Super Famicom.', 'A fast-paced test of logic and timing. Navigate through dozens of levels filled with obstacles that require precise gear management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clue-usa', 'SNES', 'Clue (USA)', '1992', 'Board Game', 'Parker Brothers', '4', 'Digital board game', 'Digital board game based on the classic mystery franchise.', 'Solve the murder by deducing the culprit, weapon, and room.', 'Solve the mystery in Clue for the Super Nintendo.', 'A faithful 16-bit adaptation of the board game. Move through the mansion, gather clues, and use the process of elimination to win.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('college-football-usa-97---the-road-to-new-orleans-usa', 'SNES', 'College Football USA ''97 - The Road to New Orleans (USA)', '1996', 'Sports', 'EA Sports', '2', 'American football simulation', 'American football simulation focusing on the college league.', 'Lead your favorite college team to victory in the Sugar Bowl.', 'Experience college football in College Football USA ''97 on SNES.', 'Part of the EA Sports series. Features real college teams, authentic playbooks, and the quest for the #1 ranking in the 16-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('college-slam-usa', 'SNES', 'College Slam (USA)', '1996', 'Sports', 'Acclaim', '4', 'Arcade-style basketball', 'Arcade-style 2-on-2 basketball featuring college teams and high-flying dunks.', 'Win the tournament by outscoring rival college teams with power-ups.', 'Experience the madness of College Slam on the Super Nintendo.', 'A college-themed spin-off of NBA Jam. Featuring big-head mode, massive dunks, and the iconic "On Fire" mechanic across various 16-bit college arenas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('columns-japan-np', 'SNES', 'Columns (Japan) (NP)', '1990', 'Puzzle', 'Sega', '2', 'Falling block puzzle', 'Tile-matching puzzle game where you align colored gems vertically or diagonally.', 'Clear columns of jewels to prevent the screen from filling up.', 'Master the classic Sega puzzler Columns on the SNES.', 'A rare Nintendo Power service release. Arrange falling jewels in sets of three to create chain reactions in this addictive 16-bit logic challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('combatribes-the-japan', 'SNES', 'Combatribes, The (Japan)', '1990', 'Beat ''em up', 'Technos Japan', '2', 'Side-scrolling brawler', 'Belt-scrolling beat ''em up featuring three distinct brawlers.', 'Defeat the "Ground Zero" gang and their cybernetic leader.', 'Fight through the streets in The Combatribes for the SNES.', 'A port of the Technos arcade hit. Choose between Bullova, Blitz, or Berzerker and use powerful grab moves to clear waves of 16-bit street thugs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('combatribes-the-usa', 'SNES', 'Combatribes, The (USA)', '1990', 'Beat ''em up', 'Technos Japan', '2', 'Side-scrolling brawler', 'Belt-scrolling beat ''em up featuring three distinct brawlers.', 'Defeat the "Ground Zero" gang and their cybernetic leader.', 'Fight through the streets in The Combatribes for the SNES.', 'Experience the gritty 16-bit action of this arcade port. Utilize unique environmental interactions and massive boss fights to restore order to the city.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('computer-nouryoku-kaiseki---ultra-baken-japan', 'SNES', 'Computer Nouryoku Kaiseki - Ultra Baken (Japan)', '1993', 'Gambling', 'Namco', '1', 'Horse betting simulation', 'Horse racing analysis and betting simulation software.', 'Use data analysis to predict winning horses in professional races.', 'Analyze the odds in Ultra Baken for the Super Famicom.', 'More of a utility than a game, this title allowed Japanese players to input racing data to calculate winning probabilities for 16-bit horse race betting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('congo-the-movie---the-secret-of-zinj-usa-proto', 'SNES', 'Congo the Movie - The Secret of Zinj (USA) (Proto)', '1995', 'Action', 'Viacom New Media', '1', 'Movie-based action adventure', 'First-person action-adventure based on the movie (Unreleased Prototype).', 'Explore the jungle and find the diamond mines of the lost city.', 'Play the unreleased Congo the Movie prototype on SNES.', 'A rare look at a cancelled project. Navigate 3D-style environments from a first-person perspective, solving puzzles and avoiding jungle hazards in this 16-bit movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('congos-caper-europe', 'SNES', 'Congo''s Caper (Europe)', '1994', 'Platformer', 'Data East', '1', 'Cute action platformer', 'Side-scrolling action platformer starring a half-monkey caveman boy.', 'Rescue your girlfriend and defeat the demon lords in a prehistoric world.', 'Join the fun in Congo''s Caper for the Super Nintendo.', 'A spiritual successor to Joe & Mac. Control Congo, use his jumping agility and club to clear stages filled with dinosaurs and 16-bit charm.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('congos-caper-usa', 'SNES', 'Congo''s Caper (USA)', '1994', 'Platformer', 'Data East', '1', 'Cute action platformer', 'Side-scrolling action platformer starring a half-monkey caveman boy.', 'Rescue your girlfriend and defeat the demon lords in a prehistoric world.', 'Join the fun in Congo''s Caper for the Super Nintendo.', 'Explore vibrant prehistoric levels. Collecting three diamonds transforms Congo into a powerful human form, granting new abilities to tackle the toughest 16-bit bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('conkers-high-rule-tail', 'SNES', 'Conker''s High Rule Tail', '1994', 'Action Adventure', 'Rare', '1', 'Cute action platformer', 'Action-adventure fan mod that replaces Link with Conker the Squirrel.', 'Explore the land of Hyrule with Conker''s unique personality and moves.', 'Play the Zelda crossover Conker''s High Rule Tail on SNES.', 'A creative hack of A Link to the Past. Experience the classic Zelda engine with Conker as the lead, featuring new dialogue and a humorous twist on the legendary 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('contra-iii---the-alien-wars-usa', 'SNES', 'Contra III - The Alien Wars (USA)', '1992', 'Run and Gun', 'Konami', '2', 'Fast-paced side-scrolling shooter', 'High-octane run-and-gun shooter featuring Mode 7 boss battles.', 'Defeat the alien invasion and save Earth from total destruction.', 'Experience the legendary Contra III: The Alien Wars on SNES.', 'Widely considered one of the best action games on the system. Dual-wield weapons, hang from ceilings, and survive punishing 16-bit stages with legendary difficulty.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('contra-iii:-the-alien-wars-restoration', 'SNES', 'Contra III: The Alien Wars Restoration', '1992', 'Run and Gun', 'Konami', '2', 'Restored arcade-style shooter', 'High-octane run-and-gun shooter with restored Japanese features.', 'Defeat the aliens with infinite continues and restored cheat codes.', 'Play the definitive Contra III Restoration mod on SNES.', 'This hack restores the "Probotector" style features and original Japanese difficulty options (like infinite continues) to the Western version for the ultimate 16-bit experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('contra-spirits-japan', 'SNES', 'Contra Spirits (Japan)', '1992', 'Run and Gun', 'Konami', '2', 'Japanese version run-and-gun', 'High-octane run-and-gun shooter known for its intense difficulty.', 'Save Earth from the alien threat in the original Japanese version.', 'Experience Contra Spirits, the original 16-bit Japanese classic.', 'Features the iconic top-down and side-scrolling stages. Use the "bomb" mechanic and specialized weapon drops to survive the mechanical alien onslaught.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('conveni-wars-barcode-battler-senki---super-senshi-shutsugeki-seyo!-japan', 'SNES', 'Conveni Wars Barcode Battler Senki - Super Senshi Shutsugeki seyo! (Japan)', '1992', 'Strategy', 'Bandai', '1', 'Barcode-based tactical RPG', 'RPG and strategy hybrid featuring barcode-battling mechanics.', 'Defeat rival warriors by utilizing data from commercial barcodes.', 'Experience the unique Barcode Battler Senki on SNES.', 'A specialized Japanese title where players could use a physical peripheral to scan barcodes from real-world products to generate stats and characters for 16-bit battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cool-spot-europe', 'SNES', 'Cool Spot (Europe)', '1993', 'Platformer', 'Virgin Interactive', '1', 'Mascot platformer', 'Side-scrolling platformer starring the 7-Up mascot.', 'Rescue your "Spot" friends from their cages across various levels.', 'Join the cool cat in Cool Spot for the Super Nintendo.', 'Features incredibly smooth animation and a catchy soundtrack. Collect red spots and navigate through oversized 16-bit environments in this classic brand tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cool-spot-japan', 'SNES', 'Cool Spot (Japan)', '1993', 'Platformer', 'Virgin Interactive', '1', 'Mascot platformer', 'Side-scrolling platformer starring the 7-Up mascot.', 'Rescue your "Spot" friends from their cages across various levels.', 'Join the cool cat in Cool Spot for the Super Nintendo.', 'The Japanese release of the 7-Up platformer. Experience the same high-quality 16-bit visuals and challenging levels that made this title a standout in the mascot era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cool-spot-usa', 'SNES', 'Cool Spot (USA)', '1993', 'Platformer', 'Virgin Interactive', '1', 'Mascot platformer', 'Side-scrolling platformer starring the 7-Up mascot.', 'Rescue your "Spot" friends from their cages across various levels.', 'Join the cool cat in Cool Spot for the Super Nintendo.', 'Master the projectile shooting and diagonal jumping mechanics to find all the secrets hidden in the 16-bit beach and toy store levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cool-spot-usa-beta', 'SNES', 'Cool Spot (USA) (Beta)', '1993', 'Platformer', 'Virgin Interactive', '1', 'Mascot platformer', 'Side-scrolling platformer starring the 7-Up mascot.', 'Rescue your "Spot" friends from their cages across various levels.', 'Explore the Cool Spot Beta version for the Super Nintendo.', 'A pre-release version of the mascot platformer. Discover early level layouts and sprite animations that were polished before the final 16-bit release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cool-world-europe', 'SNES', 'Cool World (Europe)', '1992', 'Action', 'Probe Software', '1', 'Movie-based action platformer', 'Action-platformer based on the movie blending live-action and animation.', 'Travel between the Real World and the Cool World to stop Holli Would.', 'Explore the surreal Cool World for the Super Nintendo.', 'Navigate through bizarre, cartoon-inspired levels. Use your ink pen to capture enemies and solve puzzles in this atmospheric 16-bit movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cool-world-usa', 'SNES', 'Cool World (USA)', '1992', 'Action', 'Probe Software', '1', 'Movie-based action platformer', 'Action-platformer based on the movie blending live-action and animation.', 'Travel between the Real World and the Cool World to stop Holli Would.', 'Explore the surreal Cool World for the Super Nintendo.', 'A unique take on the film''s premise. Battle weird doodles and navigate complex 16-bit stages as you try to prevent the two worlds from merging.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('corn-buster-europe-proto', 'SNES', 'Corn Buster (Europe) (Proto)', '1993', 'Puzzle', 'Unknown', '1', 'Prototype tile puzzle game', 'Side-scrolling run-and-gun shooter (Unreleased Prototype).', 'Fight through waves of enemies in a futuristic setting.', 'Discover the unreleased Corn Buster prototype on SNES.', 'A rare action title that was cancelled before completion. Features impressive sprite work and fast-paced 16-bit shooting mechanics that show what could have been.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('coron-land-japan', 'SNES', 'Coron Land (Japan)', '1995', 'Platformer', 'Yutaka', '1', 'Cute Japanese platformer', 'Puzzle-platformer featuring cute characters and environmental riddles.', 'Help the characters navigate through colorful stages to reach the exit.', 'Enjoy the charming Coron Land for the Super Famicom.', 'A Japanese-exclusive title focused on logic and timing. Move blocks and interact with the environment to clear stages in this beautifully animated 16-bit world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cosmo-gang---the-puzzle-japan', 'SNES', 'Cosmo Gang - The Puzzle (Japan)', '1992', 'Puzzle', 'Namco', '2', 'Arcade-style puzzle game', 'Falling block puzzle game featuring the Cosmo Gang characters.', 'Clear the board by aligning characters and clearing obstacles.', 'Master the puzzles of Cosmo Gang: The Puzzle for SNES.', 'A spin-off of the arcade series. Similar to Tetris or Puyo Puyo, it requires quick thinking and strategy to clear the screen in this vibrant 16-bit puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cosmo-gang---the-video-japan', 'SNES', 'Cosmo Gang - The Video (Japan)', '1992', 'Shooter', 'Namco', '2', 'Arcade-style fixed shooter', 'Fixed-screen shooter with colorful graphics and quirky enemies.', 'Protect your energy supply from the invading Cosmo Gang aliens.', 'Blast off in Cosmo Gang: The Video for the SNES.', 'A polished 16-bit take on the Galaga-style shooter. Features multiple waves of enemies, powerful weapon upgrades, and massive boss encounters with a humorous twist.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cosmo-police-galivan-ii---arrow-of-justice-japan', 'SNES', 'Cosmo Police Galivan II - Arrow of Justice (Japan)', '1993', 'Action', 'NCS', '1', 'Tokusatsu action platformer', 'Side-scrolling beat ''em up with a sci-fi tokusatsu theme.', 'Defeat the intergalactic criminal syndicate and restore justice.', 'Fight for justice in Cosmo Police Galivan II for SNES.', 'Control armored heroes in this intense 16-bit brawler. Utilize powerful special moves and weapon pick-ups to clear levels inspired by Japanese space-sheriff shows.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crayon-shin-chan---arashi-o-yobu-enji-japan', 'SNES', 'Crayon Shin-chan - Arashi o Yobu Enji (Japan)', '1994', 'Platformer', 'Banpresto', '1', 'Comedy anime platformer', 'Side-scrolling platformer featuring the mischievous Shin-chan.', 'Navigate through town and school while completing wacky tasks.', 'Join the fun in Crayon Shin-chan: Arashi o Yobu Enji for SNES.', 'A charming 16-bit platformer based on the popular anime. Use Shin-chan''s unique moves to overcome obstacles and enjoy hilarious mini-games in this Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crayon-shin-chan---nagagutsu-dobon!!-japan-st', 'SNES', 'Crayon Shin-chan - Nagagutsu Dobon!! (Japan) (ST)', '1994', 'Party', 'Game Freak', '1', 'Mini-game collection', 'Educational and puzzle-focused title for the Sufami Turbo accessory.', 'Solve various mini-games and puzzles featuring the Shin-chan cast.', 'Play the rare Crayon Shin-chan: Nagagutsu Dobon!! on SNES.', 'A specialized release for the Sufami Turbo. It offers quick-play puzzle challenges and educational content with the vibrant 16-bit visual style of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crayon-shin-chan-2---daimaou-no-gyakushuu-japan', 'SNES', 'Crayon Shin-chan 2 - Daimaou no Gyakushuu (Japan)', '1994', 'Platformer', 'Banpresto', '1', 'Anime-based platformer', 'Side-scrolling action-platformer with a superhero theme.', 'Defeat the Great Demon King and his minions to save the day.', 'Action-packed fun in Crayon Shin-chan 2: Daimaou no Gyakushuu.', 'The sequel introduces more action elements. Shin-chan can wear different costumes that grant special abilities to tackle creative 16-bit levels and bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crystal-beans-from-dungeon-explorer-japan', 'SNES', 'Crystal Beans From Dungeon Explorer (Japan)', '1994', 'Action RPG', 'Hudson Soft', '2', 'Action RPG dungeon crawler', 'Top-down action-RPG with multi-character cooperative play.', 'Explore dangerous dungeons to recover the magical Crystal Beans.', 'Adventure with friends in Crystal Beans From Dungeon Explorer.', 'A spiritual successor to the Dungeon Explorer series. Choose from diverse character classes and fight through hordes of monsters in this polished 16-bit fantasy JRPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cu-on-pa-sfc-japan', 'SNES', 'Cu-On-Pa SFC (Japan)', '1996', 'Puzzle', 'Nintendo', '2', 'Color-matching puzzle game', 'Isometric puzzle game involving rotating a colored cube to match floor tiles.', 'Match the cube''s top face with the floor color to clear stages.', 'Master the spatial puzzles of Cu-On-Pa SFC for the SNES.', 'A unique and challenging brain-teaser. Players must think several moves ahead to navigate the grid and match colors in this abstract 16-bit puzzle title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cu-on-pa-sfc-japan-en-by-aeon-genesis-v10', 'SNES', 'Cu-On-Pa SFC (Japan) [En by Aeon Genesis v1.0]', '1996', 'Puzzle', 'Nintendo', '2', 'Fan-translated puzzle game', 'Isometric puzzle game involving rotating a colored cube to match floor tiles.', 'Solve the spatial puzzles with a full English interface.', 'Play the English version of the puzzle hit Cu-On-Pa SFC.', 'The definitive fan translation by Aeon Genesis. Experience all the modes and brain-bending levels of this Japanese puzzle gem with fully translated 16-bit text.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cutthroat-island-europe', 'SNES', 'CutThroat Island (Europe)', '1995', 'Action', 'Ocean Software', '2', 'Movie-based action game', 'Side-scrolling action-adventure based on the pirate movie.', 'Find the hidden treasure of CutThroat Island before your rivals.', 'Sail the high seas in CutThroat Island for the Super Nintendo.', 'Choose between Morgan or Shaw and fight through docks, jungles, and ships. Features sword-fighting mechanics and 16-bit platforming based on the film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cutthroat-island-usa', 'SNES', 'CutThroat Island (USA)', '1995', 'Action', 'Ocean Software', '2', 'Movie-based action game', 'Side-scrolling action-adventure based on the pirate movie.', 'Find the hidden treasure of CutThroat Island before your rivals.', 'Sail the high seas in CutThroat Island for the Super Nintendo.', 'A swashbuckling 16-bit experience. Battle pirate crews and use environmental weapons to survive the quest for the legendary gold of CutThroat Island.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyber-knight-japan', 'SNES', 'Cyber Knight (Japan)', '1992', 'RPG', 'Technos Japan', '1', 'Sci-fi turn-based RPG', 'Sci-fi turn-based RPG with tactical combat and deep ship customization.', 'Explore the galaxy and survive an encounter with a hostile alien race.', 'Discover the deep sci-fi RPG Cyber Knight for the SNES.', 'A unique blend of JRPG exploration and strategic mech combat. Manage your crew and upgrade your "Cyber Knight" suits to survive the 16-bit depths of space.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyber-knight-japan-en-by-aeon-genesis-v101', 'SNES', 'Cyber Knight (Japan) [En by Aeon Genesis v1.01]', '1992', 'RPG', 'Technos Japan', '1', 'Fan-translated sci-fi RPG', 'Sci-fi turn-based RPG with tactical combat and deep ship customization.', 'Experience the epic space opera with a full English translation.', 'Play Cyber Knight in English on the Super Nintendo.', 'The Aeon Genesis fan translation allows Western players to enjoy this complex sci-fi story. Master the tactical 16-bit combat and deep customization systems.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyber-knight-ii---chikyuu-teikoku-no-yabou-japan', 'SNES', 'Cyber Knight II - Chikyuu Teikoku no Yabou (Japan)', '1994', 'RPG', 'Technos Japan', '1', 'Sci-fi turn-based RPG sequel', 'Sci-fi turn-based RPG featuring improved graphics and a larger scale.', 'Stop the Terran Empire''s dark ambitions and save the galaxy.', 'The epic sequel: Cyber Knight II on the Super Famicom.', 'Expanding on the original, this sequel features more refined combat and a massive 16-bit narrative. Battle across multiple planets and upgrade your mechs to the limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyber-knight-ii---chikyuu-teikoku-no-yabou-japan-en-by-aeon-genesis-v10-~cyber-knight-ii---ambitions-of-the-terran-empire', 'SNES', 'Cyber Knight II - Chikyuu Teikoku no Yabou (Japan) [En by Aeon Genesis v1.0] (~Cyber Knight II - Ambitions of the Terran Empire)', '1994', 'RPG', 'Technos Japan', '1', 'Fan-translated RPG sequel', 'Sci-fi turn-based RPG featuring improved graphics and a larger scale.', 'Defeat the Terran Empire in this fully translated RPG classic.', 'Experience Cyber Knight II in English on the SNES.', 'A high-quality fan translation that brings the dramatic conclusion of the Cyber Knight saga to English-speaking fans of 16-bit tactical RPGs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyber-spin-usa', 'SNES', 'Cyber Spin (USA)', '1993', 'Puzzle', 'Konami', '2', 'Rotating tile puzzle game', 'Top-down futuristic racing game using Mode 7 for high-speed effects.', 'Win the Grand Prix by mastering futuristic tracks and vehicles.', 'Zoom through the future in Cyber Spin for the Super Nintendo.', 'Known as "Shinseiki GPX Cyber Formula" in Japan. Features high-speed racing, pit stops, and customizable boosts in a vibrant 16-bit sci-fi setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cybernator-europe', 'SNES', 'Cybernator (Europe)', '1992', 'Action', 'NCS', '1', 'Side-scrolling mech action', 'Side-scrolling run-and-gun action featuring a powerful giant mech.', 'Infiltrate enemy bases and destroy the core to stop the war.', 'Pilot the massive mech in Cybernator for the Super Nintendo.', 'Known as "Assault Suits Valken." Experience heavy, tactical mech combat with destructible environments and a gritty 16-bit sci-fi atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cybernator-usa', 'SNES', 'Cybernator (USA)', '1992', 'Action', 'NCS', '1', 'Side-scrolling mech action', 'Side-scrolling run-and-gun action featuring a powerful giant mech.', 'Infiltrate enemy bases and destroy the core to stop the war.', 'Pilot the massive mech in Cybernator for the Super Nintendo.', 'Master the use of the shield and boost jets to survive intense firefights. A landmark 16-bit action title with incredible sprite work and physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cybernator-usa-with-sound-test', 'SNES', 'Cybernator (USA) (With Sound Test)', '1992', 'Action', 'NCS', '1', 'Enhanced version with sound test', 'Side-scrolling run-and-gun action featuring a powerful giant mech.', 'Infiltrate enemy bases and destroy the core to stop the war.', 'Cyberpower! Play Cybernator with a Sound Test mode on SNES.', 'This specific version includes a Sound Test to enjoy the iconic industrial soundtrack alongside the intense 16-bit mech-action gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyborg-009-japan', 'SNES', 'Cyborg 009 (Japan)', '1991', 'Action', 'Riot', '1', 'Anime-based side-scrolling action', 'Side-scrolling action game based on the legendary sci-fi manga.', 'Stop the Black Ghost organization using the unique powers of nine cyborgs.', 'Join the 00-numbered team in Cyborg 009 for the SNES.', 'Switch between different cyborgs to utilize their specialized abilities (speed, strength, vision) to clear challenging 16-bit stages and bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyborg-009-japan-beta', 'SNES', 'Cyborg 009 (Japan) (Beta)', '1991', 'Action', 'Riot', '1', 'Beta anime action game', 'Side-scrolling action game based on the legendary sci-fi manga.', 'Stop the Black Ghost organization using the unique powers of nine cyborgs.', 'Explore the Cyborg 009 Beta version on the Super Nintendo.', 'A pre-release build showing early level designs and character balancing for the 00-team''s 16-bit action-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyborg-009-japan-en-by-aeon-genesis-v10', 'SNES', 'Cyborg 009 (Japan) [En by Aeon Genesis v1.0]', '1991', 'Action', 'Riot', '1', 'Fan-translated anime action', 'Side-scrolling action game based on the legendary sci-fi manga.', 'Experience the complete Cyborg 009 story with an English translation.', 'Play the translated Cyborg 009 action game on SNES.', 'The Aeon Genesis translation brings the classic manga''s 16-bit adaptation to life, allowing players to fully understand the team''s fight for justice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('d-force-usa', 'SNES', 'D-Force (USA)', '1993', 'Shooter', 'Asmik', '2', 'Isometric sci-fi shooter', 'Vertical shoot ''em up with a unique "birds-eye" 3D perspective.', 'Destroy the alien invaders across various planetary environments.', 'Blast through the skies in D-Force for the Super Nintendo.', 'Features a layer-switching mechanic that allows you to fly at different altitudes. Battle massive bosses in this experimental 16-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daffy-duck---the-marvin-missions-europe', 'SNES', 'Daffy Duck - The Marvin Missions (Europe)', '1993', 'Platformer', 'Irem', '1', 'Cartoon platformer', 'Run-and-gun platformer starring Daffy Duck in a sci-fi setting.', 'Defeat Marvin the Martian and save the 24th-and-a-half century.', 'Join the wacky action in Daffy Duck: The Marvin Missions.', 'Play as Duck Dodgers! Use a variety of gadgets and weapons to clear Mars of enemies in this colorful and humorous 16-bit Looney Tunes adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daffy-duck---the-marvin-missions-usa', 'SNES', 'Daffy Duck - The Marvin Missions (USA)', '1993', 'Platformer', 'Irem', '1', 'Cartoon platformer', 'Run-and-gun platformer starring Daffy Duck in a sci-fi setting.', 'Defeat Marvin the Martian and save the 24th-and-a-half century.', 'Join the wacky action in Daffy Duck: The Marvin Missions.', 'Features jetpack mechanics and intense boss fights. Master Daffy''s arsenal to stop Marvin''s galactic plans in this 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dai-3-ji-super-robot-taisen-english-v200', 'SNES', 'Dai-3-ji Super Robot Taisen (English v2.00)', '1993', 'Strategy RPG', 'Winkysoft', '1', 'Tactical mecha RPG', 'Tactical turn-based RPG featuring iconic mechs from various anime series.', 'Lead your robot army to victory in the third installment of the series.', 'Play the English v2.00 of Super Robot Wars 3 on SNES.', 'A refined translation of the massive crossover RPG. Command Gundams, Mazinger Z, and more in epic 16-bit strategic battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dai-3-ji-super-robot-taisen-japan', 'SNES', 'Dai-3-ji Super Robot Taisen (Japan)', '1993', 'Strategy RPG', 'Winkysoft', '1', 'Tactical mecha RPG', 'Tactical turn-based RPG featuring iconic mechs from various anime series.', 'Command a crossover army to defeat an intergalactic threat.', 'Experience the classic Dai-3-ji Super Robot Taisen on SNES.', 'The foundational entry of the "classic" SRW era. Features complex strategy, pilot stats, and iconic 16-bit attack animations for anime fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dai-3-ji-super-robot-taisen-japan-rev-b', 'SNES', 'Dai-3-ji Super Robot Taisen (Japan) (Rev B)', '1993', 'Strategy RPG', 'Winkysoft', '1', 'Revised tactical RPG', 'Tactical turn-based RPG featuring iconic mechs from various anime series.', 'Command a crossover army to defeat an intergalactic threat.', 'Play the updated Rev B version of Super Robot Wars 3.', 'An official Japanese revision that fixed several bugs and balanced unit stats, providing a smoother 16-bit strategic experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dai-3-ji-super-robot-taisen-japan-en-by-aeon-genesis-v10-~super-robot-wars-3', 'SNES', 'Dai-3-ji Super Robot Taisen (Japan) [En by Aeon Genesis v1.0] (~Super Robot Wars 3)', '1993', 'Strategy RPG', 'Winkysoft', '1', 'Fan-translated tactical RPG', 'Tactical turn-based RPG featuring iconic mechs from various anime series.', 'Experience the epic crossover with the Aeon Genesis translation.', 'Super Robot Wars 3 in English: The Aeon Genesis version.', 'The classic fan translation that first opened the world of SRW to Western fans. Lead the "Londo Bell" squad through intense 16-bit missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dai-4-ji-super-robot-taisen-japan', 'SNES', 'Dai-4-ji Super Robot Taisen (Japan)', '1995', 'Strategy RPG', 'Winkysoft', '1', 'Tactical mecha RPG sequel', 'Tactical turn-based RPG featuring the debut of original "Banpresto" characters.', 'Choose your protagonist and lead the mechs through a massive war.', 'Master the strategy of Dai-4-ji Super Robot Taisen on SNES.', 'Often considered the peak of the 16-bit series. Introduces the "Main Character" system and features an enormous roster of mechs and branching story paths.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dai-4-ji-super-robot-taisen-japan-rev-a', 'SNES', 'Dai-4-ji Super Robot Taisen (Japan) (Rev A)', '1995', 'Strategy RPG', 'Winkysoft', '1', 'Revised tactical RPG sequel', 'Tactical turn-based RPG featuring the debut of original "Banpresto" characters.', 'Choose your protagonist and lead the mechs through a massive war.', 'Play the refined Rev A version of Super Robot Wars 4 on SNES.', 'The updated Japanese version with bug fixes and improved unit balance, ensuring the ultimate 16-bit strategy experience for anime and robot fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daibakushou-jinsei-gekijou---dokidoki-seishun-hen-japan', 'SNES', 'Daibakushou Jinsei Gekijou - Dokidoki Seishun Hen (Japan)', '1994', 'Simulation', 'Taito', '1', 'Life simulation board game', 'Digital board game focused on the ups and downs of teenage life.', 'Navigate high school, find love, and graduate with the best stats.', 'Live your youth in Daibakushou Jinsei Gekijou: Dokidoki Seishun.', 'A humorous "Game of Life" style title. Spin the wheel to move across the board, making choices about clubs, exams, and romance in this vibrant 16-bit Japanese simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daibakushou-jinsei-gekijou---ooedo-nikki-japan', 'SNES', 'Daibakushou Jinsei Gekijou - Ooedo Nikki (Japan)', '1993', 'Simulation', 'Taito', '1', 'Japanese life sim board game', 'Digital board game set in the Edo period of Japanese history.', 'Build a successful life as a citizen of old Japan.', 'Travel to old Japan in Daibakushou Jinsei Gekijou: Ooedo Nikki.', 'Experience life as a samurai, merchant, or artisan. This historical board game features era-appropriate mini-games and events with a charming 16-bit aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daibakushou-jinsei-gekijou---zukkoke-salary-man-hen-japan', 'SNES', 'Daibakushou Jinsei Gekijou - Zukkoke Salary Man Hen (Japan)', '1995', 'Simulation', 'Taito', '1', 'Comedy life simulation', 'Digital board game focused on the daily life of a Japanese salaryman.', 'Climb the corporate ladder while managing your family and finances.', 'Survive the office in Daibakushou Jinsei Gekijou: Zukkoke Salary Man.', 'A satirical take on corporate culture. Navigate the board to balance work life, promotions, and weekend activities in this unique 16-bit social simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daibakushou-jinsei-gekijou-japan', 'SNES', 'Daibakushou Jinsei Gekijou (Japan)', '1992', 'Simulation', 'Taito', '1', 'Comedy life simulation', 'Digital board game that simulates an entire lifetime.', 'Make the best life choices to end up the most successful player.', 'The ultimate life sim: Daibakushou Jinsei Gekijou on SNES.', 'The foundational entry in the series. Go from childhood to old age, dealing with careers, marriage, and random events in this fun 16-bit multiplayer experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daikaijuu-monogatari-japan', 'SNES', 'Daikaijuu Monogatari (Japan)', '1994', 'RPG', 'Birthday', '1', 'Traditional Japanese fantasy RPG', 'Turn-based JRPG featuring a massive cast of unique monsters and heroes.', 'Gather the legendary heroes to stop the resurrection of an ancient evil.', 'Experience the epic Daikaijuu Monogatari on the Super Famicom.', 'A classic RPG known for its large roster of playable characters and detailed sprite work. Explore a vast world and master a traditional 16-bit combat system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daikaijuu-monogatari-japan-rev-a', 'SNES', 'Daikaijuu Monogatari (Japan) (Rev A)', '1994', 'RPG', 'Birthday', '1', 'Revised fantasy RPG', 'Turn-based JRPG featuring a massive cast of unique monsters and heroes.', 'Gather the legendary heroes to stop the resurrection of an ancient evil.', 'Experience the epic Daikaijuu Monogatari (Rev A) on SNES.', 'The revised Japanese edition featuring bug fixes and balanced character stats to provide a more polished journey through the world of "Shell Monster Story."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daikaijuu-monogatari-ii-japan', 'SNES', 'Daikaijuu Monogatari II (Japan)', '1996', 'RPG', 'Birthday', '1', 'Traditional fantasy RPG sequel', 'Turn-based JRPG with advanced mechanics and a real-time day/night cycle.', 'Stop the new threat to the world in this massive sequel.', 'Play the visually stunning Daikaijuu Monogatari II on SNES.', 'One of the most technically advanced RPGs on the system. Featuring an internal clock, beautiful animations, and a deep story that spans two 16-bit cartridges worth of content.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daikoukai-jidai-ii-japan', 'SNES', 'Daikoukai Jidai II (Japan)', '1994', 'Simulation', 'Koei', '1', 'Historical naval trading simulation', 'Naval strategy and trading simulation set during the Age of Discovery.', 'Build a fleet, discover new lands, and dominate global trade.', 'Sail the world in the classic Daikoukai Jidai II for SNES.', 'Known as "Uncharted Waters: New Horizons" in the West. Choose one of six characters and live a life of piracy, trade, or exploration in this deep 16-bit sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daisenryaku-expert-japan', 'SNES', 'Daisenryaku Expert (Japan)', '1992', 'Strategy', 'SystemSoft', '1', 'Turn-based military strategy', 'Hex-based tactical military strategy game.', 'Conquer enemy territory using modern 16-bit military units.', 'Master the battlefield in Daisenryaku Expert for SNES.', 'A deep simulation of modern warfare. Manage resources, deploy tanks and aircraft, and use terrain to your advantage to outsmart the AI in this strategic classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daisenryaku-expert-wwii---war-in-europe-japan', 'SNES', 'Daisenryaku Expert WWII - War in Europe (Japan)', '1994', 'Strategy', 'SystemSoft', '1', 'World War II turn-based strategy', 'Hex-based tactical military strategy game set during World War II.', 'Lead your forces to victory in the European theater of WWII.', 'Experience WWII strategy in Daisenryaku Expert WWII on SNES.', 'Command historical units from the 1940s. A detailed and challenging simulation focusing on the tactical maneuvers and resource management of the Great War.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daisys-crazy-adventure', 'SNES', 'Daisy''s Crazy Adventure', '1993', 'Platformer', 'Unknown', '1', 'Unlicensed mascot platformer', 'Unknown', 'Unknown', 'Discover the rare Daisy''s Crazy Adventure for the SNES.', 'Unknown');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('darius-force-japan', 'SNES', 'Darius Force (Japan)', '1993', 'Shooter', 'Taito', '2', 'Horizontal arcade shooter', 'Side-scrolling shoot ''em up with a branching level structure.', 'Navigate through the alien-infested zones to destroy the core.', 'Battle the Belsar fleet in Darius Force for the SNES.', 'Known as "Super Nova" in the West. This entry features unique ship choices and a non-linear path system, all with the series'' iconic robotic sea-creature bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('darius-twin-europe', 'SNES', 'Darius Twin (Europe)', '1993', 'Shooter', 'Taito', '2', 'Horizontal arcade shooter', 'Side-scrolling shoot ''em up with cooperative multiplayer action.', 'Protect the galaxy from the invading Belsar forces.', 'Blast off with Darius Twin, the 16-bit shooter classic.', 'The first Darius game designed specifically for home consoles. Features the trademark robotic fish bosses and a fantastic soundtrack, perfect for two-player 16-bit action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('darius-twin-japan', 'SNES', 'Darius Twin (Japan)', '1993', 'Shooter', 'Taito', '2', 'Horizontal arcade shooter', 'Side-scrolling shoot ''em up with cooperative multiplayer action.', 'Protect the galaxy from the invading Belsar forces.', 'Blast off with Darius Twin, the 16-bit shooter classic.', 'The original Japanese release of the Darius series on the Super Famicom. Experience the intense action and legendary boss fights of this 16-bit arcade-style hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('darius-twin-usa', 'SNES', 'Darius Twin (USA)', '1993', 'Shooter', 'Taito', '2', 'Horizontal arcade shooter', 'Side-scrolling shoot ''em up with cooperative multiplayer action.', 'Protect the galaxy from the invading Belsar forces.', 'Blast off with Darius Twin, the 16-bit shooter classic.', 'Master the power-up system and choose your path through the stars. Darius Twin is a cornerstone of the SNES shooter library, offering high replayability.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-half-japan', 'SNES', 'Dark Half (Japan)', '1996', 'RPG', 'Enix', '1', 'Dark fantasy role-playing game', 'Unique turn-based RPG where you play as both the hero and the villain.', 'Experience the story from two conflicting perspectives to reveal the truth.', 'Explore the duality of Dark Half on the Super Famicom.', 'A dark and atmospheric Enix RPG. One day you play as the hero saving souls, the next as the demon stealing them. A truly innovative 16-bit narrative experiment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-kingdom-japan', 'SNES', 'Dark Kingdom (Japan)', '1996', 'Action', 'Taito', '1', 'Top-down fantasy action game', 'Strategic turn-based RPG with a focus on dark fantasy and unit management.', 'Lead your army through a war-torn kingdom to reclaim your throne.', 'Conquer the darkness in Dark Kingdom for the SNES.', 'Manage a squad of warriors in this tactical RPG. Features a gritty atmosphere and deep character customization as you navigate political intrigue and 16-bit battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-law---meaning-of-death-japan', 'SNES', 'Dark Law - Meaning of Death (Japan)', '1997', 'Action', 'NCS', '1', 'Dark cyberpunk action RPG', 'Tactical JRPG focused on non-linear storytelling and character choices.', 'Investigate a series of dark mysteries across the land.', 'Discover the complex Dark Law: Meaning of Death for SNES.', 'A spiritual successor to "Dark Lord." This title features a unique scenario system and tactical combat, emphasizing player choice in a somber 16-bit world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-law---meaning-of-death-japan-en-by-aeon-genesis-v10', 'SNES', 'Dark Law - Meaning of Death (Japan) [En by Aeon Genesis v1.0]', '1997', 'Action', 'NCS', '1', 'Fan-translated cyberpunk action RPG', 'Tactical JRPG focused on non-linear storytelling and character choices.', 'Experience the dark, atmospheric story with a full English translation.', 'Play Dark Law in English on the Super Nintendo.', 'The Aeon Genesis fan translation brings this deep, non-linear RPG to life. Solve the "Meaning of Death" mystery with fully translated dialogue and tactical 16-bit combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('date-kimiko-no-virtual-tennis-japan', 'SNES', 'Date Kimiko no Virtual Tennis (Japan)', '1993', 'Sports', 'Palsoft', '2', 'Anime-style tennis game', 'Realistic tennis simulation featuring Japanese pro Kimiko Date.', 'Win the international tennis circuit and reach the #1 rank.', 'Play pro tennis in Date Kimiko no Virtual Tennis for SNES.', 'A polished sports title focusing on realism and player positioning. Master various court types and utilize Kimiko Date''s signature playstyle in this 16-bit sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('david-cranes-amazing-tennis-europe', 'SNES', 'David Crane''s Amazing Tennis (Europe)', '1992', 'Sports', 'Imagineering', '2', 'Arcade-style tennis', 'Innovative tennis simulation with a unique "behind the player" 3D view.', 'Win the grand slam tournament through precision and timing.', 'Experience David Crane''s Amazing Tennis on the Super Nintendo.', 'Utilizing advanced scaling techniques, this game offers a groundbreaking perspective for the era. Master the physics-based ball mechanics in this unique 16-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('david-cranes-amazing-tennis-japan', 'SNES', 'David Crane''s Amazing Tennis (Japan)', '1992', 'Sports', 'Imagineering', '2', 'Arcade-style tennis', 'Innovative tennis simulation with a unique "behind the player" 3D view.', 'Win the grand slam tournament through precision and timing.', 'Experience David Crane''s Amazing Tennis on the Super Nintendo.', 'The Japanese edition of the innovative tennis sim. Practice your serve and volley in a 16-bit environment that pioneered the 3D-camera style for sports games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('david-cranes-amazing-tennis-usa', 'SNES', 'David Crane''s Amazing Tennis (USA)', '1992', 'Sports', 'Imagineering', '2', 'Arcade-style tennis', 'Innovative tennis simulation with a unique "behind the player" 3D view.', 'Win the grand slam tournament through precision and timing.', 'Experience David Crane''s Amazing Tennis on the Super Nintendo.', 'Master the various court surfaces and player stats. Features realistic sound effects and a challenging AI that reacts to your 16-bit court strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('day-of-the-muncher', 'SNES', 'Day of the Muncher', '1993', 'Action', 'Unknown', '1', 'Homebrew action game', 'Unknown', 'Unknown', 'Explore the mysterious Day of the Muncher on the SNES.', 'Unknown');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daze-before-christmas-europe', 'SNES', 'Daze Before Christmas (Europe)', '1994', 'Platformer', 'Funcom', '1', 'Christmas-themed platformer', 'Charming side-scrolling platformer with a Christmas theme.', 'Help Santa Claus recover his stolen bag of gifts before Christmas Eve.', 'Save the holidays in Daze Before Christmas for the SNES.', 'Control Santa as he turns enemies into presents. You can even transform into "Anti-Santa" for extra power in this rare and festive 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dead-dance-japan', 'SNES', 'Dead Dance (Japan)', '1993', 'Fighting', 'NCS', '2', 'One-on-one martial arts fighting', 'One-on-one fighting game with a dark, gritty aesthetic.', 'Defeat the world''s strongest fighters to reach the ultimate master.', 'Experience the intense combat of Dead Dance on the SNES.', 'Known as "Tuff E Nuff" in the West. Features a unique leveling system where your moves get stronger as you progress through the 16-bit tower.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deae-tonosama---appare-ichiban-japan', 'SNES', 'Deae Tonosama - Appare Ichiban (Japan)', '1995', 'Action', 'Sunsoft', '1', 'Comedic feudal Japan action game', 'Bizarre and humorous top-down shooter featuring a duo of lords.', 'Cleanse the land of evil using unique "lordly" projectiles.', 'Enjoy the wacky action of Deae Tonosama: Appare Ichiban.', 'A cult classic Japanese shooter. Choose between two eccentric characters and fight through surreal levels filled with humor and vibrant 16-bit graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dear-boys-japan', 'SNES', 'Dear Boys (Japan)', '1993', 'Sports', 'Tose', '2', 'Anime basketball simulation', 'Basketball simulation based on the popular sports manga.', 'Lead your high school team to the national championship.', 'Experience the hoop dreams of Dear Boys on the SNES.', 'A sports title featuring detailed 16-bit sprites and cinematic story sequences. Manage your players'' stamina and execute tactical plays to win the tournament in this manga-inspired basketball sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('death-and-return-of-superman-the-europe', 'SNES', 'Death and Return of Superman, The (Europe)', '1994', 'Beat ''em up', 'Blizzard Entertainment', '2', 'Comic-style superhero brawler', 'Side-scrolling beat ''em up featuring multiple versions of Superman.', 'Defeat Doomsday and the cyborg imposters to restore the true Superman.', 'Experience the epic Death and Return of Superman on SNES.', 'Play as Superman, Superboy, Steel, and more. Use incredible powers like flight and super-strength to fight through 16-bit levels based on the iconic DC Comics storyline.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('death-and-return-of-superman-the-usa', 'SNES', 'Death and Return of Superman, The (USA)', '1994', 'Beat ''em up', 'Blizzard Entertainment', '2', 'Comic-style superhero brawler', 'Side-scrolling beat ''em up featuring multiple versions of Superman.', 'Defeat Doomsday and the cyborg imposters to restore the true Superman.', 'Experience the epic Death and Return of Superman on SNES.', 'A high-stakes brawler with destructible environments. Master each hero''s unique projectiles and melee combos to save Metropolis in this legendary 16-bit action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('death-brade-japan', 'SNES', 'Death Brade (Japan)', '1994', 'Action', 'Data East', '1', 'Dark fantasy hack-and-slash', 'One-on-one fighting game with a mythological and arena combat theme.', 'Defeat the gods and monsters to prove your fighting supremacy.', 'Enter the arena in Death Brade for the Super Famicom.', 'Known as Mutant Fighter in arcades. Choose from creatures like golems or hydras and engage in heavy-hitting combat featuring massive sprites and unique 16-bit grappling mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dekitate-high-school-japan', 'SNES', 'Dekitate High School (Japan)', '1994', 'Adventure', 'Takara', '1', 'High school dating adventure', 'High school life and dating simulation with a focus on education.', 'Balance your studies, clubs, and social life to graduate successfully.', 'Live your school life in Dekitate High School for the SNES.', 'A charming Japanese simulation game. Make daily choices that affect your character''s future, interact with classmates, and experience the nostalgia of 16-bit school days.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('demolition-man-europe', 'SNES', 'Demolition Man (Europe)', '1995', 'Action', 'Virgin Interactive', '1', 'Movie-based action platformer', 'Action-platformer based on the Sylvester Stallone sci-fi movie.', 'Chase down Simon Phoenix across the futuristic city of San Angeles.', 'Fight for the future in Demolition Man for the Super Nintendo.', 'Features both side-scrolling and top-down perspectives. Use a variety of high-tech weapons to neutralize criminals in this explosive 16-bit movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('demolition-man-usa', 'SNES', 'Demolition Man (USA)', '1995', 'Action', 'Virgin Interactive', '1', 'Movie-based action platformer', 'Action-platformer based on the Sylvester Stallone sci-fi movie.', 'Chase down Simon Phoenix across the futuristic city of San Angeles.', 'Fight for the future in Demolition Man for the Super Nintendo.', 'A faithful recreation of the film''s action. Navigate through 16-bit museum and cryo-prison levels, utilizing grenades and rapid-fire weapons to restore order.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('demons-blazon---makaimura-monshou-hen-japan', 'SNES', 'Demon''s Blazon - Makaimura Monshou Hen (Japan)', '1994', 'Action', 'Capcom', '1', 'Dark fantasy action platformer', 'Side-scrolling action-RPG featuring the demon Firebrand.', 'Collect the magical Crests to prevent the ultimate power from falling into evil hands.', 'Discover the dark beauty of Demon''s Blazon on the Super Famicom.', 'The Japanese version of Demon''s Crest. Features gothic 16-bit art, non-linear exploration, and the ability to transform Firebrand into various forms with unique elemental powers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('demons-crest-europe', 'SNES', 'Demon''s Crest (Europe)', '1994', 'Action', 'Capcom', '1', 'Dark fantasy action platformer', 'Side-scrolling action-RPG featuring the demon Firebrand.', 'Collect the magical Crests to prevent the ultimate power from falling into evil hands.', 'Explore the dark world of Demon''s Crest for the SNES.', 'A spin-off of the Ghouls ''n Ghosts series. Master flight, wall-climbing, and diverse breath attacks to uncover secrets in this atmospheric 16-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('demons-crest-usa', 'SNES', 'Demon''s Crest (USA)', '1994', 'Action', 'Capcom', '1', 'Dark fantasy action platformer', 'Side-scrolling action-RPG featuring the demon Firebrand.', 'Collect the magical Crests to prevent the ultimate power from falling into evil hands.', 'Explore the dark world of Demon''s Crest for the SNES.', 'One of the most visually impressive games on the system. Use the Mode 7 world map to find hidden bosses and multiple endings in this deep 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dennis-europe', 'SNES', 'Dennis (Europe)', '1993', 'Platformer', 'Ocean Software', '1', 'Comic-based platformer', 'Side-scrolling platformer based on the mischievous comic strip character.', 'Navigate through various neighborhood levels and escape the grumpy Mr. Wilson.', 'Join the trouble in Dennis for the Super Nintendo.', 'Based on the movie and cartoon. Use your slingshot and agility to overcome obstacles and pranks in this colorful and challenging 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dennis-the-menace-usa', 'SNES', 'Dennis the Menace (USA)', '1993', 'Platformer', 'Ocean Software', '1', 'Comic-based platformer', 'Side-scrolling platformer based on the mischievous comic strip character.', 'Navigate through various neighborhood levels and escape the grumpy Mr. Wilson.', 'Join the trouble in Dennis the Menace for the Super Nintendo.', 'Explore oversized 16-bit environments, collect items, and outsmart bullies in this fun movie tie-in that captures the spirit of the classic character.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('densetsu-no-ogre-battle---the-march-of-the-black-queen-japan', 'SNES', 'Densetsu no Ogre Battle - The March of the Black Queen (Japan)', '1993', 'Strategy RPG', 'Quest', '1', 'Tactical fantasy RPG', 'Grand-scale tactical RPG with a focus on alignment and reputation.', 'Lead a rebellion to liberate the Zenobian Empire from a tyrant.', 'Master the strategy of Ogre Battle: March of the Black Queen.', 'A unique blend of real-time strategy and RPG. Manage units on a map and engage in auto-battles where your choices influence one of 13 possible 16-bit endings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('densetsu-no-ogre-battle---the-march-of-the-black-queen-japan-np', 'SNES', 'Densetsu no Ogre Battle - The March of the Black Queen (Japan) (NP)', '1993', 'Strategy RPG', 'Quest', '1', 'Tactical fantasy RPG', 'Grand-scale tactical RPG with a focus on alignment and reputation.', 'Lead a rebellion to liberate the Zenobian Empire from a tyrant.', 'Experience the Nintendo Power version of Ogre Battle on SNES.', 'A later digital release in Japan via the NP service. Features the same deep strategic gameplay and branching narrative that made this 16-bit title a cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('derby-jockey---kishu-ou-e-no-michi-japan', 'SNES', 'Derby Jockey - Kishu Ou e no Michi (Japan)', '1994', 'Simulation', 'ASCII', '1', 'Horse racing management sim', 'Horse racing simulation focusing on jockey career and stamina management.', 'Climb the ranks of professional racing and win the G1 cup.', 'Ride to victory in Derby Jockey for the Super Famicom.', 'A realistic 16-bit take on horse racing. Balance your speed and positioning during the race while managing your horse''s energy to cross the finish line first.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('derby-jockey---kishu-ou-e-no-michi-japan-rev-a', 'SNES', 'Derby Jockey - Kishu Ou e no Michi (Japan) (Rev A)', '1994', 'Simulation', 'ASCII', '1', 'Horse racing management sim', 'Horse racing simulation focusing on jockey career and stamina management.', 'Climb the ranks of professional racing and win the G1 cup.', 'Ride to victory in Derby Jockey (Rev A) for the SNES.', 'The updated Japanese version with improved AI behavior and minor bug fixes, providing a smoother experience for 16-bit horse racing enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('derby-jockey-2-japan', 'SNES', 'Derby Jockey 2 (Japan)', '1994', 'Simulation', 'ASCII', '1', 'Horse racing management sim', 'Enhanced horse racing simulation with new tracks and breeding mechanics.', 'Become the legendary jockey by winning the most prestigious races.', 'Master the turf in Derby Jockey 2 for the Super Famicom.', 'The sequel adds more depth to the jockey career mode, featuring improved 16-bit visuals and more detailed horse stats for a deeper simulation experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('derby-stallion-96-japan', 'SNES', 'Derby Stallion ''96 (Japan)', '1996', 'Simulation', 'ASCII', '1', 'Horse breeding and racing sim', 'Deep horse breeding and racing management simulation.', 'Breed the ultimate champion horse and win the national derby.', 'Build your racing empire in Derby Stallion ''96 for SNES.', 'The most popular entry in the series. Manage your stable, study bloodlines, and watch your 16-bit horses compete in realistic, high-stakes racing events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('derby-stallion-98-japan-np', 'SNES', 'Derby Stallion ''98 (Japan) (NP)', '1998', 'Simulation', 'ASCII', '1', 'Horse racing simulation', 'Deep horse breeding and racing management simulation.', 'Breed the ultimate champion horse and win the national derby.', 'Experience the late-gen Derby Stallion ''98 on the SNES.', 'Released via the Nintendo Power flash service. Features updated rosters and refined management menus for the ultimate 16-bit horse breeding experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('derby-stallion-ii-japan', 'SNES', 'Derby Stallion II (Japan)', '1994', 'Simulation', 'ASCII', '1', 'Horse racing management sim', 'Horse breeding and management simulation.', 'Train your horses and manage your stable''s finances to reach success.', 'Enter the world of Derby Stallion II on the Super Famicom.', 'Expanding on the original, this sequel introduced more complex breeding combinations and a more detailed 16-bit interface for stable management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('derby-stallion-iii-japan', 'SNES', 'Derby Stallion III (Japan)', '1995', 'Simulation', 'ASCII', '1', 'Horse racing management sim', 'Horse breeding and management simulation.', 'Dominate the Japanese racing circuit with your superior bloodlines.', 'Train winners in Derby Stallion III for the Super Famicom.', 'The third installment features even more realistic racing physics and a wider variety of tracks, solidifying its place as a 16-bit simulation staple.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('derby-stallion-iii-japan-rev-b', 'SNES', 'Derby Stallion III (Japan) (Rev B)', '1995', 'Simulation', 'ASCII', '1', 'Horse racing management sim', 'Horse breeding and management simulation.', 'Dominate the Japanese racing circuit with your superior bloodlines.', 'Play the updated Derby Stallion III (Rev B) on SNES.', 'An official revision that fixed technical glitches in the breeding algorithms, ensuring more accurate 16-bit simulation results for hardcore players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('derby-stallion-iii-japan-rev-d', 'SNES', 'Derby Stallion III (Japan) (Rev D)', '1995', 'Simulation', 'ASCII', '1', 'Horse racing management sim', 'Horse breeding and management simulation.', 'Dominate the Japanese racing circuit with your superior bloodlines.', 'Play the polished Derby Stallion III (Rev D) on SNES.', 'The final revision of the third game, offering the most stable and balanced version of this 16-bit horse management classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desert-fighter---suna-no-arashi-sakusen-japan', 'SNES', 'Desert Fighter - Suna no Arashi Sakusen (Japan)', '1993', 'Action', 'Kemco', '2', 'Top-down helicopter shooter', 'Isometric air combat shooter set in a desert environment.', 'Complete various military missions using an array of fighter jets.', 'Take flight in Desert Fighter: Suna no Arashi Sakusen.', 'Known as Air Cavalry in some regions. Pilot helicopters and jets in 16-bit missions involving escorting, bombing, and dogfighting across desert sands.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desert-fighter-europe', 'SNES', 'Desert Fighter (Europe)', '1993', 'Action', 'Kemco', '2', 'Top-down helicopter shooter', 'Isometric air combat shooter set in a desert environment.', 'Complete various military missions using an array of fighter jets.', 'Experience the intense Air Cavalry action in Desert Fighter.', 'Master the controls of advanced military aircraft. This 16-bit flight sim features diverse mission objectives and a focus on tactical air-to-ground combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desert-fighter-europe-beta', 'SNES', 'Desert Fighter (Europe) (Beta)', '1993', 'Action', 'Kemco', '2', 'Prototype helicopter shooter', 'Isometric air combat shooter set in a desert environment.', 'Complete various military missions using an array of fighter jets.', 'Explore the Desert Fighter Beta version for the SNES.', 'A pre-release build featuring early mission designs and flight physics as they were being developed for the final 16-bit retail release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desert-strike---return-to-the-gulf-europe', 'SNES', 'Desert Strike - Return to the Gulf (Europe)', '1992', 'Action', 'EA', '2', 'Isometric military action', 'Isometric helicopter action-strategy game based on the Gulf War.', 'Complete multiple objectives per mission to destabilize the enemy.', 'Pilot the Apache in Desert Strike: Return to the Gulf on SNES.', 'A classic EA title. Manage fuel, armor, and ammunition while rescuing hostages and destroying key targets in a challenging 16-bit tactical environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desert-strike---return-to-the-gulf-usa', 'SNES', 'Desert Strike - Return to the Gulf (USA)', '1992', 'Action', 'EA', '2', 'Isometric military action', 'Isometric helicopter action-strategy game based on the Gulf War.', 'Complete multiple objectives per mission to destabilize the enemy.', 'Pilot the Apache in Desert Strike: Return to the Gulf on SNES.', 'Navigate large open maps and use strategy to prioritize targets. One of the most successful 16-bit action games, known for its deep gameplay and smooth controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desert-strike---wangan-sakusen-japan', 'SNES', 'Desert Strike - Wangan Sakusen (Japan)', '1992', 'Action', 'EA', '2', 'Japanese version military action', 'Isometric helicopter action-strategy game based on the Gulf War.', 'Complete multiple objectives per mission to destabilize the enemy.', 'Experience the Japanese version, Desert Strike: Wangan Sakusen.', 'The localized release of the hit helicopter sim. Battle through the dunes and urban areas in a high-stakes 16-bit campaign inspired by real-world events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('destructive-japan', 'SNES', 'Destructive (Japan)', '1994', 'Action', 'KSS', '1', 'Dark sci-fi action game', 'Action-puzzle game or shooter with a focus on destruction.', 'Destroy target objects and enemies within the time limit.', 'Unleash chaos in the rare Japanese title Destructive for SNES.', 'A fast-paced 16-bit experience where the goal is to cause as much environmental damage as possible, featuring unique weapon systems and challenging arcade-style levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('devils-course-japan', 'SNES', 'Devil''s Course (Japan)', '1992', 'Sports', 'IGS', '1', 'Golf simulation', 'Realistic golf simulation featuring the fictional and challenging Devil''s Course.', 'Finish each hole under par while navigating treacherous terrain.', 'Conquer the infernal greens in Devil''s Course for the SNES.', 'Known in the West as True Golf Classics: Wicked 18. This 16-bit sim features surreal, fantasy-themed holes with steep cliffs and lava pits that test even the best digital golfers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('devils-course-japan-sample', 'SNES', 'Devil''s Course (Japan) (Sample)', '1992', 'Sports', 'IGS', '1', 'Golf simulation sample build', 'Realistic golf simulation featuring the fictional and challenging Devil''s Course.', 'Experience a pre-release segment of the challenging golf sim.', 'Explore the Devil''s Course Sample version on the Super Famicom.', 'A rare promotional version used in Japanese stores. It features a selection of the most difficult 16-bit holes to showcase the game''s unique environmental physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dharma-doujou-japan', 'SNES', 'Dharma Doujou (Japan)', '1994', 'Fighting', 'SETA', '2', 'Arcade-style martial arts fighting', 'Fast-paced tile-matching puzzle game based on Buddhist themes.', 'Match and clear blocks by pushing them into place before time runs out.', 'Solve the rhythmic puzzles of Dharma Doujou on the SNES.', 'A unique Japanese puzzler where you use a hammer to push blocks. Features a distinct art style and increasing speed that requires quick 16-bit reflexes and pattern recognition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dig-&-spike-volleyball-usa', 'SNES', 'Dig & Spike Volleyball (USA)', '1991', 'Sports', 'Tecmo', '4', 'Arcade volleyball game', 'Arcade-style volleyball simulation featuring both indoor and beach modes.', 'Win the world championship by mastering spikes, blocks, and serves.', 'Experience 16-bit sports action in Dig & Spike Volleyball.', 'Choose between professional indoor teams or casual beach matches. Features responsive controls and specialized special moves for high-energy 16-bit volleyball gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dimension-force-japan', 'SNES', 'Dimension-Force (Japan)', '1991', 'Shooter', 'Asmik', '1', 'Vertical sci-fi shooter', 'Vertical shoot ''em up with a unique perspective-shifting mechanic.', 'Destroy alien forces across multiple atmospheric layers.', 'Blast through the skies in Dimension-Force for the SNES.', 'Known as D-Force in the West. This Japanese version highlights the game''s ability to switch between low and high altitudes using Mode 7-style effects in a 16-bit environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dino-city-europe', 'SNES', 'Dino City (Europe)', '1991', 'Platformer', 'Irem', '1', 'Cute dinosaur platformer', 'Side-scrolling platformer based on the movie "Adventures in Dino City."', 'Navigate through prehistoric worlds to defeat the evil Rocky and his gang.', 'Explore the colorful world of Dino City for the Super Nintendo.', 'Control a kid riding a dinosaur! Use your dino companion''s strength to smash through obstacles and enemies in this vibrant and charming 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dino-city-usa', 'SNES', 'Dino City (USA)', '1991', 'Platformer', 'Irem', '1', 'Cute dinosaur platformer', 'Side-scrolling platformer based on the movie "Adventures in Dino City."', 'Navigate through prehistoric worlds to defeat the evil Rocky and his gang.', 'Explore the colorful world of Dino City for the Super Nintendo.', 'A faithful 16-bit platformer featuring multiple playable characters. Master the unique jumping and attacking mechanics to navigate through treacherous jungle and cave levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dino-dinis-soccer!-europe-enfrde', 'SNES', 'Dino Dini''s Soccer! (Europe) (En,Fr,De)', '1994', 'Sports', 'Dino Dini', '2', 'Arcade soccer simulation', 'Fast-paced soccer simulation with a top-down perspective.', 'Win the international cup by outplaying rival teams with tight controls.', 'Play the high-speed Dino Dini''s Soccer on the SNES.', 'Created by the legend behind Sensible Soccer. Focuses on high-velocity gameplay and precise passing, offering a deep 16-bit tactical experience for football fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dinowars---kyouryuu-oukoku-e-no-daibouken-japan', 'SNES', 'Dinowars - Kyouryuu Oukoku e no Daibouken (Japan)', '1990', 'Action Adventure', 'Jaleco', '1', 'Dinosaur-themed action adventure', 'Action-platformer featuring a boy and his dinosaur friends.', 'Rescue the kingdom from an evil force by mastering elemental powers.', 'Join the adventure in Dinowars: Kyouryuu Oukoku on SNES.', 'A Japanese exclusive that blends platforming with light RPG elements. Switch between different dinosaurs to use their specific 16-bit abilities to solve puzzles and defeat bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dirt-racer-europe-enfrde', 'SNES', 'Dirt Racer (Europe) (En,Fr,De)', '1995', 'Racing', 'Vision Works', '1', 'Off-road motorcycle racing', 'Off-road racing simulation using the Super FX chip for 3D environments.', 'Win the dirt racing circuit by outmaneuvering rivals on bumpy tracks.', 'Experience the 3D speed of Dirt Racer for the Super Nintendo.', 'A rare European release that utilizes the Super FX chip to create 3D terrain. Master the physics of off-road driving in this technically impressive 16-bit racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dirt-trax-fx-europe', 'SNES', 'Dirt Trax FX (Europe)', '1995', 'Racing', 'Nintendo', '2', 'Mode 7 dirt bike racing', 'High-speed motocross racing featuring 3D tracks and 4-player support.', 'Finish first in the motocross championship across various terrains.', 'Race through 3D mud in Dirt Trax FX for the Super Nintendo.', 'Powered by the Super FX chip, this game features polygons to create realistic hills and jumps. A fast-paced 16-bit experience with a unique radical 90s aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dirt-trax-fx-usa', 'SNES', 'Dirt Trax FX (USA)', '1995', 'Racing', 'Nintendo', '2', 'Mode 7 dirt bike racing', 'High-speed motocross racing featuring 3D tracks and 4-player support.', 'Finish first in the motocross championship across various terrains.', 'Race through 3D mud in Dirt Trax FX for the Super Nintendo.', 'Choose from multiple riders and bikes. The FX chip allows for smooth 16-bit 3D perspective changes that were groundbreaking for the time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dixie-kong-country', 'SNES', 'Dixie Kong Country', '1994', 'Platformer', 'Rare', '2', 'Cartoon-style platformer', 'Action-platformer fan modification featuring Dixie Kong in a new quest.', 'Navigate custom levels and defeat enemies using Dixie''s unique hover.', 'Play the fan-made Dixie Kong Country on the Super Nintendo.', 'A creative hack that focuses on Dixie Kong''s gameplay mechanics. Experience new challenges and level layouts in the classic 16-bit Donkey Kong Country engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('do-re-mi-fantasy---milon-no-dokidoki-daibouken-japan', 'SNES', 'Do-Re-Mi Fantasy - Milon no Dokidoki Daibouken (Japan)', '1996', 'Platformer', 'Hudson Soft', '1', 'Colorful fantasy platformer', 'Charming side-scrolling platformer with musical and fantasy themes.', 'Restore music to the world by collecting the magical instruments.', 'Discover the hidden gem Do-Re-Mi Fantasy for the SNES.', 'One of the most beautiful platformers on the system. Play as Milon, using bubbles to trap enemies in a world filled with 16-bit color and incredible sound design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('do-re-mi-fantasy---milon-no-dokidoki-daibouken-japan-en-by-gaijin+rpgone-v10-~do-re-mi-fantasy---milons-quest', 'SNES', 'Do-Re-Mi Fantasy - Milon no Dokidoki Daibouken (Japan) [En by Gaijin+RPGOne v1.0] (~Do-Re-Mi Fantasy - Milon''s Quest)', '1996', 'Platformer', 'Hudson Soft', '1', 'Fan-translated fantasy platformer', 'Charming side-scrolling platformer with musical and fantasy themes.', 'Experience Milon''s epic quest with a full English translation.', 'Play Do-Re-Mi Fantasy in English on the Super Nintendo.', 'The definitive fan translation. Now you can enjoy the whimsical story and creative dialogue of this 16-bit masterpiece that was originally a Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dokapon-3-2-1---arashi-o-yobu-yuujou-japan', 'SNES', 'Dokapon 3-2-1 - Arashi o Yobu Yuujou (Japan)', '1995', 'Board Game', 'Asmik', '4', 'RPG-style board game', 'Hybrid digital board game and turn-based JRPG.', 'Defeat your friends and monsters to become the wealthiest hero.', 'Join the chaotic fun of Dokapon 3-2-1 for the Super Famicom.', 'A cult classic known for destroying friendships. Blend RPG combat with a board game structure, featuring 16-bit humor and competitive sabotage mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dokapon-gaiden---honoo-no-audition-japan', 'SNES', 'Dokapon Gaiden - Honoo no Audition (Japan)', '1996', 'Board Game', 'Asmik', '4', 'RPG-style board game', 'Action-focused spin-off of the Dokapon board game series.', 'Win the "Flame Audition" by outperforming rivals in various challenges.', 'Experience the quirky Dokapon Gaiden on the Super Famicom.', 'A faster-paced take on the series. Features more direct combat and mini-games while maintaining the charming 16-bit art style and competitive spirit of Dokapon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dokuritsu-sensou---liberty-or-death-japan', 'SNES', 'Dokuritsu Sensou - Liberty or Death (Japan)', '1992', 'Strategy', 'Koei', '1', 'Historical war simulation', 'Historical grand strategy simulation set during the American Revolution.', 'Lead either the British or the American forces to victory.', 'Experience the war of independence in Liberty or Death for SNES.', 'A deep Koei simulation. Manage troop movements, political alliances, and budget to win the 16-bit struggle for the future of North America.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dolucky-no-aleague-soccer-japan', 'SNES', 'Dolucky no A.League Soccer (Japan)', '1995', 'Sports', 'Naxat Soft', '2', 'Arcade-style soccer', 'Arcade soccer simulation featuring the cat mascot Dolucky.', 'Win the animal world cup with flashy special moves and high energy.', 'Play the colorful Dolucky no A.League Soccer on SNES.', 'Features incredible 16-bit animations and humorous animal characters. Execute "magic shots" and enjoy the fast-paced, accessible soccer gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dolucky-no-kusayakiu-japan', 'SNES', 'Dolucky no Kusayakiu (Japan)', '1995', 'Sports', 'Naxat Soft', '2', 'Arcade-style baseball', 'Arcade baseball simulation featuring the cat mascot Dolucky.', 'Lead your animal team to the top of the grass baseball league.', 'Step up to the plate in Dolucky no Kusayakiu for SNES.', 'A charming take on baseball. Use special pitches and power-hits in vibrant 16-bit stadiums filled with Dolucky''s quirky friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dolucky-no-puzzle-tour-94-japan', 'SNES', 'Dolucky no Puzzle Tour ''94 (Japan)', '1994', 'Puzzle', 'Naxat Soft', '2', 'Arcade puzzle game', 'Falling-block puzzle game featuring characters from the Dolucky series.', 'Win the puzzle world tour by clearing blocks faster than your rivals.', 'Solve the puzzles in Dolucky no Puzzle Tour ''94 for SNES.', 'A polished 16-bit puzzler with a travel theme. Features great music and various difficulty modes, perfect for fans of competitive tile-matching games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donald-duck-no-mahou-no-boushi-japan', 'SNES', 'Donald Duck no Mahou no Boushi (Japan)', '1995', 'Platformer', 'Disney Interactive', '1', 'Magic-based cartoon platformer', 'Action-platformer featuring Donald Duck in a magical adventure.', 'Find the magical hat to save your nephews and return home.', 'Join the fun in Donald Duck no Mahou no Boushi for SNES.', 'A beautiful Japanese exclusive. Donald can change jobs (like a delivery boy or firefighter) to gain new 16-bit abilities and clear imaginative stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donald-duck-no-maui-mallard-japan', 'SNES', 'Donald Duck no Maui Mallard (Japan)', '1996', 'Platformer', 'Eurocom', '1', 'Exploration-based action platformer', 'Action-platformer starring Donald''s "Maui Mallard" alter ego.', 'Solve the mystery of the missing idol on a tropical island.', 'Experience Maui Mallard''s ninja adventure on the SNES.', 'A visually stunning title where Donald can transform into a ninja. Features smooth 16-bit animation and challenging levels inspired by Disney''s darker side.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donald-in-maui-mallard-europe', 'SNES', 'Donald in Maui Mallard (Europe)', '1996', 'Platformer', 'Eurocom', '1', 'Exploration-based action platformer', 'Action-platformer starring Donald''s "Maui Mallard" alter ego.', 'Solve the mystery of the missing idol on a tropical island.', 'Experience Maui Mallard''s ninja adventure on the SNES.', 'Known as "Cold Shadow" in the USA. Master the staff and projectile weapons to navigate through detailed 16-bit environments and defeat exotic bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country---expert-edition', 'SNES', 'Donkey Kong Country - Expert Edition', '1994', 'Platformer', 'Rare', '2', 'Hard mode platformer hack', 'Side-scrolling platformer with significantly increased difficulty.', 'Complete the classic levels with new, brutal enemy placements.', 'Challenge yourself with Donkey Kong Country: Expert Edition.', 'A hardcore fan modification of the first DKC. Every level has been redesigned to test the reflexes of veteran players, featuring tighter jumps and relentless Kremling positioning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-europe-enfrde', 'SNES', 'Donkey Kong Country (Europe) (En,Fr,De)', '1994', 'Platformer', 'Rare', '2', 'Pre-rendered 2D platformer', 'Groundbreaking platformer featuring pre-rendered 3D graphics.', 'Recover the stolen banana hoard from King K. Rool.', 'Experience the original Donkey Kong Country on the SNES.', 'A technical masterpiece by Rare. Control Donkey and Diddy through jungles, caves, and factories. Features incredible 16-bit music and fluid animations that defined an era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-europe-enfrde-rev-a', 'SNES', 'Donkey Kong Country (Europe) (En,Fr,De) (Rev A)', '1994', 'Platformer', 'Rare', '2', 'Pre-rendered 2D platformer', 'Groundbreaking platformer featuring pre-rendered 3D graphics.', 'Recover the stolen banana hoard from King K. Rool.', 'Experience the original Donkey Kong Country on the SNES.', 'The revised European version, featuring localized text and minor bug fixes to ensure the smoothest 16-bit platforming experience for PAL regions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-usa', 'SNES', 'Donkey Kong Country (USA)', '1994', 'Platformer', 'Rare', '2', 'Pre-rendered 2D platformer', 'Groundbreaking platformer featuring pre-rendered 3D graphics.', 'Recover the stolen banana hoard from King K. Rool.', 'Experience the original Donkey Kong Country on the SNES.', 'One of the best-selling games on the system. Master the "buddy" system to swap between Kongs and find all the hidden bonus rooms in this 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-usa-competition-edition', 'SNES', 'Donkey Kong Country (USA) (Competition Edition)', '1994', 'Platformer', 'Rare', '2', 'Competition-focused platformer', 'Timed score-attack version of the original platformer.', 'Achieve the highest score possible within a five-minute time limit.', 'Play the rare Donkey Kong Country Competition Edition.', 'Originally used for Blockbuster championships. This version features a timer and a scoring system, challenging players to optimize their path through select 16-bit levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-usa-rev-a', 'SNES', 'Donkey Kong Country (USA) (Rev A)', '1994', 'Platformer', 'Rare', '2', 'Pre-rendered 2D platformer', 'Groundbreaking platformer featuring pre-rendered 3D graphics.', 'Recover the stolen banana hoard from King K. Rool.', 'Play the updated Rev A version of Donkey Kong Country.', 'The first major revision for the USA market, fixing several glitches and minor graphical errors found in the initial 16-bit launch version.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-usa-rev-b', 'SNES', 'Donkey Kong Country (USA) (Rev B)', '1994', 'Platformer', 'Rare', '2', 'Pre-rendered 2D platformer', 'Groundbreaking platformer featuring pre-rendered 3D graphics.', 'Recover the stolen banana hoard from King K. Rool.', 'Play the polished Rev B version of Donkey Kong Country.', 'The final official revision of the game, offering the most stable gameplay and addressing rare hardware compatibility issues on the Super Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-2---diddys-kong-kannons', 'SNES', 'Donkey Kong Country 2 - Diddy''s Kong Kannons', '1995', 'Platformer', 'Rare', '2', 'Challenge-focused platformer hack', 'Level-hack focused on barrel-cannon mechanics and precision.', 'Navigate through levels filled with complex cannon puzzles.', 'Master the barrels in DKC2: Diddy''s Kong Kannons.', 'A specialized fan mod for the second game. It emphasizes the barrel-blasting mechanics, requiring perfect timing and spatial awareness to survive the new 16-bit challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-2---diddys-kong-quest-europe-enfr-rev-a', 'SNES', 'Donkey Kong Country 2 - Diddy''s Kong Quest (Europe) (En,Fr) (Rev A)', '1995', 'Platformer', 'Rare', '2', 'Pre-rendered 2D platformer sequel', 'Epic platforming sequel featuring Diddy and Dixie Kong.', 'Rescue Donkey Kong from the clutches of Kaptain K. Rool.', 'Experience the legendary DKC2: Diddy''s Kong Quest.', 'Widely considered the best in the trilogy. Features incredible atmosphere, a haunting soundtrack by David Wise, and the debut of Dixie''s helicopter hair in 16-bit glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-2---diddys-kong-quest-germany-ende', 'SNES', 'Donkey Kong Country 2 - Diddy''s Kong Quest (Germany) (En,De)', '1995', 'Platformer', 'Rare', '2', 'Pre-rendered 2D platformer sequel', 'Epic platforming sequel featuring Diddy and Dixie Kong.', 'Rescue Donkey Kong from the clutches of Kaptain K. Rool.', 'Play Donkey Kong Country 2: Diddy''s Kong Quest (Germany).', 'The German localization of the 16-bit masterpiece. Features translated text and the same iconic gameplay that made the Kongs world-famous.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-2---diddys-kong-quest-germany-ende-rev-a', 'SNES', 'Donkey Kong Country 2 - Diddy''s Kong Quest (Germany) (En,De) (Rev A)', '1995', 'Platformer', 'Rare', '2', 'Pre-rendered 2D platformer sequel', 'Epic platforming sequel featuring Diddy and Dixie Kong.', 'Rescue Donkey Kong from the clutches of Kaptain K. Rool.', 'Play the updated German Rev A version of DKC2.', 'The polished German revision, addressing minor text errors and balancing some of the more difficult 16-bit platforming segments for local players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-2---diddys-kong-quest-usa-enfr', 'SNES', 'Donkey Kong Country 2 - Diddy''s Kong Quest (USA) (En,Fr)', '1995', 'Platformer', 'Rare', '2', 'Pre-rendered 2D platformer sequel', 'Epic platforming sequel featuring Diddy and Dixie Kong.', 'Rescue Donkey Kong from the clutches of Kaptain K. Rool.', 'Experience the definitive DKC2: Diddy''s Kong Quest (USA).', 'Master the teamwork between Diddy and Dixie. Explore Crocodile Isle, collect Kremkoins, and conquer the "Lost World" in this peak 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-2---diddys-kong-quest-usa-enfr-rev-a', 'SNES', 'Donkey Kong Country 2 - Diddy''s Kong Quest (USA) (En,Fr) (Rev A)', '1995', 'Platformer', 'Rare', '2', 'Pre-rendered 2D platformer sequel', 'Epic platforming sequel featuring Diddy and Dixie Kong.', 'Rescue Donkey Kong from the clutches of Kaptain K. Rool.', 'Play the refined USA Rev A version of DKC2.', 'An official revision that fixed several sequence-breaking bugs, ensuring that players experience the 16-bit journey exactly as the developers intended.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-2---diddys-kong-quest-usa-enfr_ixkz-hack-v1-1-beta03', 'SNES', 'Donkey Kong Country 2 - Diddy''s Kong Quest (USA) (En,Fr)_IXKZ HACK-v1-1-beta03', '1995', 'Platformer', 'Rare', '2', 'Difficulty hack platformer', 'Side-scrolling platformer with experimental beta features and tweaks.', 'Rescue Donkey Kong in this modified beta build of DKC2.', 'Explore the DKC2 IXKZ Hack Beta on the Super Nintendo.', 'A technical hack that explores unused assets and experimental physics. A unique way to see the 16-bit mechanics of DKC2 from a different perspective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-2---the-adventure-return', 'SNES', 'Donkey Kong Country 2 - The Adventure Return', '1995', 'Platformer', 'Rare', '2', 'Fan-made story hack', 'Comprehensive fan-made sequel with entirely new level designs.', 'Embark on a new journey to save the Kong family.', 'Play the fan-made Donkey Kong Country 2: The Adventure Return.', 'A massive project that offers a fresh experience using the DKC2 engine. Features creative level layouts and a difficulty curve designed for 16-bit veterans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-2---the-kremlings-revenge', 'SNES', 'Donkey Kong Country 2 - The Kremlings'' Revenge', '1995', 'Platformer', 'Rare', '2', 'Alternate title hack', 'Punishing difficulty mod with redesigned levels and enemy AI.', 'Survive the Kremlings'' most brutal traps and ambushes.', 'Face the challenge of DKC2: The Kremlings'' Revenge.', 'Every level is a test of skill. This hack pushes the DKC2 engine to its limits, requiring pixel-perfect jumps and masterful use of the Kongs'' 16-bit abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-2---the-lost-levels', 'SNES', 'Donkey Kong Country 2 - The Lost Levels', '1995', 'Platformer', 'Rare', '2', 'Restored cut content hack', 'Restoration mod featuring levels and assets that were cut or altered.', 'Explore the "lost" side of Crocodile Isle in this unique mod.', 'Discover the secrets of DKC2: The Lost Levels on SNES.', 'A creative hack that reimagines the game using cut content and new ideas, providing a "what-if" scenario for the 16-bit platforming classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-2-:-hard-as-kongcrete', 'SNES', 'Donkey Kong Country 2 : Hard As Kongcrete', '1995', 'Platformer', 'Rare', '2', 'Extreme difficulty platformer hack', 'Hardcore difficulty hack with a focus on industrial and solid themes.', 'Conquer the hardest versions of the classic DKC2 stages.', 'Test your skill in DKC2: Hard As Kongcrete for SNES.', 'A brutal modification that replaces the standard levels with industrial-strength challenges. Not for the faint of heart, this is 16-bit platforming at its most intense.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-2-unveiled', 'SNES', 'Donkey Kong Country 2 Unveiled', '1995', 'Platformer', 'Rare', '2', 'Content expansion hack', 'Complete level overhaul with new secrets and a revamped difficulty.', 'Uncover the mysteries of Crocodile Isle in this "unveiled" version.', 'Experience the fresh world of Donkey Kong Country 2 Unveiled.', 'A high-quality hack that keeps the spirit of the original but offers entirely new puzzles and level flow, making the 16-bit classic feel brand new.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-2:-brigand-barrage', 'SNES', 'Donkey Kong Country 2: Brigand Barrage', '1995', 'Platformer', 'Rare', '2', 'Custom level hack', 'Boss-rush and combat-focused mod for the second game.', 'Defeat every boss in the game in a specialized arena format.', 'Battle the bosses in DKC2: Brigand Barrage on SNES.', 'Skip the platforming and go straight to the action. This mod tests your combat mastery against all of Kaptain K. Rool''s 16-bit lieutenants.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-3---dixie-kongs-double-trouble!-europe-enfrde', 'SNES', 'Donkey Kong Country 3 - Dixie Kong''s Double Trouble! (Europe) (En,Fr,De)', '1996', 'Platformer', 'Rare', '2', 'Pre-rendered 2D platformer', 'The final entry in the original trilogy featuring Dixie and Kiddy Kong.', 'Search for the missing Donkey and Diddy in the Northern Kremisphere.', 'Explore the Northern Kremisphere in DKC3 for the SNES.', 'Features a more interactive world map and unique vehicle-based exploration. Use Kiddy''s strength and Dixie''s agility to solve new 16-bit puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-3---dixie-kongs-double-trouble!-usa-enfr', 'SNES', 'Donkey Kong Country 3 - Dixie Kong''s Double Trouble! (USA) (En,Fr)', '1996', 'Platformer', 'Rare', '2', 'Pre-rendered 2D platformer', 'The final entry in the original trilogy featuring Dixie and Kiddy Kong.', 'Search for the missing Donkey and Diddy in the Northern Kremisphere.', 'Experience the massive DKC3: Dixie Kong''s Double Trouble.', 'Help the Kongs face off against the mysterious Baron K. Roolenstein. A polished 16-bit finale with some of the most complex secrets in the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-3---dixie-kongs-triple-trouble!', 'SNES', 'Donkey Kong Country 3 - Dixie Kong''s Triple Trouble!', '1996', 'Platformer', 'Rare', '2', 'Custom hack platformer', 'High-difficulty hack of the third game with new level layouts.', 'Rescue the Kongs from even more dangerous mechanical traps.', 'Face the trouble in DKC3: Dixie''s Triple Trouble mod.', 'A total conversion of the third game that increases the stakes. Navigate revamped 16-bit levels that require expert knowledge of Dixie and Kiddy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-3---tag-team-trouble', 'SNES', 'Donkey Kong Country 3 - Tag Team Trouble', '1996', 'Platformer', 'Rare', '2', 'Co-op focused hack', 'Strategic mod focusing on the tag-team mechanic between the Kongs.', 'Navigate through treacherous zones by mastering Kong cooperation.', 'Master the duo in DKC3: Tag Team Trouble on SNES.', 'This hack emphasizes the specific roles of the two Kongs, forcing players to swap and utilize their unique 16-bit physics to progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-3-free-roam-&-open-world', 'SNES', 'Donkey Kong Country 3 Free Roam & Open World', '1996', 'Platformer', 'Rare', '2', 'Open-world experiment hack', 'Non-linear exploration mod that opens the entire game map.', 'Explore the Northern Kremisphere in any order you choose.', 'Play DKC3 Free Roam & Open World on the Super Nintendo.', 'A revolutionary hack that removes the linear progression, allowing you to tackle 16-bit levels and collect items in a completely open-ended fashion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-hack-advanced-god-mode', 'SNES', 'Donkey Kong Country Hack Advanced God Mode', '1994', 'Platformer', 'Rare', '2', 'Cheat-enabled hack', 'Cheat-enabled version of the original game for casual exploration.', 'Explore every secret of the jungle without fear of losing lives.', 'Enjoy the DKC Advanced God Mode mod on the SNES.', 'This hack provides infinite lives and invulnerability, perfect for players who want to appreciate the 16-bit art and music without the stress of the high difficulty.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-kremlings-revenge-remodel', 'SNES', 'Donkey Kong Country Kremling''s Revenge Remodel', '1994', 'Platformer', 'Rare', '2', 'Enemy-focused remix hack', 'Visual and mechanical remodel of the first game''s difficulty hack.', 'Survive the updated Kremling traps in this polished remodel.', 'Experience DKC: Kremling''s Revenge Remodel for SNES.', 'A more balanced and visually consistent version of the classic revenge hack, offering a tough but fair 16-bit platforming challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-mania', 'SNES', 'Donkey Kong Country Mania', '1994', 'Platformer', 'Rare', '2', 'Fan-made remix hack', 'A "Greatest Hits" style level hack for the first DKC.', 'Play through a collection of the most creative fan-made levels.', 'Experience the frantic Donkey Kong Country Mania on SNES.', 'A compilation of high-energy levels that mix and match elements from the entire 16-bit trilogy to create a chaotic new experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country-mirror-edition-god-mode', 'SNES', 'Donkey Kong Country Mirror Edition God Mode', '1994', 'Platformer', 'Rare', '2', 'Mirrored stages hack', 'Unique mod that flips the entire game world horizontally.', 'Relearn the classic levels in this mind-bending mirror version.', 'Test your brain with DKC Mirror Edition God Mode.', 'Everything is backward! This hack flips the 16-bit levels, challenging your muscle memory while providing god-mode powers to help you adjust.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-country:-boss-blitz', 'SNES', 'Donkey Kong Country: Boss Blitz', '1994', 'Platformer', 'Rare', '2', 'Boss rush hack', 'Combat-only mod that takes you directly to the boss encounters.', 'Defeat all of King K. Rool''s henchmen in record time.', 'Face the leaders in Donkey Kong Country: Boss Blitz.', 'A streamlined experience for those who want to practice the boss patterns. Take on the biggest 16-bit threats in the jungle back-to-back.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donkey-kong-distortion-country', 'SNES', 'Donkey Kong Distortion Country', '1994', 'Platformer', 'Rare', '2', 'Glitch-based experimental hack', 'A "glitchy" and surreal aesthetic mod for the first game.', 'Navigate through a distorted and visually strange version of the jungle.', 'Explore the surreal Donkey Kong Distortion Country on SNES.', 'This hack uses graphical corruptions and palette swaps to create a dream-like (or nightmare-like) version of the 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doom-europe', 'SNES', 'Doom (Europe)', '1995', 'Shooter', 'ID Software', '1', 'First-person shooter port', 'First-person shooter featuring a lone marine fighting demonic forces.', 'Survive the Martian moons and defeat the Cyberdemon.', 'Play the technical marvel Doom on the Super Nintendo.', 'A legendary port utilizing the Super FX 2 chip. Blast through Martian corridors and hellish landscapes in this 16-bit rendition of the FPS that defined a generation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doom-japan', 'SNES', 'Doom (Japan)', '1995', 'Shooter', 'ID Software', '1', 'First-person shooter port', 'First-person shooter featuring a lone marine fighting demonic forces.', 'Survive the Martian moons and defeat the Cyberdemon.', 'Experience the Japanese version of Doom on SNES.', 'The Super Famicom release of the seminal shooter. Despite hardware limits, it delivers the full visceral experience of demon-slaying with iconic 16-bit music and sound effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doom-usa', 'SNES', 'Doom (USA)', '1995', 'Shooter', 'ID Software', '1', 'First-person shooter port', 'First-person shooter featuring a lone marine fighting demonic forces.', 'Survive the Martian moons and defeat the Cyberdemon.', 'Experience the legendary FPS Doom on the SNES.', 'Navigate complex levels, manage your ammo, and utilize the iconic BFG9000. A must-play 16-bit conversion for fans of retro action and technical achievements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doom-troopers-usa', 'SNES', 'Doom Troopers (USA)', '1995', 'Action', 'Runic Games', '2', 'Isometric sci-fi shooter', 'Run-and-gun side-scrolling shooter with a dark sci-fi theme.', 'Defeat the legions of the Dark Apostle in this brutal shooter.', 'Join the fight in Doom Troopers for the Super Nintendo.', 'Based on the Mutant Chronicles universe. Features large sprites and intense 16-bit gore as you blast through hordes of mutants across multiple desolate planets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doomsday-warrior-usa', 'SNES', 'Doomsday Warrior (USA)', '1992', 'Fighting', 'Black Pearl', '2', 'One-on-one fighting game', 'One-on-one fighting game featuring customizable warriors.', 'Win the tournament and defeat the ultimate God of War.', 'Challenge the world in Doomsday Warrior for the SNES.', 'A unique 16-bit fighter where you can improve your character''s stats between matches. Master diverse special moves and conquer the "Doomsday" challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon---nobita-to-yousei-no-kuni-japan', 'SNES', 'Doraemon - Nobita to Yousei no Kuni (Japan)', '1993', 'Platformer', 'Epoch', '1', 'Anime-based platformer', 'Side-scrolling platformer featuring the beloved robotic cat.', 'Help Nobita and friends save the Fairy Kingdom from a dark threat.', 'Join the adventure in Doraemon: Nobita to Yousei no Kuni.', 'A charming Japanese exclusive. Use Doraemon’s gadgets to navigate creative 16-bit levels and solve environmental puzzles inspired by the classic manga and anime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon-2---nobita-no-toys-land-daibouken-japan', 'SNES', 'Doraemon 2 - Nobita no Toys Land Daibouken (Japan)', '1994', 'Platformer', 'Epoch', '1', 'Anime-based platformer', 'Action-platformer set in a whimsical toy-themed world.', 'Explore Toys Land and rescue Nobita''s friends from trouble.', 'Discover the magic of Doraemon 2: Nobita no Toys Land.', 'Featuring vibrant 16-bit graphics and a variety of gadgets. Navigate through toy-themed stages and defeat eccentric bosses in this polished Japanese platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon-3---nobita-to-toki-no-hougyoku-japan', 'SNES', 'Doraemon 3 - Nobita to Toki no Hougyoku (Japan)', '1995', 'Adventure', 'Epoch', '1', 'Story-driven adventure platformer', 'Adventure-platformer with a focus on time travel and exploration.', 'Travel through different eras to recover the magical Orbs of Time.', 'Experience the time-traveling fun of Doraemon 3 on SNES.', 'The series evolves with larger levels and more complex gadget uses. A high-quality 16-bit title that captures the spirit of Doraemon''s cinematic adventures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon-4---nobita-to-tsuki-no-oukoku-japan', 'SNES', 'Doraemon 4 - Nobita to Tsuki no Oukoku (Japan)', '1996', 'Adventure', 'Epoch', '1', 'Anime adventure platformer', 'Action-platformer set in a futuristic Moon Kingdom.', 'Save the lunar civilization by mastering new high-tech gadgets.', 'Explore the Moon in Doraemon 4 for the Super Famicom.', 'The final 16-bit entry in the series, featuring the most refined gameplay and detailed sprites. A must-play for fans of Japanese action-platformers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon-4---nobita-to-tsuki-no-oukoku-japan-en-by-sgt-bow-v094b-~doraemon-4---in-the-moon-kingdom', 'SNES', 'Doraemon 4 - Nobita to Tsuki no Oukoku (Japan) [En by Sgt. Bow v0.94b] (~Doraemon 4 - In the Moon Kingdom)', '1996', 'Adventure', 'Epoch', '1', 'Fan-translated anime adventure', 'Action-platformer set in a futuristic Moon Kingdom.', 'Experience Doraemon''s lunar quest with a full English translation.', 'Play Doraemon 4 in English on the Super Nintendo.', 'A dedicated fan translation that allows Western players to follow the charming story and use the futuristic gadgets correctly in this 16-bit moon adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dossun!-ganseki-battle-japan', 'SNES', 'Dossun! Ganseki Battle (Japan)', '1994', 'Puzzle', 'Nintendo', '2', 'Physics-based puzzle game', 'Falling-block puzzle game with a combat twist.', 'Defeat your opponents by dropping rocks and creating combos.', 'Battle with puzzles in Dossun! Ganseki Battle for SNES.', 'A unique 16-bit puzzler where your matches translate into attacks. Choose from various fantasy characters and use strategy to out-puzzle your rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dossun!-ganseki-battle-japan-en-by-aeon-genesis-v10-~dossun!-stone-battle', 'SNES', 'Dossun! Ganseki Battle (Japan) [En by Aeon Genesis v1.0] (~Dossun! Stone Battle)', '1994', 'Puzzle', 'Nintendo', '2', 'Fan-translated puzzle game', 'Falling-block puzzle game with a combat twist.', 'Experience the unique puzzle-combat with a full English translation.', 'Play Dossun! Stone Battle in English on the SNES.', 'The Aeon Genesis translation brings this hidden puzzle gem to English speakers. Master the stone-dropping mechanics and character specials in this 16-bit battle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-dragon-v---the-shadow-falls-europe', 'SNES', 'Double Dragon V - The Shadow Falls (Europe)', '1995', 'Fighting', 'Leland Interactive', '2', 'Western-style fighting game', 'One-on-one fighting game based on the cult animated series.', 'Defeat the Shadow Master and his henchmen to save the city.', 'Fight the shadows in Double Dragon V: The Shadow Falls.', 'A departure from the beat ''em up roots, this entry is a traditional 16-bit fighter. Features a unique cast of characters and a tournament-style progression.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-dragon-v---the-shadow-falls-usa', 'SNES', 'Double Dragon V - The Shadow Falls (USA)', '1995', 'Fighting', 'Leland Interactive', '2', 'Western-style fighting game', 'One-on-one fighting game based on the cult animated series.', 'Defeat the Shadow Master and his henchmen to save the city.', 'Fight the shadows in Double Dragon V: The Shadow Falls.', 'Master the special moves and combos of the Lee brothers in a 16-bit fighting tournament setting. Includes a variety of futuristic arenas and colorful villains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doukyuusei-2-japan-np', 'SNES', 'Doukyuusei 2 (Japan) (NP)', '1995', 'Adventure', 'Elf', '1', 'Dating simulation visual novel', 'Visual novel and dating simulation sequel with a school setting.', 'Manage your social life and build relationships with your classmates.', 'Experience the high school drama of Doukyuusei 2 on SNES.', 'A refined 16-bit visual novel with beautiful artwork and multiple story paths. Navigate the complexities of teenage romance in this popular Japanese simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('down-the-world---mervils-ambition-japan', 'SNES', 'Down the World - Mervil''s Ambition (Japan)', '1992', 'RPG', 'ITL', '1', 'Top-down fantasy RPG', 'Traditional turn-based RPG with a focus on world-building and exploration.', 'Prevent a global catastrophe by fulfilling Mervil''s mysterious ambition.', 'Explore the world of Down the World on the Super Famicom.', 'A visually impressive late-gen RPG. Manage your party, explore detailed 16-bit environments, and engage in tactical battles to save the planet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('downtown-nekketsu-baseball-monogatari---yakyuu-de-shoubu-da!-kunio-kun-japan', 'SNES', 'Downtown Nekketsu Baseball Monogatari - Yakyuu de Shoubu da! Kunio-kun (Japan)', '1993', 'Sports', 'Technos Japan', '2', 'Arcade baseball game', 'Baseball simulation featuring the cast of the Kunio-kun (River City) series.', 'Win the baseball championship using wacky special moves and items.', 'Play the Kunio-kun baseball classic on the SNES.', 'Not your average sports game! Use "hustle" moves and unique 16-bit character abilities to score runs in this humorous and competitive Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon---the-bruce-lee-story-europe', 'SNES', 'Dragon - The Bruce Lee Story (Europe)', '1993', 'Action', 'Virgin Interactive', '1', 'Movie-based martial arts action', 'One-on-one fighting game based on the Bruce Lee biopic film.', 'Defeat legendary masters and overcome Lee''s inner demons.', 'Master the dragon in Dragon: The Bruce Lee Story.', 'Experience Bruce Lee''s philosophy in a 16-bit fighter. Features fluid animations and a difficulty level that honors the legendary martial artist''s skill.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon---the-bruce-lee-story-usa', 'SNES', 'Dragon - The Bruce Lee Story (USA)', '1993', 'Action', 'Virgin Interactive', '1', 'Movie-based martial arts action', 'One-on-one fighting game based on the Bruce Lee biopic film.', 'Defeat legendary masters and overcome Lee''s inner demons.', 'Master the dragon in Dragon: The Bruce Lee Story.', 'Battle through iconic scenes from the movie. Use speed and precision to overcome larger-than-life opponents in this challenging 16-bit combat title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---chomutujeon-korea', 'SNES', 'Dragon Ball Z - Chomutujeon (Korea)', '1993', 'Fighting', 'Bandai', '2', 'Anime fighting game (Korean release)', 'Rare Korean-exclusive Dragon Ball Z fighting game.', 'Defeat the Z-fighters in this unique 16-bit tournament.', 'Discover the rare DBZ: Chomutujeon for the SNES.', 'A fascinating piece of regional history. While mechanically simpler than the Butouden series, it offers a unique 16-bit perspective on the DBZ universe for collectors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---chou-gokuuden---kakusei-hen-japan', 'SNES', 'Dragon Ball Z - Chou Gokuuden - Kakusei Hen (Japan)', '1993', 'RPG', 'Bandai', '1', 'Story-driven Dragon Ball RPG', 'Cinematic adventure/fighting hybrid covering the Cell Saga.', 'Relive Gohan and Goku''s growth as they face the Android threat.', 'Play the cinematic DBZ: Chou Gokuuden Kakusei Hen.', 'A unique RPG-style take on DBZ. Focus on timing and story choices to trigger iconic 16-bit anime sequences during the battle against Cell.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---chou-gokuuden---totsugeki-hen-japan', 'SNES', 'Dragon Ball Z - Chou Gokuuden - Totsugeki Hen (Japan)', '1994', 'RPG', 'Bandai', '1', 'Story-driven Dragon Ball RPG sequel', 'Cinematic adventure/fighting hybrid covering the early Dragon Ball story.', 'Follow Goku''s journey from his first meeting with Bulma.', 'Experience the origins in DBZ: Chou Gokuuden Totsugeki Hen.', 'Focuses on the early humor and action of the series. Use a Rock-Paper-Scissors style 16-bit combat system to relive the classic manga events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---hyper-dimension-france', 'SNES', 'Dragon Ball Z - Hyper Dimension (France)', '1996', 'Fighting', 'Bandai', '2', 'Fast-paced anime fighting game', 'The most advanced 16-bit DBZ fighting game with large sprites.', 'Master the "Hyper" combat system to defeat the strongest warriors.', 'Play the visually stunning DBZ: Hyper Dimension (France).', 'A masterpiece of 16-bit fighting. Features gorgeous animations, stage transitions, and a deep combat system that pushes the SNES hardware to its limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---hyper-dimension-japan', 'SNES', 'Dragon Ball Z - Hyper Dimension (Japan)', '1996', 'Fighting', 'Bandai', '2', 'Fast-paced anime fighting game', 'The most advanced 16-bit DBZ fighting game with large sprites.', 'Master the "Hyper" combat system to defeat the strongest warriors.', 'Experience the original DBZ: Hyper Dimension (Japan).', 'Considered the definitive DBZ game of the era. Includes a deep story mode covering multiple sagas and the most fluid 16-bit combat mechanics in the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---hyper-dimension-japan-en-by-unknown-v10', 'SNES', 'Dragon Ball Z - Hyper Dimension (Japan) [En by Unknown v1.0]', '1996', 'Fighting', 'Bandai', '2', 'Fan-translated anime fighting game', 'The most advanced 16-bit DBZ fighting game with large sprites.', 'Experience the peak of 16-bit DBZ combat with English text.', 'Play the Hyper Dimension English fan translation on SNES.', 'Allows Western fans to fully enjoy the story mode and character interactions in this technically superior 16-bit Dragon Ball Z fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---la-legende-saien-france', 'SNES', 'Dragon Ball Z - La Legende Saien (France)', '1993', 'Fighting', 'Bandai', '2', 'Dragon Ball Z fighting game', 'Traditional 2D fighter featuring the split-screen "Duel" mechanic.', 'Defeat the Saiyan invaders and the tyrant Frieza.', 'Experience the classic DBZ: La Legende Saien on SNES.', 'The French version of Super Butouden 2. Famous for its massive arenas and cinematic special moves that take over the entire 16-bit screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---la-legende-saien-france-en-by-ginew-v20010305-~dragon-ball-z---super-butouden-2-incomplete', 'SNES', 'Dragon Ball Z - La Legende Saien (France) [En by Ginew v20010305] (~Dragon Ball Z - Super Butouden 2) (Incomplete)', '1993', 'Fighting', 'Bandai', '2', 'Incomplete fan translation', 'Traditional 2D fighter featuring the split-screen "Duel" mechanic.', 'Battle through the Frieza and Cell sagas with English text.', 'Play the translated DBZ: La Legende Saien on the SNES.', 'An early English translation effort. While incomplete, it helps fans navigate the menus of this iconic 16-bit split-screen fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---super-butouden-france', 'SNES', 'Dragon Ball Z - Super Butouden (France)', '1992', 'Fighting', 'Bandai', '2', 'Anime fighting game', 'The first DBZ fighting game on the system with 13 playable characters.', 'Win the world tournament and defeat the legendary Super Saiyan.', 'Experience the original DBZ: Super Butouden on SNES.', 'Introduced the famous split-screen mechanic. Battle from afar with energy blasts or up close with 16-bit martial arts in this foundational title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---super-butouden-france-en-by-aeon-genesis-v098-~dragon-ball-z---super-butouden-1-incomplete', 'SNES', 'Dragon Ball Z - Super Butouden (France) [En by Aeon Genesis v0.98] (~Dragon Ball Z - Super Butouden 1) (Incomplete)', '1992', 'Fighting', 'Bandai', '2', 'Incomplete fan translation', 'The first DBZ fighting game on the system with 13 playable characters.', 'Experience the first Butouden game with translated menus.', 'Play the DBZ: Super Butouden English translation on SNES.', 'A fan translation that makes the story mode and menu system accessible to English-speaking 16-bit fighting game fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---super-butouden-japan', 'SNES', 'Dragon Ball Z - Super Butouden (Japan)', '1992', 'Fighting', 'Bandai', '2', 'Original Japanese release', 'The first DBZ fighting game on the system with 13 playable characters.', 'Win the world tournament and defeat the legendary Super Saiyan.', 'Experience the original DBZ: Super Butouden (Japan).', 'Relive the excitement of the first Super Famicom DBZ fighter. Master the flying combat and iconic special moves in this 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---super-butouden-japan-sample', 'SNES', 'Dragon Ball Z - Super Butouden (Japan) (Sample)', '1992', 'Fighting', 'Bandai', '2', 'Sample build', 'The first DBZ fighting game on the system with 13 playable characters.', 'Explore a pre-release version of the first DBZ fighter.', 'Check out the DBZ: Super Butouden Sample version on SNES.', 'A rare Japanese promotional cartridge. It features limited characters and stages, offering a glimpse into the development of the 16-bit DBZ fighting engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---super-butouden-2-japan', 'SNES', 'Dragon Ball Z - Super Butouden 2 (Japan)', '1993', 'Fighting', 'Bandai', '2', 'Sequel anime fighting game', 'Widely considered the best of the Butouden trilogy on SNES.', 'Defeat Broly and Bojack in this epic 16-bit fighting game.', 'Master the combat in DBZ: Super Butouden 2 (Japan).', 'Features an incredible story mode with branching paths, improved split-screen mechanics, and a legendary 16-bit soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---super-butouden-2-japan-rev-a', 'SNES', 'Dragon Ball Z - Super Butouden 2 (Japan) (Rev A)', '1993', 'Fighting', 'Bandai', '2', 'Revised anime fighting game', 'Widely considered the best of the Butouden trilogy on SNES.', 'Defeat Broly and Bojack in the refined Rev A version.', 'Play the polished DBZ: Super Butouden 2 (Rev A) on SNES.', 'An updated Japanese version that fixed several bugs and balanced character stats for a more competitive 16-bit fighting experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---super-butouden-3-japan', 'SNES', 'Dragon Ball Z - Super Butouden 3 (Japan)', '1994', 'Fighting', 'Bandai', '2', 'Anime fighting game sequel', 'Fast-paced fighter focusing on the Buu Saga with a larger roster.', 'Defeat Majin Buu and prove who is the ultimate 16-bit warrior.', 'Blast off in DBZ: Super Butouden 3 (Japan).', 'Removes the story mode to focus on pure arcade action. Features fast gameplay and a high-energy 16-bit tournament mode for Dragon Ball fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---super-gokuu-den---kakusei-hen-japan-en-by-ginew-v20010405-~dragon-ball-z---the-legend-of-goku-2-incomplete', 'SNES', 'Dragon Ball Z - Super Gokuu Den - Kakusei Hen (Japan) [En by Ginew v20010405] (~Dragon Ball Z - The Legend of Goku 2) (Incomplete)', '1994', 'RPG', 'Bandai', '1', 'Incomplete fan-translated RPG', 'Cinematic adventure/fighting hybrid covering the Cell Saga.', 'Experience Gohan''s transformation into a hero with English text.', 'Play the DBZ: The Legend of Goku 2 English mod on SNES.', 'An incomplete but helpful translation of Kakusei Hen. Relive the dramatic moments of the Cell Games in 16-bit cinematic glory.');